// -------------------------------------------------------------------------
// 1. test_create_object
// -------------------------------------------------------------------------

#[test]
fn test_create_object() {
    let obj = JsObject::new(ShapeTable::EMPTY_SHAPE, 3);
    assert_eq!(obj.shape_id, ShapeTable::EMPTY_SHAPE);
    assert_eq!(obj.header.alloc_class, 3);
    assert_eq!(obj.header.flags, 0);
    assert!(obj.is_extensible());
    assert!(!obj.is_frozen());
    assert!(!obj.is_sealed());
    assert!(obj.prototype.is_none());
}

// -------------------------------------------------------------------------
// 2. test_set_get_property
// -------------------------------------------------------------------------

#[test]
fn test_set_get_property() {
    let interner = Interner::new();
    let mut shapes = ShapeTable::new();
    let mut obj = JsObject::new(ShapeTable::EMPTY_SHAPE, 3);

    property::set_property(&mut obj, "x", JsValue::int(42), &mut shapes, &interner).unwrap();

    let val = property::get_property(&obj, "x", &shapes, &interner);
    assert!(val.is_some());
    assert_eq!(val.unwrap().as_int(), Some(42));
}

