// -------------------------------------------------------------------------
// 18. test_function_closure_env
// -------------------------------------------------------------------------

#[test]
fn test_function_closure_env() {
    let env = vec![JsValue::int(10), JsValue::bool(true)];
    let func = JsFunction::new("closure".to_string(), FunctionKind::Arrow, 1).with_env(env);

    assert!(func.env.is_some());
    let captured = func.env.as_ref().unwrap();
    assert_eq!(captured.len(), 2);
    assert_eq!(captured[0].as_int(), Some(10));
    assert_eq!(captured[1].as_bool(), Some(true));
}

// -------------------------------------------------------------------------
// 19. test_runtime_new
// -------------------------------------------------------------------------

#[test]
fn test_runtime_new() {
    let rt = Runtime::new(false);
    assert!(!rt.allocator.is_heap_only());

    let rt_heap = Runtime::new(true);
    assert!(rt_heap.allocator.is_heap_only());

    let rt_default = Runtime::default();
    assert!(!rt_default.allocator.is_heap_only());
}

// -------------------------------------------------------------------------
// 20. test_microtask_ordering
// -------------------------------------------------------------------------

#[test]
fn test_microtask_ordering() {
    use std::sync::{Arc, Mutex};

    let log: Arc<Mutex<Vec<u32>>> = Arc::new(Mutex::new(Vec::new()));
    let mut rt = Runtime::new(false);

    for i in 1..=5 {
        let log_clone = Arc::clone(&log);
        rt.enqueue_microtask(Box::new(move || {
            log_clone.lock().unwrap().push(i);
        }));
    }

    rt.run_microtasks();

    let result = log.lock().unwrap();
    assert_eq!(
        *result,
        vec![1, 2, 3, 4, 5],
        "microtasks must run in FIFO order"
    );
}

