// -------------------------------------------------------------------------
// 40. test_to_boolean_truthy
// -------------------------------------------------------------------------

#[test]
fn test_to_boolean_truthy() {
    assert!(crate::value_ops::to_boolean(JsValue::int(1)));
    assert!(crate::value_ops::to_boolean(JsValue::bool(true)));
    assert!(crate::value_ops::to_boolean(JsValue::number(1.0)));
    assert!(crate::value_ops::to_boolean(JsValue::number(-1.0)));
    // Objects are always truthy (even null pointer as object tag)
    assert!(crate::value_ops::to_boolean(JsValue::object(
        std::ptr::null()
    )));
    // Null-pointer string is treated as empty → falsy (tested in dedicated test below)
}

