// -------------------------------------------------------------------------
// 45. test_typeof_all_types
// -------------------------------------------------------------------------

#[test]
fn test_typeof_all_types() {
    assert_eq!(
        crate::value_ops::js_typeof(JsValue::undefined()),
        "undefined"
    );
    assert_eq!(crate::value_ops::js_typeof(JsValue::null()), "object");
    assert_eq!(crate::value_ops::js_typeof(JsValue::bool(true)), "boolean");
    assert_eq!(crate::value_ops::js_typeof(JsValue::int(1)), "number");
    assert_eq!(crate::value_ops::js_typeof(JsValue::number(2.5)), "number");
    assert_eq!(
        crate::value_ops::js_typeof(JsValue::string(std::ptr::null())),
        "string"
    );
    assert_eq!(crate::value_ops::js_typeof(JsValue::symbol(0)), "symbol");
    assert_eq!(
        crate::value_ops::js_typeof(JsValue::object(std::ptr::null())),
        "object"
    );
}

