// -------------------------------------------------------------------------
// UTF-16 index conversion helpers (string_ops)
// -------------------------------------------------------------------------

#[test]
fn test_utf16_index_to_byte_ascii() {
    assert_eq!(crate::string_ops::utf16_index_to_byte("hello", 0), Some(0));
    assert_eq!(crate::string_ops::utf16_index_to_byte("hello", 3), Some(3));
    assert_eq!(crate::string_ops::utf16_index_to_byte("hello", 5), Some(5));
}

#[test]
fn test_utf16_index_to_byte_emoji() {
    // "\u{1F600}" is 4 bytes in UTF-8, 2 code units in UTF-16.
    let s = "\u{1F600}";
    assert_eq!(crate::string_ops::utf16_index_to_byte(s, 0), Some(0));
    // Index 1 is the low surrogate — no byte boundary.
    assert_eq!(crate::string_ops::utf16_index_to_byte(s, 1), None);
    // Index 2 is past the end of the string (which has 2 UTF-16 code units).
    assert_eq!(crate::string_ops::utf16_index_to_byte(s, 2), Some(4));
}

#[test]
fn test_byte_index_to_utf16_emoji() {
    let s = "a\u{1F600}b";
    // 'a' = byte 0 → UTF-16 index 0
    assert_eq!(crate::string_ops::byte_index_to_utf16(s, 0), Some(0));
    // emoji starts at byte 1 → UTF-16 index 1
    assert_eq!(crate::string_ops::byte_index_to_utf16(s, 1), Some(1));
    // 'b' starts at byte 5 → UTF-16 index 3 (a=0, hi=1, lo=2, b=3)
    assert_eq!(crate::string_ops::byte_index_to_utf16(s, 5), Some(3));
}

#[test]
fn test_char_at_utf16_surrogate_pair() {
    let s = "\u{1F600}";
    assert_eq!(crate::string_ops::char_at_utf16(s, 0), Some(0xD83D));
    assert_eq!(crate::string_ops::char_at_utf16(s, 1), Some(0xDE00));
    assert_eq!(crate::string_ops::char_at_utf16(s, 2), None);
}

#[test]
fn test_slice_utf16_across_emoji() {
    let s = "a\u{1F600}b";
    // Slice the emoji (UTF-16 indices 1..3)
    assert_eq!(crate::string_ops::slice_utf16(s, 1, 3), "\u{1F600}");
    // Slice 'b' (UTF-16 index 3..4)
    assert_eq!(crate::string_ops::slice_utf16(s, 3, 4), "b");
    // Slice 'a' (UTF-16 index 0..1)
    assert_eq!(crate::string_ops::slice_utf16(s, 0, 1), "a");
}

#[test]
fn test_index_of_utf16_returns_utf16_index() {
    let s = "a\u{1F600}b";
    // 'b' is at UTF-16 index 3
    assert_eq!(crate::string_ops::index_of_utf16(s, "b", 0), Some(3));
    // 'a' is at UTF-16 index 0
    assert_eq!(crate::string_ops::index_of_utf16(s, "a", 0), Some(0));
    // Not found
    assert_eq!(crate::string_ops::index_of_utf16(s, "c", 0), None);
}

#[test]
fn test_last_index_of_utf16_returns_utf16_index() {
    let s = "a\u{1F600}ba";
    // Last 'a' is at UTF-16 index 4 (a=0, hi=1, lo=2, b=3, a=4)
    assert_eq!(crate::string_ops::last_index_of_utf16(s, "a"), Some(4));
}

