// -------------------------------------------------------------------------
// 64. test_div_by_zero
// -------------------------------------------------------------------------

#[test]
fn test_div_by_zero() {
    // JS: 1 / 0 → Infinity
    let result = crate::value_ops::js_div(JsValue::int(1), JsValue::int(0));
    assert_eq!(result.as_number(), Some(f64::INFINITY));

    // JS: -1 / 0 → -Infinity
    let result_neg = crate::value_ops::js_div(JsValue::int(-1), JsValue::int(0));
    assert_eq!(result_neg.as_number(), Some(f64::NEG_INFINITY));

    // JS: 0 / 0 → NaN
    let result_nan = crate::value_ops::js_div(JsValue::int(0), JsValue::int(0));
    assert!(result_nan.as_number().unwrap().is_nan());
}

// -------------------------------------------------------------------------
// 65. test_arithmetic_with_undefined_nan_propagation
// -------------------------------------------------------------------------

#[test]
fn test_arithmetic_with_undefined_nan_propagation() {
    // undefined → NaN → NaN propagates through arithmetic
    let result = crate::value_ops::js_add(JsValue::int(1), JsValue::undefined());
    assert!(result.as_number().unwrap().is_nan());

    let result2 = crate::value_ops::js_mul(JsValue::undefined(), JsValue::int(5));
    assert!(result2.as_number().unwrap().is_nan());
}

