fn test_env_nested_depth() {
    let parent = crate::rt_api::__esc_rt_env_create(0, 2);
    crate::rt_api::__esc_rt_env_store(parent, 0, 0, JsValue::int(100).raw_bits());

    let child = crate::rt_api::__esc_rt_env_create(parent, 1);
    crate::rt_api::__esc_rt_env_store(child, 0, 0, JsValue::int(200).raw_bits());

    // Load from child (depth 0)
    let child_val = crate::rt_api::__esc_rt_env_load(child, 0, 0);
    assert_eq!(JsValue::from_raw_bits(child_val).as_int(), Some(200));

    // Load from parent via child (depth 1)
    let parent_val = crate::rt_api::__esc_rt_env_load(child, 1, 0);
    assert_eq!(JsValue::from_raw_bits(parent_val).as_int(), Some(100));
}

