// -------------------------------------------------------------------------
// 96. test_exception_throw_catch
// -------------------------------------------------------------------------

#[test]
fn test_exception_throw_catch() {
    // Clear any previous exception state
    crate::exceptions::clear_exception();

    // No exception initially
    let is_exc = crate::rt_api::__esc_rt_is_exception();
    assert_eq!(JsValue::from_raw_bits(is_exc).as_bool(), Some(false));

    // Begin catch frame
    crate::rt_api::__esc_rt_catch_begin();

    // Throw an exception
    crate::rt_api::__esc_rt_throw(JsValue::int(99).raw_bits());

    // Exception is now pending
    let is_exc2 = crate::rt_api::__esc_rt_is_exception();
    assert_eq!(JsValue::from_raw_bits(is_exc2).as_bool(), Some(true));

    // Get exception value
    let exc_val = crate::rt_api::__esc_rt_get_exception();
    assert_eq!(JsValue::from_raw_bits(exc_val).as_int(), Some(99));

    // End catch frame
    crate::rt_api::__esc_rt_catch_end();

    // Clear for cleanup
    crate::exceptions::clear_exception();
}

