// -------------------------------------------------------------------------
// 99. test_iterator_array_basic
// -------------------------------------------------------------------------

#[test]
fn test_iterator_array_basic() {
    let arr = crate::rt_api::__esc_rt_create_array(0);
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(10).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(20).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(30).raw_bits());

    let iter = crate::rt_api::__esc_rt_iter_init(arr);
    let v = JsValue::from_raw_bits(iter);
    assert!(v.is_object());

    // First element
    let r1 = crate::rt_api::__esc_rt_iter_next(iter);
    let done1 = crate::rt_api::__esc_rt_iter_done(r1);
    let val1 = crate::rt_api::__esc_rt_iter_value(r1);
    assert_eq!(JsValue::from_raw_bits(done1).as_bool(), Some(false));
    assert_eq!(JsValue::from_raw_bits(val1).as_int(), Some(10));

    // Second element
    let r2 = crate::rt_api::__esc_rt_iter_next(iter);
    let val2 = crate::rt_api::__esc_rt_iter_value(r2);
    assert_eq!(JsValue::from_raw_bits(val2).as_int(), Some(20));

    // Third element
    let r3 = crate::rt_api::__esc_rt_iter_next(iter);
    let val3 = crate::rt_api::__esc_rt_iter_value(r3);
    assert_eq!(JsValue::from_raw_bits(val3).as_int(), Some(30));

    // Done
    let r4 = crate::rt_api::__esc_rt_iter_next(iter);
    let done4 = crate::rt_api::__esc_rt_iter_done(r4);
    assert_eq!(JsValue::from_raw_bits(done4).as_bool(), Some(true));

    crate::rt_api::__esc_rt_iter_close(iter);
}

