// -------------------------------------------------------------------------
// 108. test_to_number_string_parsing
// -------------------------------------------------------------------------

#[test]
fn test_to_number_string_parsing() {
    // Empty string → 0
    let empty = make_string_value("");
    let n = crate::rt_api::__esc_rt_to_number(empty);
    assert_eq!(JsValue::from_raw_bits(n).as_number(), Some(0.0));

    // "42" → 42
    let forty_two = make_string_value("42");
    let n2 = crate::rt_api::__esc_rt_to_number(forty_two);
    assert_eq!(JsValue::from_raw_bits(n2).as_number(), Some(42.0));

    // "2.5" → 2.5
    let pi = make_string_value("2.5");
    let n3 = crate::rt_api::__esc_rt_to_number(pi);
    assert_eq!(JsValue::from_raw_bits(n3).as_number(), Some(2.5));

    // "Infinity" → Infinity
    let inf = make_string_value("Infinity");
    let n4 = crate::rt_api::__esc_rt_to_number(inf);
    assert_eq!(JsValue::from_raw_bits(n4).as_number(), Some(f64::INFINITY));

    // "0xFF" → 255
    let hex = make_string_value("0xFF");
    let n5 = crate::rt_api::__esc_rt_to_number(hex);
    assert_eq!(JsValue::from_raw_bits(n5).as_number(), Some(255.0));

    // "abc" → NaN
    let abc = make_string_value("abc");
    let n6 = crate::rt_api::__esc_rt_to_number(abc);
    assert!(JsValue::from_raw_bits(n6).as_number().unwrap().is_nan());
}

