// -------------------------------------------------------------------------
// 119b. test_display_number_scientific_notation
// -------------------------------------------------------------------------

#[test]
fn test_display_number_scientific_notation() {
    // Very large numbers use e+ notation
    assert_eq!(
        crate::display::display_number(f64::MAX),
        "1.7976931348623157e+308"
    );
    // Very small positive subnormal
    assert_eq!(crate::display::display_number(5e-324), "5e-324");
    // Epsilon
    assert_eq!(
        crate::display::display_number(f64::EPSILON),
        "2.220446049250313e-16"
    );
    // Large safe integer (no scientific notation, below 1e20)
    assert_eq!(
        crate::display::display_number(9_007_199_254_740_991.0),
        "9007199254740991"
    );
    assert_eq!(
        crate::display::display_number(-9_007_199_254_740_991.0),
        "-9007199254740991"
    );
}

