// Tagged object / dispatch helper tests
// =========================================================================

use crate::internal_data::{InternalData, InternalKind};
use crate::rt_api::{
    __esc_rt_create_regexp, __esc_rt_get_prop, __esc_rt_regexp_exec, __esc_rt_regexp_test,
    create_array_from_elements, dispatch_array_method, dispatch_array_static_method,
    dispatch_global_namespace_method, dispatch_math_method, dispatch_number_instance_method,
    dispatch_number_static_method, dispatch_regexp_method, dispatch_string_method,
    extract_key_string, format_value_for_join, is_array_prototype_method, make_rt_string,
    normalize_index, read_argv,
};
use crate::string_ops::RtString;
use crate::tagged_obj::{ObjTag, TaggedObj, deref_tagged, free_tagged, read_obj_tag};

// -------------------------------------------------------------------------
// 130. test_tagged_obj_array_round_trip
// -------------------------------------------------------------------------

#[test]
fn test_tagged_obj_array_round_trip() {
    let elems = vec![JsValue::int(10), JsValue::int(20)];
    let arr = UnifiedObject::array(ShapeTable::EMPTY_SHAPE, elems);
    let bits = TaggedObj::boxed(ObjTag::Unified, arr);

    // Verify tag
    assert_eq!(read_obj_tag(bits), Some(ObjTag::Unified as u8));

    // Verify contents via deref
    let uni_ref = unsafe { deref_tagged::<UnifiedObject>(bits) };
    let uni_ref = uni_ref.unwrap();
    assert_eq!(uni_ref.array_len(), 2);
    assert_eq!(uni_ref.get_element(0).unwrap().as_int(), Some(10));
    assert_eq!(uni_ref.get_element(1).unwrap().as_int(), Some(20));

    // Clean up
    unsafe { free_tagged::<UnifiedObject>(bits) };
}

// -------------------------------------------------------------------------
// 131. test_tagged_obj_closure_round_trip
// -------------------------------------------------------------------------

#[test]
fn test_tagged_obj_closure_round_trip() {
    let closure = UnifiedObject::closure(ShapeTable::EMPTY_SHAPE, 42, 0xDEAD, 0);
    let bits = TaggedObj::boxed(ObjTag::Unified, closure);

    assert_eq!(read_obj_tag(bits), Some(ObjTag::Unified as u8));

    let uni_ref = unsafe { deref_tagged::<UnifiedObject>(bits) };
    let uni_ref = uni_ref.unwrap();
    assert_eq!(uni_ref.kind, InternalKind::Closure);
    if let Some(InternalData::Function { code_idx, env, .. }) = uni_ref.internal_data() {
        assert_eq!(*code_idx, 42);
        assert_eq!(*env, 0xDEAD);
    } else {
        panic!("expected Function internal data");
    }

    unsafe { free_tagged::<UnifiedObject>(bits) };
}

