// -------------------------------------------------------------------------
// 143. test_normalize_index_positive
// -------------------------------------------------------------------------

#[test]
fn test_normalize_index_positive() {
    assert_eq!(normalize_index(2, 5), 2);
    assert_eq!(normalize_index(0, 5), 0);
    assert_eq!(normalize_index(5, 5), 5);
    // Beyond length clamps to length
    assert_eq!(normalize_index(10, 5), 5);
}

// -------------------------------------------------------------------------
// 144. test_normalize_index_negative
// -------------------------------------------------------------------------

#[test]
fn test_normalize_index_negative() {
    assert_eq!(normalize_index(-1, 5), 4);
    assert_eq!(normalize_index(-3, 5), 2);
    assert_eq!(normalize_index(-5, 5), 0);
    // Beyond negative clamps to 0
    assert_eq!(normalize_index(-10, 5), 0);
}

