// -------------------------------------------------------------------------
// 147. test_dispatch_array_method_join
// -------------------------------------------------------------------------

#[test]
fn test_dispatch_array_method_join() {
    let bits = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::array(
            ShapeTable::EMPTY_SHAPE,
            vec![JsValue::int(1), JsValue::int(2), JsValue::int(3)],
        ),
    );

    // Default join (comma separator)
    let result = dispatch_array_method(bits, "join", 0, std::ptr::null());
    let val = JsValue::from_raw_bits(result);
    assert!(val.is_string());
    let s = crate::string_ops::get_string_data(val);
    assert_eq!(s, "1,2,3");
    crate::string_ops::free_string(val);

    // Custom separator
    let sep_str = Box::new(RtString::new("-".to_string()));
    let sep_ptr = Box::into_raw(sep_str) as *const ();
    let sep_val = JsValue::string(sep_ptr).raw_bits();
    let args: [u64; 1] = [sep_val];
    let result2 = dispatch_array_method(bits, "join", 1, args.as_ptr());
    let val2 = JsValue::from_raw_bits(result2);
    assert!(val2.is_string());
    let s2 = crate::string_ops::get_string_data(val2);
    assert_eq!(s2, "1-2-3");
    crate::string_ops::free_string(val2);
    crate::string_ops::free_string(JsValue::from_raw_bits(sep_val));

    unsafe { free_tagged::<UnifiedObject>(bits) };
}

