// -------------------------------------------------------------------------
// 161. test_dispatch_string_method_starts_ends_with
// -------------------------------------------------------------------------

#[test]
fn test_dispatch_string_method_starts_ends_with() {
    let rt_str = Box::new(RtString::new("hello world".to_string()));
    let ptr = Box::into_raw(rt_str) as *const ();
    let obj = JsValue::string(ptr).raw_bits();

    let prefix = Box::new(RtString::new("hello".to_string()));
    let prefix_ptr = Box::into_raw(prefix) as *const ();
    let args: [u64; 1] = [JsValue::string(prefix_ptr).raw_bits()];
    let result = dispatch_string_method(obj, "startsWith", 1, args.as_ptr());
    assert_eq!(JsValue::from_raw_bits(result).as_bool(), Some(true));

    let suffix = Box::new(RtString::new("world".to_string()));
    let suffix_ptr = Box::into_raw(suffix) as *const ();
    let args2: [u64; 1] = [JsValue::string(suffix_ptr).raw_bits()];
    let result2 = dispatch_string_method(obj, "endsWith", 1, args2.as_ptr());
    assert_eq!(JsValue::from_raw_bits(result2).as_bool(), Some(true));

    crate::string_ops::free_string(JsValue::from_raw_bits(obj));
    crate::string_ops::free_string(JsValue::string(prefix_ptr));
    crate::string_ops::free_string(JsValue::string(suffix_ptr));
}

// -------------------------------------------------------------------------
// 162. test_closure_env_round_trip
// -------------------------------------------------------------------------

#[test]
fn test_closure_env_round_trip() {
    use crate::internal_data::{InternalData, InternalKind};
    // Default env should be 0
    let env = crate::rt_api::__esc_rt_get_closure_env();
    assert_eq!(env, 0);

    // Create a closure with a known env value and verify it gets set via
    // the create_closure API — now creates a UnifiedObject
    let bits = crate::rt_api::__esc_rt_create_closure(0, 0xCAFE, 0);
    let uni = unsafe { deref_tagged::<UnifiedObject>(bits) }.unwrap();
    assert_eq!(uni.kind, InternalKind::Closure);
    if let Some(InternalData::Function { env, code_idx, .. }) = uni.internal_data() {
        assert_eq!(*env, 0xCAFE);
        assert_eq!(*code_idx, 0);
    } else {
        panic!("expected Function internal data");
    }

    unsafe { free_tagged::<UnifiedObject>(bits) };
}

