/// Create a NaN-boxed string value from a &str (for test use).
fn make_string_value(s: &str) -> u64 {
    let rt_str = Box::new(crate::string_ops::RtString::new(s.to_string()));
    let ptr = Box::into_raw(rt_str) as *const ();
    JsValue::string(ptr).raw_bits()
}

/// Error data extracted from a unified `ErrorObj`.
#[allow(dead_code)]
struct ErrorInfo {
    error_tag: u32,
    message: u64,
    raw_message: u64,
    stack: u64,
}

/// Extract error data from a NaN-boxed value.
///
/// Returns `None` if the value is not a unified error object.
fn extract_error_info(bits: u64) -> Option<ErrorInfo> {
    use crate::internal_data::{InternalData, InternalKind};
    let tag = read_obj_tag(bits)?;
    if tag != ObjTag::Unified as u8 {
        return None;
    }
    let uni = unsafe { deref_tagged::<UnifiedObject>(bits) }?;
    if uni.kind == InternalKind::ErrorObj
        && let Some(InternalData::Error {
            error_tag,
            message,
            raw_message,
            stack,
        }) = uni.internal_data()
    {
        return Some(ErrorInfo {
            error_tag: *error_tag,
            message: *message,
            raw_message: *raw_message,
            stack: *stack,
        });
    }
    None
}

/// Check if a NaN-boxed value is an error object (legacy or unified).
fn is_error_obj(bits: u64) -> bool {
    extract_error_info(bits).is_some()
}

