use crate::proxy::{ProxyObject, TrapResult};

#[test]
fn test_proxy_get_trap() {
    let proxy = ProxyObject::new(100, 200);
    let result = proxy.get(42, |_handler, _target, _key| Some(999)).unwrap();
    assert_eq!(result, TrapResult::Trapped(999));
}

#[test]
fn test_proxy_get_no_trap_fallthrough() {
    let proxy = ProxyObject::new(100, 200);
    let result = proxy.get(42, |_handler, _target, _key| None).unwrap();
    assert_eq!(result, TrapResult::Fallthrough);
}

#[test]
fn test_proxy_set_trap() {
    let mut proxy = ProxyObject::new(100, 200);
    let result = proxy
        .set(42, 999, |_handler, _target, _key, _value| Some(true))
        .unwrap();
    assert_eq!(result, TrapResult::Trapped(1));
}

#[test]
fn test_proxy_set_trap_returns_false() {
    let mut proxy = ProxyObject::new(100, 200);
    let result = proxy
        .set(42, 999, |_handler, _target, _key, _value| Some(false))
        .unwrap();
    assert_eq!(result, TrapResult::Trapped(0));
}

