#[test]
fn test_proxy_revocable() {
    let mut proxy = ProxyObject::new(100, 200);
    assert!(!proxy.revoked);

    // Works before revocation.
    let result = proxy.get(42, |_, _, _| Some(1)).unwrap();
    assert_eq!(result, TrapResult::Trapped(1));

    // Revoke.
    proxy.revoke();
    assert!(proxy.revoked);

    // All operations fail after revocation.
    assert!(proxy.get(42, |_, _, _| Some(1)).is_err());
}

#[test]
fn test_proxy_revoked_set_throws() {
    let mut proxy = ProxyObject::new(100, 200);
    proxy.revoke();
    let err = proxy.set(1, 2, |_, _, _, _| Some(true)).unwrap_err();
    let msg = err.to_string();
    assert!(msg.contains("revoked"));
    assert!(msg.contains("set"));
}

#[test]
fn test_proxy_revoked_has_throws() {
    let mut proxy = ProxyObject::new(100, 200);
    proxy.revoke();
    assert!(proxy.has(1, |_, _, _| Some(true)).is_err());
}

#[test]
fn test_proxy_revoked_delete_throws() {
    let mut proxy = ProxyObject::new(100, 200);
    proxy.revoke();
    assert!(proxy.delete(1, |_, _, _| Some(true)).is_err());
}

#[test]
fn test_proxy_revoked_apply_throws() {
    let proxy = {
        let mut p = ProxyObject::new(100, 200);
        p.revoke();
        p
    };
    assert!(proxy.apply(0, &[], |_, _, _, _| Some(1)).is_err());
}

#[test]
fn test_proxy_revoked_construct_throws() {
    let proxy = {
        let mut p = ProxyObject::new(100, 200);
        p.revoke();
        p
    };
    assert!(proxy.construct(&[], |_, _, _| Some(1)).is_err());
}

#[test]
fn test_proxy_create_revocable() {
    let (proxy, _revoke) = crate::proxy::create_revocable(10, 20);
    assert!(!proxy.revoked);
    assert_eq!(proxy.target, 10);
    assert_eq!(proxy.handler, 20);
}

