#[test]
fn test_proxy_same_value_basic() {
    // Test through proxy_get invariant behavior
    // NaN === NaN should be true in SameValue
    use crate::internal_data::UnifiedObject;
    use crate::proxy::proxy_get;
    use crate::rt_api::{
        __esc_rt_create_object, __esc_rt_create_proxy, __esc_rt_set_prop, INTERNER, SHAPES,
    };
    use crate::tagged_obj::{ObjTag, TaggedObj, deref_tagged_mut};

    let target = __esc_rt_create_object();
    let key_name = "x";

    // Non-configurable, non-writable property with NaN value
    SHAPES.with(|shapes| {
        INTERNER.with(|interner| {
            let mut shapes = shapes.borrow_mut();
            let interner = interner.borrow();
            let tag = crate::tagged_obj::read_obj_tag(target);
            if tag == Some(ObjTag::Unified as u8) {
                let u = unsafe { deref_tagged_mut::<UnifiedObject>(target) }.unwrap();
                let atom = interner.intern(key_name);
                let new_shape =
                    shapes.add_property_with_flags(u.shape_id, atom, false, true, false);
                u.shape_id = new_shape;
                u.slots.push(JsValue::number(f64::NAN));
            }
        })
    });

    // Trap returns NaN (same as target)
    let trap_fn = UnifiedObject::native_func(|_ctx| JsValue::number(f64::NAN).raw_bits(), 0);
    let trap_bits = TaggedObj::boxed(ObjTag::Unified, trap_fn);
    let handler = __esc_rt_create_object();
    __esc_rt_set_prop(handler, make_string_value("get"), trap_bits);

    let proxy = __esc_rt_create_proxy(target, handler);
    let key = make_string_value(key_name);

    // NaN === NaN in SameValue: should succeed
    let result = proxy_get(proxy, key, key_name);
    assert!(result.is_ok());
}

