    // Artificially set depth to max
    set_proxy_depth_for_test(MAX_PROXY_DEPTH);

    // Next proxy operation should fail with MaxDepthExceeded
    use crate::proxy::proxy_is_extensible;
    use crate::rt_api::{__esc_rt_create_object, __esc_rt_create_proxy};

    let target = __esc_rt_create_object();
    let handler = __esc_rt_create_object();
