#[test]
fn test_promise_resolve_immediate() {
    // Promise.resolve(42) creates an immediately fulfilled promise
    let args = [JsValue::int(42).raw_bits()];
    let result = crate::rt_api::dispatch_promise_static_method("resolve", 1, args.as_ptr());
    assert!(result.is_some());
    let prom = result.unwrap();

    // Await should return the resolved value
    let awaited = crate::rt_api::__esc_rt_await(prom);
    assert_eq!(JsValue::from_raw_bits(awaited).as_int(), Some(42));
}

// -------------------------------------------------------------------------
// 177. test_promise_then_fulfilled
// -------------------------------------------------------------------------

#[test]
fn test_promise_then_fulfilled() {
    use crate::promise;

    // Create and resolve a promise
    let p = crate::rt_api::__esc_rt_promise_create();
    crate::rt_api::__esc_rt_promise_resolve(p, JsValue::int(10).raw_bits());

    // .then() on an already-resolved promise enqueues a microtask
    let undef = JsValue::undefined().raw_bits();
    let chained = crate::rt_api::__esc_rt_promise_then(p, undef, undef);
    assert!(JsValue::from_raw_bits(chained).is_object());

    // Drain should propagate the value (since handler is undefined, passthrough)
    promise::drain_microtasks();

    let awaited = crate::rt_api::__esc_rt_await(chained);
    assert_eq!(JsValue::from_raw_bits(awaited).as_int(), Some(10));
}

// -------------------------------------------------------------------------
// 178. test_promise_chain_propagation
// -------------------------------------------------------------------------

#[test]
fn test_promise_chain_propagation() {
    use crate::promise;

    // Create promise, attach two .then() handlers (no handler = passthrough)
    let p = crate::rt_api::__esc_rt_promise_create();
    let undef = JsValue::undefined().raw_bits();
    let chained1 = crate::rt_api::__esc_rt_promise_then(p, undef, undef);
    let chained2 = crate::rt_api::__esc_rt_promise_then(chained1, undef, undef);

    // Resolve the original
    crate::rt_api::__esc_rt_promise_resolve(p, JsValue::int(7).raw_bits());

    // Drain microtasks to propagate through chain
    promise::drain_microtasks();

    let awaited = crate::rt_api::__esc_rt_await(chained2);
    assert_eq!(JsValue::from_raw_bits(awaited).as_int(), Some(7));
}

// -------------------------------------------------------------------------
// 179. test_promise_reject_and_catch
// -------------------------------------------------------------------------

#[test]
fn test_promise_reject_and_catch() {
    use crate::promise;

    let p = crate::rt_api::__esc_rt_promise_create();

    // .catch(handler) is like .then(null, handler)
    // Using no handler = passthrough for rejection
    let caught = crate::rt_api::dispatch_promise_instance_method(p, "catch", 0, std::ptr::null());
    assert!(JsValue::from_raw_bits(caught).is_object());

    // Reject the original promise
    crate::rt_api::__esc_rt_promise_reject(p, JsValue::int(99).raw_bits());

    // Drain microtasks
    promise::drain_microtasks();

    // The caught promise should have the rejected value propagated
    let awaited = crate::rt_api::__esc_rt_await(caught);
    // Since there's no on_reject handler, rejection propagates through
    // and the chained promise is rejected, so __esc_rt_await returns the promise itself
    assert_eq!(awaited, caught);
}

