#[test]
fn test_math_constants() {
    let obj = crate::rt_api::make_rt_string("Math".to_string());

    let e_key = crate::rt_api::make_rt_string("E".to_string());
    let e_val = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(obj, e_key));
    let e_num = e_val.as_number().unwrap();
    assert!((e_num - std::f64::consts::E).abs() < 1e-15);

    let pi_key = crate::rt_api::make_rt_string("PI".to_string());
    let pi_val = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(obj, pi_key));
    let pi_num = pi_val.as_number().unwrap();
    assert!((pi_num - std::f64::consts::PI).abs() < 1e-15);

    let ln2_key = crate::rt_api::make_rt_string("LN2".to_string());
    let ln2_val = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(obj, ln2_key));
    let ln2_num = ln2_val.as_number().unwrap();
    assert!((ln2_num - std::f64::consts::LN_2).abs() < 1e-15);

    let sqrt2_key = crate::rt_api::make_rt_string("SQRT2".to_string());
    let sqrt2_val = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(obj, sqrt2_key));
    let sqrt2_num = sqrt2_val.as_number().unwrap();
    assert!((sqrt2_num - std::f64::consts::SQRT_2).abs() < 1e-15);

    let sqrt12_key = crate::rt_api::make_rt_string("SQRT1_2".to_string());
    let sqrt12_val = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(obj, sqrt12_key));
    let sqrt12_num = sqrt12_val.as_number().unwrap();
    assert!((sqrt12_num - 1.0 / std::f64::consts::SQRT_2).abs() < 1e-15);
}

