#[test]
fn test_exponentiation_operator() {
    // 2 ** 3 = 8
    let result = crate::value_ops::js_exp(JsValue::int(2), JsValue::int(3));
    assert_eq!(result.as_number(), Some(8.0));

    // 2 ** 0 = 1
    let result2 = crate::value_ops::js_exp(JsValue::int(2), JsValue::int(0));
    assert_eq!(result2.as_number(), Some(1.0));

    // 2 ** -1 = 0.5
    let result3 = crate::value_ops::js_exp(JsValue::int(2), JsValue::int(-1));
    assert_eq!(result3.as_number(), Some(0.5));

    // 0 ** 0 = 1 (per IEEE 754)
    let result4 = crate::value_ops::js_exp(JsValue::int(0), JsValue::int(0));
    assert_eq!(result4.as_number(), Some(1.0));

    // (-1) ** 0.5 = NaN
    let result5 = crate::value_ops::js_exp(JsValue::int(-1), JsValue::number(0.5));
    let val = result5.as_number().unwrap();
    assert!(val.is_nan());
}

