#[test]
fn test_math_round_negative_half() {
    // Math.round(-0.5) must return -0 (not 0)
    let args = [JsValue::number(-0.5).raw_bits()];
    let result = dispatch_math_method("round", 1, args.as_ptr());
    let val = JsValue::from_raw_bits(result.unwrap()).as_number().unwrap();
    assert_eq!(val, 0.0);
    assert!(val.is_sign_negative(), "Math.round(-0.5) should be -0");
}

#[test]
fn test_math_round_neg_zero() {
    // Math.round(-0) must return -0
    let args = [JsValue::number(-0.0).raw_bits()];
    let result = dispatch_math_method("round", 1, args.as_ptr());
    let val = JsValue::from_raw_bits(result.unwrap()).as_number().unwrap();
    assert_eq!(val, 0.0);
    assert!(val.is_sign_negative(), "Math.round(-0) should preserve -0");
}

#[test]
fn test_math_max_positive_and_negative_zero() {
    // Math.max(+0, -0) must return +0
    let args = [
        JsValue::number(0.0).raw_bits(),
        JsValue::number(-0.0).raw_bits(),
    ];
    let result = dispatch_math_method("max", 2, args.as_ptr());
    let val = JsValue::from_raw_bits(result.unwrap()).as_number().unwrap();
    assert_eq!(val, 0.0);
    assert!(!val.is_sign_negative(), "Math.max(+0, -0) should return +0");

    // Also test reversed order
    let args2 = [
        JsValue::number(-0.0).raw_bits(),
        JsValue::number(0.0).raw_bits(),
    ];
    let result2 = dispatch_math_method("max", 2, args2.as_ptr());
    let val2 = JsValue::from_raw_bits(result2.unwrap())
        .as_number()
        .unwrap();
    assert!(
        !val2.is_sign_negative(),
        "Math.max(-0, +0) should return +0"
    );
}

