#[test]
fn test_number_is_safe_integer_no_coercion() {
    // Number.isSafeInteger should NOT coerce non-number types
    // true should NOT be coerced to 1
    let args_bool = [JsValue::bool(true).raw_bits()];
    let result = dispatch_number_static_method("isSafeInteger", 1, args_bool.as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(result.unwrap()).as_bool(),
        Some(false),
        "Number.isSafeInteger(true) should be false (no coercion)"
    );

    // null should NOT be coerced to 0
    let args_null = [JsValue::null().raw_bits()];
    let result2 = dispatch_number_static_method("isSafeInteger", 1, args_null.as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(result2.unwrap()).as_bool(),
        Some(false),
        "Number.isSafeInteger(null) should be false (no coercion)"
    );

    // Actual safe integer
    let args_int = [JsValue::int(42).raw_bits()];
    let result3 = dispatch_number_static_method("isSafeInteger", 1, args_int.as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(result3.unwrap()).as_bool(),
        Some(true),
        "Number.isSafeInteger(42) should be true"
    );

    // Number greater than MAX_SAFE_INTEGER
    let args_big = [JsValue::number(9_007_199_254_740_992.0).raw_bits()];
    let result4 = dispatch_number_static_method("isSafeInteger", 1, args_big.as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(result4.unwrap()).as_bool(),
        Some(false),
        "Number.isSafeInteger(2^53) should be false"
    );
}

