// =========================================================================
// UTF-16 correctness tests for string dispatch
// =========================================================================

#[test]
fn test_string_length_emoji() {
    // A single emoji (U+1F600) is 2 UTF-16 code units (surrogate pair).
    let s = make_string_value("\u{1F600}");
    let result = dispatch_string_method(s, "length", 0, std::ptr::null());
    assert_eq!(JsValue::from_raw_bits(result).as_int(), Some(2));
    crate::string_ops::free_string(JsValue::from_raw_bits(s));
}

#[test]
fn test_string_length_mixed_bmp_and_supplementary() {
    // "a" (1 UTF-16 cu) + emoji (2 UTF-16 cu) + "b" (1 UTF-16 cu) = 4
    let s = make_string_value("a\u{1F600}b");
    let result = dispatch_string_method(s, "length", 0, std::ptr::null());
    assert_eq!(JsValue::from_raw_bits(result).as_int(), Some(4));
    crate::string_ops::free_string(JsValue::from_raw_bits(s));
}

#[test]
fn test_string_char_code_at_emoji() {
    // "\u{1F600}" = surrogate pair [0xD83D, 0xDE00]
    let s = make_string_value("\u{1F600}");
    // Index 0: high surrogate
    let args0 = [JsValue::int(0).raw_bits()];
    let result0 = dispatch_string_method(s, "charCodeAt", 1, args0.as_ptr());
    assert_eq!(JsValue::from_raw_bits(result0).as_int(), Some(0xD83D));
    // Index 1: low surrogate
    let args1 = [JsValue::int(1).raw_bits()];
    let result1 = dispatch_string_method(s, "charCodeAt", 1, args1.as_ptr());
    assert_eq!(JsValue::from_raw_bits(result1).as_int(), Some(0xDE00));
    crate::string_ops::free_string(JsValue::from_raw_bits(s));
}

#[test]
fn test_string_code_point_at_emoji() {
    // "\u{1F600}" at UTF-16 index 0 should return the full code point 0x1F600
    let s = make_string_value("\u{1F600}");
    let args0 = [JsValue::int(0).raw_bits()];
    let result0 = dispatch_string_method(s, "codePointAt", 1, args0.as_ptr());
    assert_eq!(JsValue::from_raw_bits(result0).as_int(), Some(0x1F600));
    // Index 1 (low surrogate) should return 0xDE00 (the lone low surrogate)
    let args1 = [JsValue::int(1).raw_bits()];
    let result1 = dispatch_string_method(s, "codePointAt", 1, args1.as_ptr());
    assert_eq!(JsValue::from_raw_bits(result1).as_int(), Some(0xDE00));
    crate::string_ops::free_string(JsValue::from_raw_bits(s));
}

#[test]
fn test_string_index_of_after_emoji() {
    // "a\u{1F600}b" — 'b' is at UTF-16 index 3 (a=0, high=1, low=2, b=3)
    let s = make_string_value("a\u{1F600}b");
    let args = [make_string_value("b")];
    let result = dispatch_string_method(s, "indexOf", 1, args.as_ptr());
    assert_eq!(JsValue::from_raw_bits(result).as_int(), Some(3));
    crate::string_ops::free_string(JsValue::from_raw_bits(s));
    crate::string_ops::free_string(JsValue::from_raw_bits(args[0]));
}

#[test]
fn test_string_slice_utf16_emoji() {
    // "a\u{1F600}b" — slice(1, 3) should extract the emoji (UTF-16 indices 1..3)
    let s = make_string_value("a\u{1F600}b");
    let args = [JsValue::int(1).raw_bits(), JsValue::int(3).raw_bits()];
    let result = dispatch_string_method(s, "slice", 2, args.as_ptr());
    let result_str = crate::string_ops::get_string_data(JsValue::from_raw_bits(result));
    assert_eq!(result_str, "\u{1F600}");
    crate::string_ops::free_string(JsValue::from_raw_bits(s));
    crate::string_ops::free_string(JsValue::from_raw_bits(result));
}

#[test]
fn test_string_substring_utf16_emoji() {
    // "a\u{1F600}b" — substring(3, 4) should extract 'b'
    let s = make_string_value("a\u{1F600}b");
    let args = [JsValue::int(3).raw_bits(), JsValue::int(4).raw_bits()];
    let result = dispatch_string_method(s, "substring", 2, args.as_ptr());
    let result_str = crate::string_ops::get_string_data(JsValue::from_raw_bits(result));
    assert_eq!(result_str, "b");
    crate::string_ops::free_string(JsValue::from_raw_bits(s));
    crate::string_ops::free_string(JsValue::from_raw_bits(result));
}

#[test]
fn test_array_foreach_basic() {
    let elems = vec![JsValue::int(1), JsValue::int(2)];
    let obj = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::array(ShapeTable::EMPTY_SHAPE, elems),
    );
    let callback = JsValue::int(0);
    let args = [callback.raw_bits()];
    let result = dispatch_array_method(obj, "forEach", 1, args.as_ptr());
    assert!(JsValue::from_raw_bits(result).is_undefined());
    unsafe {
        free_tagged::<UnifiedObject>(obj);
    }
}

