#[test]
fn test_create_regexp_with_flags() {
    let re = __esc_rt_create_regexp(make_string_value("hello"), make_string_value("gi"));
    let tag = read_obj_tag(re);
    assert_eq!(tag, Some(ObjTag::Unified as u8));
    // Verify the flags were parsed correctly via unified object's internal data
    let uni = unsafe { deref_tagged::<crate::internal_data::UnifiedObject>(re) };
    let uni = uni.unwrap();
    if let Some(crate::internal_data::InternalData::RegExp { inner }) = uni.internal_data() {
        let re_data = inner.downcast_ref::<JsRegExpData>().unwrap();
        assert!(re_data.inner.flags.global);
        assert!(re_data.inner.flags.ignore_case);
        assert!(!re_data.inner.flags.multiline);
    } else {
        panic!("Expected InternalData::RegExp");
    }
    unsafe {
        free_tagged::<crate::internal_data::UnifiedObject>(re);
    }
}

