// =========================================================================
// RegExp Constructor from Existing RegExp Tests
// =========================================================================

#[test]
fn test_regexp_constructor_from_regexp() {
    use crate::rt_api::call_builtin_constructor;

    // Create original regexp /hello/gi
    let original = __esc_rt_create_regexp(make_string_value("hello"), make_string_value("gi"));

    // new RegExp(existingRegExp) — copies pattern and flags
    let args: [u64; 1] = [original];
    let copy = unsafe { call_builtin_constructor("RegExp", 1, args.as_ptr()) };

    // Verify it's a RegExpObj
    let tag = read_obj_tag(copy);
    assert_eq!(tag, Some(ObjTag::Unified as u8));
    let uni = unsafe { deref_tagged::<UnifiedObject>(copy) };
    assert_eq!(
        uni.unwrap().kind,
        crate::internal_data::InternalKind::RegExpObj
    );

    // Verify source and flags match
    let source = __esc_rt_get_prop(copy, make_string_value("source"));
    assert_eq!(
        crate::string_ops::get_string_data(JsValue::from_raw_bits(source)),
        "hello"
    );
    let flags = __esc_rt_get_prop(copy, make_string_value("flags"));
    assert_eq!(
        crate::string_ops::get_string_data(JsValue::from_raw_bits(flags)),
        "gi"
    );

    unsafe {
        free_tagged::<crate::internal_data::UnifiedObject>(original);
        free_tagged::<crate::internal_data::UnifiedObject>(copy);
    }
}

#[test]
fn test_regexp_constructor_from_regexp_with_new_flags() {
    use crate::rt_api::call_builtin_constructor;

    // Create original regexp /hello/gi
    let original = __esc_rt_create_regexp(make_string_value("hello"), make_string_value("gi"));

    // new RegExp(existingRegExp, "m") — copies pattern, uses new flags
    let args: [u64; 2] = [original, make_string_value("m")];
    let copy = unsafe { call_builtin_constructor("RegExp", 2, args.as_ptr()) };

    // Verify source is the same
    let source = __esc_rt_get_prop(copy, make_string_value("source"));
    assert_eq!(
        crate::string_ops::get_string_data(JsValue::from_raw_bits(source)),
        "hello"
    );

    // Verify flags are the new ones
    let flags = __esc_rt_get_prop(copy, make_string_value("flags"));
    assert_eq!(
        crate::string_ops::get_string_data(JsValue::from_raw_bits(flags)),
        "m"
    );

    // Verify global is now false
    let global = __esc_rt_get_prop(copy, make_string_value("global"));
    assert_eq!(global, JsValue::bool(false).raw_bits());

    // Verify multiline is now true
    let multiline = __esc_rt_get_prop(copy, make_string_value("multiline"));
    assert_eq!(multiline, JsValue::bool(true).raw_bits());

    unsafe {
        free_tagged::<crate::internal_data::UnifiedObject>(original);
        free_tagged::<crate::internal_data::UnifiedObject>(copy);
    }
}

