    let re = __esc_rt_create_regexp(make_string_value("\\d+"), make_string_value("g"));
    let input = make_string_value("abc123def456");
    let args: [u64; 1] = [input];
    let result = dispatch_regexp_method(re, "Symbol.match", 1, args.as_ptr());
    // Global returns array of all matches
    assert_ne!(result, JsValue::null().raw_bits());
    let tag = read_obj_tag(result);
