    crate::rt_api::__esc_rt_set_prop(a, key, b);
    let key = make_string_value("next");
    crate::rt_api::__esc_rt_set_prop(b, key, c);
    let key = make_string_value("next");
    crate::rt_api::__esc_rt_set_prop(c, key, a);

    crate::cycle_integration::register_traceable(a, 1);
    crate::cycle_integration::register_traceable(b, 1);
