#[test]
fn test_rest_args_returns_empty_array_when_no_args() {
    // With no current argv set, rest_args should return an empty array.
    let start_bits = JsValue::number(0.0).raw_bits();
    let result = crate::rt_api::__esc_rt_rest_args(start_bits);
    let len = crate::rt_api::__esc_rt_array_length(result);
    assert_eq!(
        JsValue::from_raw_bits(len).as_number(),
        Some(0.0),
        "rest args with no argv should be empty"
    );
}

#[test]
fn test_rest_args_nan_boxed_start_index() {
    // Ensure the start index is decoded from NaN-boxed bits, not raw u64.
    let start_2 = JsValue::number(2.0).raw_bits();
    let result = crate::rt_api::__esc_rt_rest_args(start_2);
    // With no args set, should still return an empty array (no crash).
    let len = crate::rt_api::__esc_rt_array_length(result);
    assert_eq!(
        JsValue::from_raw_bits(len).as_number(),
        Some(0.0),
        "rest args should decode NaN-boxed start index"
    );
}

#[test]
fn test_rest_args_undefined_start_defaults_to_zero() {
    // If start index is undefined (not a number), default to 0.
    let undef = JsValue::undefined().raw_bits();
    let result = crate::rt_api::__esc_rt_rest_args(undef);
    let len = crate::rt_api::__esc_rt_array_length(result);
    assert_eq!(
        JsValue::from_raw_bits(len).as_number(),
        Some(0.0),
        "rest args with undefined start should default to 0"
    );
}

