#[test]
fn test_spread_into_array_basic() {
    let target = crate::rt_api::__esc_rt_create_empty_array(0);
    let source = crate::rt_api::__esc_rt_create_empty_array(0);
    crate::rt_api::__esc_rt_array_push(source, JsValue::int(1).raw_bits());
    crate::rt_api::__esc_rt_array_push(source, JsValue::int(2).raw_bits());
    crate::rt_api::__esc_rt_array_push(source, JsValue::int(3).raw_bits());

    let result = crate::rt_api::__esc_rt_spread_into_array(target, source);
    // Should return target
    assert_eq!(result, target, "spread should return target array");
    let len = crate::rt_api::__esc_rt_array_length(target);
    assert_eq!(
        JsValue::from_raw_bits(len).as_number(),
        Some(3.0),
        "target should have 3 elements after spread"
    );
}

