#[test]
fn test_instanceof_type_error() {
    let msg = crate::rt_api::make_rt_string("bad arg".to_string());
    let err = crate::rt_api::__esc_rt_create_error(crate::exceptions::error_tag::TYPE_ERROR, msg);
    let ctor = crate::rt_api::make_rt_string("TypeError".to_string());
    let result = crate::rt_api::__esc_rt_instanceof(err, ctor);
    assert_eq!(
        JsValue::from_raw_bits(result).as_bool(),
        Some(true),
        "TypeError instance should be instanceof TypeError"
    );
}

