// -------------------------------------------------------------------------
// Object property: __proto__ chain for class extends
// -------------------------------------------------------------------------

#[test]
fn test_set_proto_creates_prototype_chain() {
    let parent = crate::rt_api::__esc_rt_create_object();
    let parent_name_key = crate::rt_api::make_rt_string("kind".to_string());
    let parent_val = crate::rt_api::make_rt_string("parent".to_string());
    crate::rt_api::__esc_rt_set_prop(parent, parent_name_key, parent_val);

    let child = crate::rt_api::__esc_rt_create_object();
    let proto_key = crate::rt_api::make_rt_string("__proto__".to_string());
    crate::rt_api::__esc_rt_set_prop(child, proto_key, parent);

    // Child should inherit parent's "kind" property through __proto__
    let kind_key = crate::rt_api::make_rt_string("kind".to_string());
    let result = crate::rt_api::__esc_rt_get_prop(child, kind_key);
    let val = JsValue::from_raw_bits(result);
    assert!(val.is_string(), "child should inherit parent's property");
    let s = crate::string_ops::get_string_data(val);
    assert_eq!(s, "parent", "inherited property should be 'parent'");
}

#[test]
fn test_proto_chain_own_property_shadows() {
    let parent = crate::rt_api::__esc_rt_create_object();
    let key = crate::rt_api::make_rt_string("x".to_string());
    crate::rt_api::__esc_rt_set_prop(parent, key, JsValue::int(1).raw_bits());

    let child = crate::rt_api::__esc_rt_create_object();
    let proto_key = crate::rt_api::make_rt_string("__proto__".to_string());
    crate::rt_api::__esc_rt_set_prop(child, proto_key, parent);

    // Set own property on child
    let key2 = crate::rt_api::make_rt_string("x".to_string());
    crate::rt_api::__esc_rt_set_prop(child, key2, JsValue::int(99).raw_bits());

    let key3 = crate::rt_api::make_rt_string("x".to_string());
    let result = crate::rt_api::__esc_rt_get_prop(child, key3);
    assert_eq!(
        JsValue::from_raw_bits(result).as_int(),
        Some(99),
        "own property should shadow inherited property"
    );
}

