// -------------------------------------------------------------------------
// Regression: iter_init on object creates key iterator
// -------------------------------------------------------------------------

#[test]
fn test_iter_init_object_creates_key_iterator() {
    // for-in iteration on objects uses __esc_rt_for_in_init (not iter_init,
    // which is for-of and throws TypeError on non-iterable objects).
    let obj = crate::rt_api::__esc_rt_create_object();
    let key_a = crate::rt_api::make_rt_string("a".to_string());
    crate::rt_api::__esc_rt_set_prop(obj, key_a, JsValue::int(1).raw_bits());
    let key_b = crate::rt_api::make_rt_string("b".to_string());
    crate::rt_api::__esc_rt_set_prop(obj, key_b, JsValue::int(2).raw_bits());

    let iter = crate::rt_api::__esc_rt_for_in_init(obj);
    let tag = crate::tagged_obj::read_obj_tag(iter);
    assert_eq!(
        tag,
        Some(crate::tagged_obj::ObjTag::Unified as u8),
        "iter_init on object should produce Iterator"
    );

    // Should iterate over keys (order may vary, just check count)
    let mut count = 0;
    for _ in 0..10 {
        let r = crate::rt_api::__esc_rt_iter_next(iter);
        let done = crate::rt_api::__esc_rt_iter_done(r);
        if JsValue::from_raw_bits(done).as_bool() == Some(true) {
            break;
        }
        count += 1;
    }
    assert_eq!(count, 2, "object with 2 keys should yield 2 iterations");
}

