// -------------------------------------------------------------------------
// Generator: .next() on a done generator returns {undefined, true}
// Note: In test mode, __esc_dispatch returns undefined (no compiled code).
// The generator_resume function wraps undefined in an iter result.
// -------------------------------------------------------------------------

#[test]
fn test_generator_next_on_done_generator() {
    // Create a generator whose state has state_index = -2 (done)
    let state = crate::rt_api::__esc_rt_create_object();
    let si_key = crate::rt_api::make_rt_string("state_index".to_string());
    crate::rt_api::__esc_rt_set_prop(
        state,
        si_key,
        JsValue::int(crate::generator::STATE_DONE).raw_bits(),
    );
    let generator = crate::rt_api::__esc_rt_create_generator(state, 0);

    // .next() should return {value: undefined, done: true}
    let result = crate::rt_api::__esc_rt_generator_next(generator, JsValue::undefined().raw_bits());
    let tag = crate::tagged_obj::read_obj_tag(result);
    assert_eq!(tag, Some(crate::tagged_obj::ObjTag::Unified as u8));

    let done_key = crate::rt_api::make_rt_string("done".to_string());
    let done = crate::rt_api::__esc_rt_get_prop(result, done_key);
    assert_eq!(JsValue::from_raw_bits(done).as_bool(), Some(true));
}

// -------------------------------------------------------------------------
