// -------------------------------------------------------------------------
// Exception handling: null/undefined property access throws TypeError
// -------------------------------------------------------------------------

#[test]
fn test_get_prop_null_throws_exception() {
    // Ensure no exception is pending before the test
    crate::exceptions::clear_exception();

    let null_val = JsValue::null().raw_bits();
    let key = crate::rt_api::make_rt_string("x".to_string());
    let _result = crate::rt_api::__esc_rt_get_prop(null_val, key);

    assert!(
        crate::exceptions::is_exception(),
        "get_prop on null should set pending exception"
    );

    // Verify it's a TypeError
    let exc = crate::exceptions::get_exception();
    assert!(is_error_obj(exc), "exception should be an error object");
    let info = extract_error_info(exc);
    assert_eq!(
        info.map(|e| e.error_tag),
        Some(crate::exceptions::error_tag::TYPE_ERROR),
        "exception should be a TypeError"
    );
    crate::exceptions::clear_exception();
}

#[test]
fn test_get_prop_undefined_throws_exception() {
    crate::exceptions::clear_exception();

    let undef_val = JsValue::undefined().raw_bits();
    let key = crate::rt_api::make_rt_string("y".to_string());
    let _result = crate::rt_api::__esc_rt_get_prop(undef_val, key);

    assert!(
        crate::exceptions::is_exception(),
        "get_prop on undefined should set pending exception"
    );
    crate::exceptions::clear_exception();
}

#[test]
fn test_has_pending_exception_default_false() {
    crate::exceptions::clear_exception();

    let result = crate::rt_api::__esc_rt_has_pending_exception();
    assert_eq!(result, 0, "no exception should be pending by default");
}

#[test]
fn test_throw_sets_pending_exception() {
    crate::exceptions::clear_exception();

    let msg = crate::rt_api::make_rt_string("test error".to_string());
    let err = crate::rt_api::__esc_rt_create_error(0, msg);
    crate::rt_api::__esc_rt_throw(err);

    let result = crate::rt_api::__esc_rt_has_pending_exception();
    assert_eq!(result, 1, "exception should be pending after throw");

    crate::exceptions::clear_exception();
}

#[test]
fn test_catch_begin_end_clears_exception() {
    crate::exceptions::clear_exception();

    // Push catch frame
    let _initial = crate::rt_api::__esc_rt_catch_begin();

    // Throw inside the catch frame
    let msg = crate::rt_api::make_rt_string("test".to_string());
    let err = crate::rt_api::__esc_rt_create_error(0, msg);
    crate::rt_api::__esc_rt_throw(err);

    assert!(
        crate::exceptions::is_exception(),
        "exception should be pending after throw"
    );

    // Get exception
    let exc = crate::rt_api::__esc_rt_get_exception();
    assert_ne!(
        exc,
        JsValue::undefined().raw_bits(),
        "get_exception should return the thrown value"
    );

    // Pop catch frame
    crate::rt_api::__esc_rt_catch_end();

    // Manually clear exception (like a catch block would)
    crate::exceptions::clear_exception();
    assert!(
        !crate::exceptions::is_exception(),
        "exception should be cleared after clear_exception"
    );
}

