#[test]
fn test_strict_eq_minus_zero_plus_zero() {
    // In JS, -0 === +0 is true (IEEE 754)
    let pos = JsValue::int(0);
    let neg = JsValue::number(-0.0);
    assert!(
        crate::value_ops::strict_eq(pos, neg),
        "+0 === -0 should be true"
    );
    assert!(
        crate::value_ops::strict_eq(neg, pos),
        "-0 === +0 should be true"
    );
    // Both as number type
    assert!(
        crate::value_ops::strict_eq(JsValue::number(0.0), JsValue::number(-0.0)),
        "number(0.0) === number(-0.0) should be true"
    );
}

#[test]
fn test_strict_eq_nan_self() {
    // NaN !== NaN for any representation
    let nan1 = JsValue::number(f64::NAN);
    let nan2 = JsValue::number(f64::NAN);
    assert!(
        !crate::value_ops::strict_eq(nan1, nan2),
        "NaN !== NaN should hold"
    );
    assert!(
        !crate::value_ops::strict_eq(nan1, nan1),
        "NaN !== NaN even with same binding"
    );
}

#[test]
fn test_strict_eq_different_objects() {
    // Two distinct objects are never ===
    let a = JsValue::object(std::ptr::NonNull::<u64>::dangling().as_ptr() as *const ());
    let b = JsValue::object(std::ptr::NonNull::<u16>::dangling().as_ptr() as *const ());
    assert!(
        !crate::value_ops::strict_eq(a, b),
        "distinct objects should not be ==="
    );
}

#[test]
fn test_strict_eq_same_object() {
    // Same object pointer is ===
    let a = JsValue::object(std::ptr::NonNull::<u64>::dangling().as_ptr() as *const ());
    assert!(
        crate::value_ops::strict_eq(a, a),
        "same object should be ==="
    );
}

/// Helper to read `.length` from an arguments object via property access.
fn args_get_length(args_bits: u64) -> i32 {
    let length_key = crate::rt_api::make_rt_string("length".to_string());
    let len = crate::rt_api::__esc_rt_get_prop(args_bits, length_key);
    let v = JsValue::from_raw_bits(len);
    // Length may be stored as int or f64
    if let Some(i) = v.as_int() {
        i
    } else if let Some(n) = v.as_number() {
        n as i32
    } else {
        -1
    }
}

/// Helper to read `.callee` from an arguments object via property access.
fn args_get_callee(args_bits: u64) -> u64 {
    let callee_key = crate::rt_api::make_rt_string("callee".to_string());
    crate::rt_api::__esc_rt_get_prop(args_bits, callee_key)
}

#[test]
fn test_create_arguments_empty() {
    // With no args set (default: argc=0, argv=null), create_arguments returns
    // an ordinary object with length=0.
    unsafe { crate::rt_api::set_current_args(0, std::ptr::null()) };
    crate::rt_api::set_current_callee(0);
    let result = crate::rt_api::__esc_rt_create_arguments();
    assert_eq!(
        args_get_length(result),
        0,
        "arguments with no args should have length 0"
    );
}

#[test]
fn test_create_arguments_with_values() {
    // Set up 3 arguments, verify they appear as indexed properties.
    let args = [
        JsValue::int(10).raw_bits(),
        JsValue::int(20).raw_bits(),
        JsValue::int(30).raw_bits(),
    ];
    unsafe { crate::rt_api::set_current_args(3, args.as_ptr()) };
    crate::rt_api::set_current_callee(0);
    let result = crate::rt_api::__esc_rt_create_arguments();

    // Verify length is 3
    assert_eq!(args_get_length(result), 3, "arguments should have length 3");

    // Verify individual elements via get_prop with numeric keys
    let idx0 = JsValue::int(0).raw_bits();
    let idx1 = JsValue::int(1).raw_bits();
    let idx2 = JsValue::int(2).raw_bits();
    let v0 = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(result, idx0));
    let v1 = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(result, idx1));
    let v2 = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(result, idx2));
    assert_eq!(v0.as_int(), Some(10), "arguments[0] should be 10");
    assert_eq!(v1.as_int(), Some(20), "arguments[1] should be 20");
    assert_eq!(v2.as_int(), Some(30), "arguments[2] should be 30");

    // Reset thread-locals
    unsafe { crate::rt_api::set_current_args(0, std::ptr::null()) };
}

#[test]
fn test_create_arguments_single_value() {
    // Single argument case.
    let args = [JsValue::number(2.5).raw_bits()];
    unsafe { crate::rt_api::set_current_args(1, args.as_ptr()) };
    crate::rt_api::set_current_callee(0);
    let result = crate::rt_api::__esc_rt_create_arguments();

    assert_eq!(args_get_length(result), 1, "arguments should have length 1");

    let idx0 = JsValue::int(0).raw_bits();
    let v0 = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(result, idx0));
    assert_eq!(v0.as_number(), Some(2.5), "arguments[0] should be 2.5");

    unsafe { crate::rt_api::set_current_args(0, std::ptr::null()) };
}

