#[test]
fn test_arguments_callee_sloppy_mode() {
    // In sloppy mode, arguments.callee should return the closure value.
    let closure = crate::rt_api::__esc_rt_create_closure(42, 0, 0);
    let args_data = [JsValue::int(1).raw_bits()];
    unsafe { crate::rt_api::set_current_args(1, args_data.as_ptr()) };
    crate::rt_api::set_current_callee(closure);
    let result = crate::rt_api::__esc_rt_create_arguments();

    let callee = args_get_callee(result);
    assert_eq!(
        callee, closure,
        "arguments.callee should be the closure in sloppy mode"
    );

    unsafe { crate::rt_api::set_current_args(0, std::ptr::null()) };
    crate::rt_api::set_current_callee(0);
}

#[test]
fn test_arguments_callee_no_callee_returns_undefined() {
    // When no callee is set (CURRENT_CALLEE=0), .callee should not be present
    // and accessing it should return undefined.
    let args_data = [JsValue::int(1).raw_bits()];
    unsafe { crate::rt_api::set_current_args(1, args_data.as_ptr()) };
    crate::rt_api::set_current_callee(0);
    let result = crate::rt_api::__esc_rt_create_arguments();

    let callee = args_get_callee(result);
    assert!(
        JsValue::from_raw_bits(callee).is_undefined(),
        "arguments.callee should be undefined when no callee is set"
    );

    unsafe { crate::rt_api::set_current_args(0, std::ptr::null()) };
}

#[test]
fn test_arguments_is_ordinary_object() {
    // arguments is an ordinary object (NOT an array) per ECMA-262 Section 10.4.4
    let args = [JsValue::int(1).raw_bits(), JsValue::int(2).raw_bits()];
    unsafe { crate::rt_api::set_current_args(2, args.as_ptr()) };
    crate::rt_api::set_current_callee(0);
    let result = crate::rt_api::__esc_rt_create_arguments();

    // It should be an object
    let v = JsValue::from_raw_bits(result);
    assert!(v.is_object(), "arguments should be an object");

    // Verify .length via property access works
    assert_eq!(args_get_length(result), 2, "arguments.length should be 2");

    // Verify indexed access works
    let idx0 = JsValue::int(0).raw_bits();
    let v0 = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(result, idx0));
    assert_eq!(v0.as_int(), Some(1), "arguments[0] should be 1");

    unsafe { crate::rt_api::set_current_args(0, std::ptr::null()) };
}

#[test]
fn test_arguments_length_equals_actual_arg_count() {
    // arguments.length reflects actual args passed, not formal param count.
    // 5 arguments passed.
    let args = [
        JsValue::int(10).raw_bits(),
        JsValue::int(20).raw_bits(),
        JsValue::int(30).raw_bits(),
        JsValue::int(40).raw_bits(),
        JsValue::int(50).raw_bits(),
    ];
    unsafe { crate::rt_api::set_current_args(5, args.as_ptr()) };
    crate::rt_api::set_current_callee(0);
    let result = crate::rt_api::__esc_rt_create_arguments();

    assert_eq!(
        args_get_length(result),
        5,
        "arguments.length should equal actual arg count (5)"
    );

    // Verify all elements accessible
    for i in 0..5 {
        let idx = JsValue::int(i).raw_bits();
        let v = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(result, idx));
        assert_eq!(
            v.as_int(),
            Some((i + 1) * 10),
            "arguments[{i}] should be {}",
            (i + 1) * 10
        );
    }

    unsafe { crate::rt_api::set_current_args(0, std::ptr::null()) };
}

#[test]
fn test_arguments_extra_args_beyond_params() {
    // Extra arguments beyond formal param count are still accessible.
    // This tests the runtime behavior — formal param count doesn't matter here,
    // only actual argument count.
    let args = [
        JsValue::int(1).raw_bits(),
        JsValue::int(2).raw_bits(),
        JsValue::int(3).raw_bits(),
        JsValue::int(4).raw_bits(),
    ];
    unsafe { crate::rt_api::set_current_args(4, args.as_ptr()) };
    crate::rt_api::set_current_callee(0);
    let result = crate::rt_api::__esc_rt_create_arguments();

    // All 4 args should be accessible regardless of formal param count
    for i in 0..4 {
        let idx = JsValue::int(i).raw_bits();
        let v = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(result, idx));
        assert_eq!(
            v.as_int(),
            Some(i + 1),
            "arguments[{i}] should be {}",
            i + 1
        );
    }

    // Out-of-range index should return undefined
    let idx5 = JsValue::int(5).raw_bits();
    let v5 = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(result, idx5));
    assert!(
        v5.is_undefined(),
        "arguments[5] should be undefined for 4 args"
    );

    unsafe { crate::rt_api::set_current_args(0, std::ptr::null()) };
}

#[test]
fn test_arguments_set_indexed_property() {
    // Setting arguments[i] should work (ordinary object set_prop).
    let args = [JsValue::int(10).raw_bits(), JsValue::int(20).raw_bits()];
    unsafe { crate::rt_api::set_current_args(2, args.as_ptr()) };
    crate::rt_api::set_current_callee(0);
    let result = crate::rt_api::__esc_rt_create_arguments();

    // Set arguments[0] = 99
    let idx0 = JsValue::int(0).raw_bits();
    let new_val = JsValue::int(99).raw_bits();
    crate::rt_api::__esc_rt_set_prop(result, idx0, new_val);

    // Read back
    let v0 = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(result, idx0));
    assert_eq!(v0.as_int(), Some(99), "arguments[0] should be 99 after set");

    // arguments[1] should be unaffected
    let idx1 = JsValue::int(1).raw_bits();
    let v1 = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_prop(result, idx1));
    assert_eq!(v1.as_int(), Some(20), "arguments[1] should still be 20");

    unsafe { crate::rt_api::set_current_args(0, std::ptr::null()) };
}

