// --- Closure method dispatch tests ---

#[test]
fn test_closure_method_property_lookup() {
    // Simulate assert.sameValue pattern: closure with a method property
    let parent = crate::rt_api::__esc_rt_create_closure(0, 0, 0);
    let child = crate::rt_api::__esc_rt_create_closure(0, 0, 0);
    let key = crate::rt_api::make_rt_string("method".to_string());
    crate::rt_api::__esc_rt_set_prop(parent, key, child);

    // Retrieve the method — should get back the child closure
    let key2 = crate::rt_api::make_rt_string("method".to_string());
    let retrieved = crate::rt_api::__esc_rt_get_prop(parent, key2);
    assert!(
        JsValue::from_raw_bits(retrieved).is_object(),
        "method property on closure should resolve to an object"
    );
}

#[test]
fn test_call_new_creates_object_with_proto() {
    // new Constructor() should return a plain object when constructor is a closure
    let ctor = crate::rt_api::__esc_rt_create_closure(0, 0, 0);
    let proto = crate::rt_api::__esc_rt_create_object();
    let proto_key = crate::rt_api::make_rt_string("prototype".to_string());
    crate::rt_api::__esc_rt_set_prop(ctor, proto_key, proto);

    let result = unsafe { crate::rt_api::__esc_rt_call_new(ctor, 0, std::ptr::null()) };
    let result_val = JsValue::from_raw_bits(result);
    assert!(
        result_val.is_object(),
        "new Constructor() must return an object"
    );

    // The returned object's __proto__ should be the constructor's prototype
    let proto_key2 = crate::rt_api::make_rt_string("__proto__".to_string());
    let result_proto = crate::rt_api::__esc_rt_get_prop(result, proto_key2);
    assert_eq!(
        result_proto, proto,
        "new obj.__proto__ should equal Constructor.prototype"
    );
}

