// =========================================================================
// Array slice tests (__esc_rt_array_slice)
// =========================================================================

#[test]
fn test_array_slice_from_start() {
    // [1, 2, 3, 4] sliced from index 0 should give [1, 2, 3, 4]
    let arr = crate::rt_api::__esc_rt_create_array(4);
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(1).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(2).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(3).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(4).raw_bits());

    let result = crate::rt_api::__esc_rt_array_slice(arr, JsValue::int(0).raw_bits());
    let len = crate::rt_api::__esc_rt_array_length(result);
    assert_eq!(
        JsValue::from_raw_bits(len).as_number(),
        Some(4.0),
        "slice from 0 should have 4 elements"
    );
}

#[test]
fn test_array_slice_from_middle() {
    // [10, 20, 30, 40] sliced from index 2 should give [30, 40]
    let arr = crate::rt_api::__esc_rt_create_array(4);
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(10).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(20).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(30).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(40).raw_bits());

    let result = crate::rt_api::__esc_rt_array_slice(arr, JsValue::int(2).raw_bits());
    let len = crate::rt_api::__esc_rt_array_length(result);
    assert_eq!(
        JsValue::from_raw_bits(len).as_number(),
        Some(2.0),
        "slice from 2 should have 2 elements"
    );

    let idx0 = JsValue::int(0).raw_bits();
    let idx1 = JsValue::int(1).raw_bits();
    let v0 = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_elem(result, idx0));
    let v1 = JsValue::from_raw_bits(crate::rt_api::__esc_rt_get_elem(result, idx1));
    assert_eq!(v0.as_int(), Some(30), "rest[0] should be 30");
    assert_eq!(v1.as_int(), Some(40), "rest[1] should be 40");
}

#[test]
fn test_array_slice_past_end() {
    // [1, 2] sliced from index 5 should give []
    let arr = crate::rt_api::__esc_rt_create_array(2);
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(1).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(2).raw_bits());

    let result = crate::rt_api::__esc_rt_array_slice(arr, JsValue::int(5).raw_bits());
    let len = crate::rt_api::__esc_rt_array_length(result);
    assert_eq!(
        JsValue::from_raw_bits(len).as_number(),
        Some(0.0),
        "slice past end should give empty array"
    );
}

