#[test]
fn test_throw_syntax_error() {
    crate::exceptions::clear_exception();

    let msg = crate::rt_api::make_rt_string("Unexpected token".to_string());
    let _result = crate::rt_api::__esc_rt_throw_syntax_error(msg);

    assert!(
        crate::exceptions::is_exception(),
        "should have pending exception"
    );
    let exc = crate::exceptions::get_exception();
    let info = extract_error_info(exc);
    assert_eq!(
        info.map(|e| e.error_tag),
        Some(crate::exceptions::error_tag::SYNTAX_ERROR),
        "exception should be a SyntaxError"
    );
    crate::exceptions::clear_exception();
}

