/// Helper: run __esc_rt_typeof on a string-valued built-in and return the type string.
fn typeof_builtin_string(name: &str) -> String {
    let val = crate::rt_api::make_rt_string(name.to_string());
    let result = crate::rt_api::__esc_rt_typeof(val);
    let result_val = JsValue::from_raw_bits(result);
    assert!(result_val.is_string(), "typeof result should be a string");
    let s = crate::string_ops::get_string_data(result_val);
    crate::string_ops::free_string(result_val);
    s
}

