// =========================================================================
// Strict mode property assignment tests
// =========================================================================

/// Helper to call Object static methods (freeze, seal, etc.) via the dispatch API.
fn call_object_static(method: &str, obj_bits: u64) -> Option<u64> {
    let argv: [u64; 1] = [obj_bits];
    crate::rt_api::dispatch_object_static_method(method, 1, argv.as_ptr())
}

#[test]
fn test_set_prop_strict_frozen_object_throws() {
    crate::exceptions::clear_exception();

    // Create object, set a property, then freeze it
    let obj = crate::rt_api::__esc_rt_create_object();
    let key = crate::rt_api::make_rt_string("x".to_string());
    crate::rt_api::__esc_rt_set_prop(obj, key, JsValue::int(1).raw_bits());

    // Freeze via Object.freeze
    call_object_static("freeze", obj);

    // Sloppy mode: silent failure, no exception
    crate::rt_api::__esc_rt_set_prop(obj, key, JsValue::int(2).raw_bits());
    assert!(
        !crate::exceptions::is_exception(),
        "sloppy set_prop on frozen object should not throw"
    );

    // Strict mode: should throw TypeError
    crate::rt_api::__esc_rt_set_prop_strict(obj, key, JsValue::int(3).raw_bits());
    assert!(
        crate::exceptions::is_exception(),
        "strict set_prop on frozen object should throw TypeError"
    );

    let exc = crate::exceptions::get_exception();
    let info = extract_error_info(exc);
    assert!(info.is_some(), "exception should be an error object");
    let error = info.unwrap();
    let msg_str = crate::string_ops::get_string_data(JsValue::from_raw_bits(error.message));
    assert!(
        msg_str.contains("read only property"),
        "error message should mention 'read only property', got: {msg_str}"
    );
    crate::exceptions::clear_exception();
    // SAFETY: obj was created by __esc_rt_create_object and is owned by this test
    unsafe { crate::tagged_obj::free_tagged::<crate::internal_data::UnifiedObject>(obj) };
}

