#[test]
fn test_set_property_non_writable_rejected() {
    let interner = Interner::new();
    let mut shapes = ShapeTable::new();
    let mut obj = JsObject::new(ShapeTable::EMPTY_SHAPE, 3);

    // Define a property with writable=false
    let result = property::define_property(
        &mut obj,
        "x",
        &property::DefinePropertyOptions {
            value: Some(JsValue::int(42)),
            writable: Some(false),
            enumerable: Some(true),
            configurable: Some(true),
            ..Default::default()
        },
        &mut shapes,
        &interner,
    );
    assert!(result.is_ok());

    // Reading the value should work
    let val = property::get_property(&obj, "x", &shapes, &interner);
    assert_eq!(val.unwrap().as_int(), Some(42));

    // set_property should fail with NotWritable
    let result = property::set_property(&mut obj, "x", JsValue::int(99), &mut shapes, &interner);
    assert_eq!(result, Err(PropertyError::NotWritable));

    // Value should be unchanged
    let val = property::get_property(&obj, "x", &shapes, &interner);
    assert_eq!(val.unwrap().as_int(), Some(42));
}

