#[test]
fn test_define_property_round_trip_descriptor() {
    let interner = Interner::new();
    let mut shapes = ShapeTable::new();
    let mut obj = JsObject::new(ShapeTable::EMPTY_SHAPE, 3);

    // Define with specific flags
    property::define_property(
        &mut obj,
        "x",
        &property::DefinePropertyOptions {
            value: Some(JsValue::int(7)),
            writable: Some(false),
            enumerable: Some(false),
            configurable: Some(true),
            ..Default::default()
        },
        &mut shapes,
        &interner,
    )
    .unwrap();

    // Get the descriptor back
    let desc = property::get_own_property_descriptor(&obj, "x", &shapes, &interner);
    assert!(desc.is_some());
    let desc = desc.unwrap();
    match desc {
        property::OwnPropertyDescriptor::Data {
            value,
            writable,
            enumerable,
            configurable,
        } => {
            assert_eq!(value.as_int(), Some(7));
            assert!(!writable);
            assert!(!enumerable);
            assert!(configurable);
        }
        property::OwnPropertyDescriptor::Accessor { .. } => {
            panic!("expected data descriptor, got accessor");
        }
    }
}

