#[test]
fn test_enumerable_property_keys_filters_non_enumerable() {
    let interner = Interner::new();
    let mut shapes = ShapeTable::new();
    let mut obj = JsObject::new(ShapeTable::EMPTY_SHAPE, 3);

    // Add an enumerable property
    property::define_property(
        &mut obj,
        "visible",
        &property::DefinePropertyOptions {
            value: Some(JsValue::int(1)),
            writable: Some(true),
            enumerable: Some(true),
            configurable: Some(true),
            ..Default::default()
        },
        &mut shapes,
        &interner,
    )
    .unwrap();

    // Add a non-enumerable property
    property::define_property(
        &mut obj,
        "hidden",
        &property::DefinePropertyOptions {
            value: Some(JsValue::int(2)),
            writable: Some(true),
            enumerable: Some(false),
            configurable: Some(true),
            ..Default::default()
        },
        &mut shapes,
        &interner,
    )
    .unwrap();

    // enumerable_property_keys should only return "visible"
    let keys = property::enumerable_property_keys(&obj, &shapes, &interner);
    assert_eq!(keys, vec!["visible"]);

    // property_keys should return both
    let all_keys = property::property_keys(&obj, &shapes, &interner);
    assert_eq!(all_keys.len(), 2);
    assert!(all_keys.contains(&"visible".to_string()));
    assert!(all_keys.contains(&"hidden".to_string()));
}

