#[test]
fn test_set_prop_sloppy_non_writable_silent_on_side_table_object() {
    // OBJECT_PROPS-backed kinds (Map, Date, Function, wrappers) store user
    // properties in the side-table, but defineProperty stores descriptors in
    // the shape table. Assignment must respect the shape descriptor's
    // non-writable flag instead of blindly overwriting the side-table.
    crate::exceptions::clear_exception();

    let obj = crate::rt_api::__esc_rt_create_map();
    let prop_key = crate::rt_api::make_rt_string("x".to_string());

    // Create non-writable property via defineProperty
    let descriptor = crate::rt_api::__esc_rt_create_object();
    let val_key = crate::rt_api::make_rt_string("value".to_string());
    crate::rt_api::__esc_rt_set_prop(descriptor, val_key, JsValue::int(10).raw_bits());
    let w_key = crate::rt_api::make_rt_string("writable".to_string());
    crate::rt_api::__esc_rt_set_prop(descriptor, w_key, JsValue::bool(false).raw_bits());

    let argv: [u64; 3] = [obj, prop_key, descriptor];
    crate::rt_api::dispatch_object_static_method("defineProperty", 3, argv.as_ptr());

    // Sloppy set: should not throw, value unchanged
    crate::rt_api::__esc_rt_set_prop(obj, prop_key, JsValue::int(999).raw_bits());
    assert!(!crate::exceptions::is_exception());

    let val = crate::rt_api::__esc_rt_get_prop(obj, prop_key);
    assert_eq!(JsValue::from_raw_bits(val).as_int(), Some(10));

    // SAFETY: cleanup
    unsafe { crate::tagged_obj::free_tagged::<crate::internal_data::UnifiedObject>(obj) };
    unsafe { crate::tagged_obj::free_tagged::<crate::internal_data::UnifiedObject>(descriptor) };
}

#[test]
fn test_get_own_property_descriptor_via_dispatch() {
    crate::exceptions::clear_exception();

    let obj = crate::rt_api::__esc_rt_create_object();
    let prop_key = crate::rt_api::make_rt_string("x".to_string());

    // Define property with specific flags
    let descriptor = crate::rt_api::__esc_rt_create_object();
    let val_key = crate::rt_api::make_rt_string("value".to_string());
    crate::rt_api::__esc_rt_set_prop(descriptor, val_key, JsValue::int(42).raw_bits());
    let w_key = crate::rt_api::make_rt_string("writable".to_string());
    crate::rt_api::__esc_rt_set_prop(descriptor, w_key, JsValue::bool(false).raw_bits());
    let e_key = crate::rt_api::make_rt_string("enumerable".to_string());
    crate::rt_api::__esc_rt_set_prop(descriptor, e_key, JsValue::bool(true).raw_bits());
    let c_key = crate::rt_api::make_rt_string("configurable".to_string());
    crate::rt_api::__esc_rt_set_prop(descriptor, c_key, JsValue::bool(false).raw_bits());

    let argv_define: [u64; 3] = [obj, prop_key, descriptor];
    crate::rt_api::dispatch_object_static_method("defineProperty", 3, argv_define.as_ptr());

    // Now get the descriptor back
    let argv_get: [u64; 2] = [obj, prop_key];
    let result = crate::rt_api::dispatch_object_static_method(
        "getOwnPropertyDescriptor",
        2,
        argv_get.as_ptr(),
    );
    assert!(result.is_some());
    let desc_obj = result.unwrap();

    // Check writable is false
    let w_key2 = crate::rt_api::make_rt_string("writable".to_string());
    let w_val = crate::rt_api::__esc_rt_get_prop(desc_obj, w_key2);
    assert_eq!(
        JsValue::from_raw_bits(w_val).as_bool(),
        Some(false),
        "writable should be false"
    );

    // Check enumerable is true
    let e_key2 = crate::rt_api::make_rt_string("enumerable".to_string());
    let e_val = crate::rt_api::__esc_rt_get_prop(desc_obj, e_key2);
    assert_eq!(
        JsValue::from_raw_bits(e_val).as_bool(),
        Some(true),
        "enumerable should be true"
    );

    // Check configurable is false
    let c_key2 = crate::rt_api::make_rt_string("configurable".to_string());
    let c_val = crate::rt_api::__esc_rt_get_prop(desc_obj, c_key2);
    assert_eq!(
        JsValue::from_raw_bits(c_val).as_bool(),
        Some(false),
        "configurable should be false"
    );

    // Check value is 42
    let v_key2 = crate::rt_api::make_rt_string("value".to_string());
    let v_val = crate::rt_api::__esc_rt_get_prop(desc_obj, v_key2);
    assert_eq!(
        JsValue::from_raw_bits(v_val).as_int(),
        Some(42),
        "value should be 42"
    );

    // SAFETY: cleanup
    unsafe { crate::tagged_obj::free_tagged::<crate::internal_data::UnifiedObject>(obj) };
    unsafe { crate::tagged_obj::free_tagged::<crate::internal_data::UnifiedObject>(descriptor) };
    unsafe { crate::tagged_obj::free_tagged::<crate::internal_data::UnifiedObject>(desc_obj) };
}

#[test]
fn test_object_keys_only_enumerable() {
    crate::exceptions::clear_exception();

    let obj = crate::rt_api::__esc_rt_create_object();

    // Add a normal (enumerable) property
    let key_a = crate::rt_api::make_rt_string("a".to_string());
    crate::rt_api::__esc_rt_set_prop(obj, key_a, JsValue::int(1).raw_bits());

    // Add a non-enumerable property via defineProperty
    let key_b = crate::rt_api::make_rt_string("b".to_string());
    let descriptor = crate::rt_api::__esc_rt_create_object();
    let val_key = crate::rt_api::make_rt_string("value".to_string());
    crate::rt_api::__esc_rt_set_prop(descriptor, val_key, JsValue::int(2).raw_bits());
    let e_key = crate::rt_api::make_rt_string("enumerable".to_string());
    crate::rt_api::__esc_rt_set_prop(descriptor, e_key, JsValue::bool(false).raw_bits());

    let argv_define: [u64; 3] = [obj, key_b, descriptor];
    crate::rt_api::dispatch_object_static_method("defineProperty", 3, argv_define.as_ptr());

    // Object.keys should only return "a"
    let keys = crate::rt_api::__esc_rt_object_keys(obj);
    let arr = unsafe {
        // SAFETY: keys was returned by __esc_rt_object_keys and is a valid tagged array.
        crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(keys)
    };
    assert!(arr.is_some());
    let arr = arr.unwrap();
    assert_eq!(
        arr.array_len(),
        1,
        "Object.keys should return only enumerable properties"
    );

    // SAFETY: cleanup
    unsafe { crate::tagged_obj::free_tagged::<crate::internal_data::UnifiedObject>(obj) };
    unsafe { crate::tagged_obj::free_tagged::<crate::internal_data::UnifiedObject>(descriptor) };
}

#[test]
fn test_freeze_sets_per_property_flags() {
    let interner = Interner::new();
    let mut shapes = ShapeTable::new();
    let mut obj = JsObject::new(ShapeTable::EMPTY_SHAPE, 3);

    // Add properties first
    property::set_property(&mut obj, "a", JsValue::int(1), &mut shapes, &interner).unwrap();
    property::set_property(&mut obj, "b", JsValue::int(2), &mut shapes, &interner).unwrap();

    // Check writable before freeze
    let desc_a = property::get_own_property_descriptor(&obj, "a", &shapes, &interner).unwrap();
    assert!(desc_a.is_data());
    assert!(desc_a.is_configurable());

    // Freeze the shape's properties
    if let Some(new_shape) = shapes.freeze_all_properties(obj.shape_id) {
        obj.shape_id = new_shape;
    }
    obj.freeze();

    // After freeze, properties should be non-writable and non-configurable
    let desc_a = property::get_own_property_descriptor(&obj, "a", &shapes, &interner).unwrap();
    match &desc_a {
        property::OwnPropertyDescriptor::Data {
            writable,
            configurable,
            ..
        } => {
            assert!(!writable, "property should be non-writable after freeze");
            assert!(
                !configurable,
                "property should be non-configurable after freeze"
            );
        }
        _ => panic!("expected data descriptor"),
    }
    let desc_b = property::get_own_property_descriptor(&obj, "b", &shapes, &interner).unwrap();
    match &desc_b {
        property::OwnPropertyDescriptor::Data {
            writable,
            configurable,
            ..
        } => {
            assert!(!writable);
            assert!(!configurable);
        }
        _ => panic!("expected data descriptor"),
    }
}

#[test]
fn test_seal_sets_per_property_configurable_false() {
    let interner = Interner::new();
    let mut shapes = ShapeTable::new();
    let mut obj = JsObject::new(ShapeTable::EMPTY_SHAPE, 3);

    property::set_property(&mut obj, "x", JsValue::int(1), &mut shapes, &interner).unwrap();

    // Seal the properties
    if let Some(new_shape) = shapes.seal_all_properties(obj.shape_id) {
        obj.shape_id = new_shape;
    }
    obj.seal();

    let desc = property::get_own_property_descriptor(&obj, "x", &shapes, &interner).unwrap();
    match desc {
        property::OwnPropertyDescriptor::Data {
            writable,
            configurable,
            ..
        } => {
            assert!(writable, "sealed properties should still be writable");
            assert!(
                !configurable,
                "sealed properties should be non-configurable"
            );
        }
        property::OwnPropertyDescriptor::Accessor { .. } => {
            panic!("expected data descriptor, got accessor");
        }
    }
}

