// =========================================================================
// String.lastIndexOf dispatch test
// =========================================================================

#[test]
fn test_dispatch_string_method_last_index_of() {
    let rt_str = Box::new(RtString::new("hello world hello".to_string()));
    let ptr = Box::into_raw(rt_str) as *const ();
    let obj = JsValue::string(ptr).raw_bits();

    let search = Box::new(RtString::new("hello".to_string()));
    let search_ptr = Box::into_raw(search) as *const ();
    let args: [u64; 1] = [JsValue::string(search_ptr).raw_bits()];

    let result = dispatch_string_method(obj, "lastIndexOf", 1, args.as_ptr());
    // "hello" last appears at index 12
    assert_eq!(JsValue::from_raw_bits(result).as_int(), Some(12));

    // Search for something not found
    let not_found = Box::new(RtString::new("xyz".to_string()));
    let nf_ptr = Box::into_raw(not_found) as *const ();
    let args2: [u64; 1] = [JsValue::string(nf_ptr).raw_bits()];
    let result2 = dispatch_string_method(obj, "lastIndexOf", 1, args2.as_ptr());
    assert_eq!(JsValue::from_raw_bits(result2).as_int(), Some(-1));

    crate::string_ops::free_string(JsValue::from_raw_bits(obj));
    crate::string_ops::free_string(JsValue::string(search_ptr));
    crate::string_ops::free_string(JsValue::string(nf_ptr));
}

