#[test]
fn test_dispatch_array_method_last_index_of() {
    let bits = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::array(
            ShapeTable::EMPTY_SHAPE,
            vec![
                JsValue::int(1),
                JsValue::int(2),
                JsValue::int(1),
                JsValue::int(3),
            ],
        ),
    );

    let search: [u64; 1] = [JsValue::int(1).raw_bits()];
    let result = dispatch_array_method(bits, "lastIndexOf", 1, search.as_ptr());
    // Last occurrence of 1 is at index 2
    assert_eq!(JsValue::from_raw_bits(result).as_int(), Some(2));

    let search2: [u64; 1] = [JsValue::int(99).raw_bits()];
    let result2 = dispatch_array_method(bits, "lastIndexOf", 1, search2.as_ptr());
    assert_eq!(JsValue::from_raw_bits(result2).as_int(), Some(-1));

    unsafe { free_tagged::<UnifiedObject>(bits) };
}

