#[test]
fn test_define_property_on_non_extensible_object() {
    let interner = Interner::new();
    let mut shapes = ShapeTable::new();
    let mut obj = JsObject::new(ShapeTable::EMPTY_SHAPE, 3);
    obj.prevent_extensions();

    // Defining a new property on a non-extensible object should fail
    let result = property::define_property(
        &mut obj,
        "x",
        &property::DefinePropertyOptions {
            value: Some(JsValue::int(1)),
            writable: Some(true),
            enumerable: Some(true),
            configurable: Some(true),
            ..Default::default()
        },
        &mut shapes,
        &interner,
    );
    assert_eq!(result, Err(PropertyError::NotExtensible));
}

#[test]
fn test_define_property_redefine_same_value_non_configurable() {
    let interner = Interner::new();
    let mut shapes = ShapeTable::new();
    let mut obj = JsObject::new(ShapeTable::EMPTY_SHAPE, 3);

    // Define a non-configurable, non-writable property
    property::define_property(
        &mut obj,
        "x",
        &property::DefinePropertyOptions {
            value: Some(JsValue::int(42)),
            writable: Some(false),
            enumerable: Some(true),
            configurable: Some(false),
            ..Default::default()
        },
        &mut shapes,
        &interner,
    )
    .unwrap();

    // Redefining with no changes should succeed (spec allows no-op redefine)
    let result = property::define_property(
        &mut obj,
        "x",
        &property::DefinePropertyOptions {
            writable: Some(false),
            enumerable: Some(true),
            configurable: Some(false),
            ..Default::default()
        },
        &mut shapes,
        &interner,
    );
    assert!(
        result.is_ok(),
        "redefining non-configurable property with same flags should succeed"
    );
}

