// -------------------------------------------------------------------------
// ToUint32 tests
// -------------------------------------------------------------------------

#[test]
fn test_to_uint32_basic() {
    // Integer passthrough
    let result = crate::rt_api::__esc_rt_to_uint32(JsValue::int(5).raw_bits());
    let val = JsValue::from_raw_bits(result);
    assert_eq!(val.as_int(), Some(5));

    // Float truncates
    let result = crate::rt_api::__esc_rt_to_uint32(JsValue::number(3.7).raw_bits());
    let val = JsValue::from_raw_bits(result);
    assert_eq!(val.as_int(), Some(3));

    // null → 0
    let result = crate::rt_api::__esc_rt_to_uint32(JsValue::null().raw_bits());
    let val = JsValue::from_raw_bits(result);
    assert_eq!(val.as_int(), Some(0));

    // undefined → 0 (NaN)
    let result = crate::rt_api::__esc_rt_to_uint32(JsValue::undefined().raw_bits());
    let val = JsValue::from_raw_bits(result);
    assert_eq!(val.as_int(), Some(0));

    // true → 1
    let result = crate::rt_api::__esc_rt_to_uint32(JsValue::bool(true).raw_bits());
    let val = JsValue::from_raw_bits(result);
    assert_eq!(val.as_int(), Some(1));

    // false → 0
    let result = crate::rt_api::__esc_rt_to_uint32(JsValue::bool(false).raw_bits());
    let val = JsValue::from_raw_bits(result);
    assert_eq!(val.as_int(), Some(0));
}

#[test]
fn test_to_uint32_edge_cases() {
    // NaN → 0
    let result = crate::rt_api::__esc_rt_to_uint32(JsValue::number(f64::NAN).raw_bits());
    assert_eq!(JsValue::from_raw_bits(result).as_int(), Some(0));

    // Infinity → 0
    let result = crate::rt_api::__esc_rt_to_uint32(JsValue::number(f64::INFINITY).raw_bits());
    assert_eq!(JsValue::from_raw_bits(result).as_int(), Some(0));

    // -Infinity → 0
    let result = crate::rt_api::__esc_rt_to_uint32(JsValue::number(f64::NEG_INFINITY).raw_bits());
    assert_eq!(JsValue::from_raw_bits(result).as_int(), Some(0));

    // -0.0 → 0
    let result = crate::rt_api::__esc_rt_to_uint32(JsValue::number(-0.0).raw_bits());
    assert_eq!(JsValue::from_raw_bits(result).as_int(), Some(0));

    // Negative number: -1 → 4294967295 (as u32) → -1 (as i32 bit pattern)
    let result = crate::rt_api::__esc_rt_to_uint32(JsValue::number(-1.0).raw_bits());
    let val = JsValue::from_raw_bits(result);
    // -1 mod 2^32 = 4294967295 = 0xFFFFFFFF which as i32 is -1
    assert_eq!(val.as_int(), Some(-1));
}

