#[test]
fn test_string_matchall_with_regexp() {
    let re = __esc_rt_create_regexp(make_string_value("\\d+"), make_string_value("g"));
    let s = make_string_value("a1b22c333");
    let args: [u64; 1] = [re];

    let result = dispatch_string_method(s, "matchAll", 1, args.as_ptr());
    let tag = read_obj_tag(result);
    assert_eq!(tag, Some(ObjTag::Unified as u8));
    let arr = unsafe { deref_tagged::<UnifiedObject>(result) }.unwrap();
    // 3 match objects
    assert_eq!(arr.array_len(), 3);
    // First match: "1"
    let m0_val = arr.get_element(0).unwrap();
    let m0 = unsafe { deref_tagged::<UnifiedObject>(m0_val.raw_bits()) }.unwrap();
    assert_eq!(
        crate::string_ops::get_string_data(m0.get_element(0).unwrap()),
        "1"
    );
    // Second match: "22"
    let m1_val = arr.get_element(1).unwrap();
    let m1 = unsafe { deref_tagged::<UnifiedObject>(m1_val.raw_bits()) }.unwrap();
    assert_eq!(
        crate::string_ops::get_string_data(m1.get_element(0).unwrap()),
        "22"
    );
    // Third match: "333"
    let m2_val = arr.get_element(2).unwrap();
    let m2 = unsafe { deref_tagged::<UnifiedObject>(m2_val.raw_bits()) }.unwrap();
    assert_eq!(
        crate::string_ops::get_string_data(m2.get_element(0).unwrap()),
        "333"
    );

    unsafe { free_tagged::<UnifiedObject>(result) };
    crate::string_ops::free_string(JsValue::from_raw_bits(s));
}

#[test]
fn test_string_matchall_with_capture_groups() {
    let re = __esc_rt_create_regexp(make_string_value("(\\d)(\\w)"), make_string_value("g"));
    let s = make_string_value("1a2b3c");
    let args: [u64; 1] = [re];

    let result = dispatch_string_method(s, "matchAll", 1, args.as_ptr());
    let arr = unsafe { deref_tagged::<UnifiedObject>(result) }.unwrap();
    assert_eq!(arr.array_len(), 3);
    // First match: ["1a", "1", "a"]
    let m0_val = arr.get_element(0).unwrap();
    let m0 = unsafe { deref_tagged::<UnifiedObject>(m0_val.raw_bits()) }.unwrap();
    assert_eq!(
        crate::string_ops::get_string_data(m0.get_element(0).unwrap()),
        "1a"
    );
    assert_eq!(
        crate::string_ops::get_string_data(m0.get_element(1).unwrap()),
        "1"
    );
    assert_eq!(
        crate::string_ops::get_string_data(m0.get_element(2).unwrap()),
        "a"
    );

    unsafe { free_tagged::<UnifiedObject>(result) };
    crate::string_ops::free_string(JsValue::from_raw_bits(s));
}

