// Note: In unit tests, __esc_dispatch is stubbed to return undefined.
// These tests verify the dispatch mechanics (this binding, arg passing)
// rather than actual function execution, which is covered by integration
// fixtures.

#[test]
fn test_function_call_sets_this() {
    use crate::rt_api::{__esc_rt_create_closure, dispatch_function_call};

    // Create a closure (func_idx=0, no env)
    let closure = __esc_rt_create_closure(0, 0, 0);
    let this_obj = JsValue::int(999).raw_bits();

    let args: [u64; 2] = [this_obj, JsValue::int(1).raw_bits()];
    // In test mode, __esc_dispatch returns undefined, but we verify
    // the dispatch happened without panic and CURRENT_THIS was restored.
    let result = unsafe { dispatch_function_call(closure, 2, args.as_ptr()) };

    // __esc_dispatch stub returns undefined in test mode
    let val = JsValue::from_raw_bits(result);
    assert!(val.is_undefined());
}

