// -------------------------------------------------------------------------
// 188. test_iter_next_map_entries_returns_key_value_pairs
// -------------------------------------------------------------------------

#[test]
fn test_iter_next_map_entries_returns_key_value_pairs() {
    use crate::rt_api;
    use crate::tagged_obj::{ObjTag, read_obj_tag};

    let map = rt_api::__esc_rt_create_map();
    let k1 = rt_api::make_rt_string("a".to_string());
    let v1 = JsValue::int(1).raw_bits();
    rt_api::dispatch_map_method(map, "set", 2, [k1, v1].as_ptr());
    let k2 = rt_api::make_rt_string("b".to_string());
    let v2 = JsValue::int(2).raw_bits();
    rt_api::dispatch_map_method(map, "set", 2, [k2, v2].as_ptr());

    let iter = rt_api::__esc_rt_iter_init(map);

    // First entry: [a, 1]
    let result1 = rt_api::__esc_rt_iter_next(iter);
    let done1 = rt_api::__esc_rt_iter_done(result1);
    assert_eq!(
        JsValue::from_raw_bits(done1),
        JsValue::bool(false),
        "first entry should not be done"
    );
    let val1 = rt_api::__esc_rt_iter_value(result1);
    let pair_tag = read_obj_tag(val1);
    assert_eq!(
        pair_tag,
        Some(ObjTag::Unified as u8),
        "Map entry value should be an array"
    );

    // Second entry: [b, 2]
    let result2 = rt_api::__esc_rt_iter_next(iter);
    let done2 = rt_api::__esc_rt_iter_done(result2);
    assert_eq!(
        JsValue::from_raw_bits(done2),
        JsValue::bool(false),
        "second entry should not be done"
    );

    // Third: done
    let result3 = rt_api::__esc_rt_iter_next(iter);
    let done3 = rt_api::__esc_rt_iter_done(result3);
    assert_eq!(
        JsValue::from_raw_bits(done3),
        JsValue::bool(true),
        "third entry should be done"
    );
}

