// -------------------------------------------------------------------------
// 193. test_spread_into_array_string
// -------------------------------------------------------------------------

#[test]
fn test_spread_into_array_string() {
    use crate::rt_api;
    use crate::tagged_obj::{ObjTag, deref_tagged, read_obj_tag};

    let target = rt_api::__esc_rt_create_array(0);
    let source = rt_api::make_rt_string("abc".to_string());

    let result = rt_api::__esc_rt_spread_into_array(target, source);
    assert_eq!(result, target, "spread should return the target array");

    // Check that target has 3 elements (a, b, c)
    let tag = read_obj_tag(result);
    assert_eq!(tag, Some(ObjTag::Unified as u8));
    let arr = unsafe { deref_tagged::<UnifiedObject>(result) };
    assert!(arr.is_some());
    let arr = arr.unwrap();
    assert_eq!(
        arr.array_len(),
        3,
        "spreading 'abc' should produce 3 elements"
    );

    let c0 = arr.get_element(0).unwrap();
    assert!(c0.is_string(), "first element should be a string");
    let s0 = crate::string_ops::get_string_data(c0);
    assert_eq!(s0, "a");
}

