// -------------------------------------------------------------------------
// 197. test_map_get_set
// -------------------------------------------------------------------------

#[test]
fn test_map_get_set() {
    use crate::rt_api;

    let map = rt_api::__esc_rt_create_map();

    // set("x", 42) — should return the map itself
    let key = rt_api::make_rt_string("x".to_string());
    let val = JsValue::int(42).raw_bits();
    let ret = rt_api::dispatch_map_method(map, "set", 2, [key, val].as_ptr());
    assert_eq!(ret, map, "Map.set should return the map");

    // get("x") — should return 42
    let result = rt_api::dispatch_map_method(map, "get", 1, [key].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(result).as_int(),
        Some(42),
        "Map.get should return the value that was set"
    );

    // get("missing") — should return undefined
    let missing_key = rt_api::make_rt_string("missing".to_string());
    let result_missing = rt_api::dispatch_map_method(map, "get", 1, [missing_key].as_ptr());
    assert!(
        JsValue::from_raw_bits(result_missing).is_undefined(),
        "Map.get for missing key should return undefined"
    );
}

// -------------------------------------------------------------------------
// 198. test_map_has_and_delete
// -------------------------------------------------------------------------

#[test]
fn test_map_has_and_delete() {
    use crate::rt_api;

    let map = rt_api::__esc_rt_create_map();

    let key = rt_api::make_rt_string("k".to_string());
    let val = JsValue::int(99).raw_bits();
    rt_api::dispatch_map_method(map, "set", 2, [key, val].as_ptr());

    // has("k") → true
    let has_result = rt_api::dispatch_map_method(map, "has", 1, [key].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(has_result),
        JsValue::bool(true),
        "Map.has should return true for existing key"
    );

    // has("other") → false
    let other_key = rt_api::make_rt_string("other".to_string());
    let has_other = rt_api::dispatch_map_method(map, "has", 1, [other_key].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(has_other),
        JsValue::bool(false),
        "Map.has should return false for missing key"
    );

    // delete("k") → true (was present)
    let del_result = rt_api::dispatch_map_method(map, "delete", 1, [key].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(del_result),
        JsValue::bool(true),
        "Map.delete should return true when key existed"
    );

    // has("k") → false (after delete)
    let has_after = rt_api::dispatch_map_method(map, "has", 1, [key].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(has_after),
        JsValue::bool(false),
        "Map.has should return false after delete"
    );

    // delete("k") again → false (already removed)
    let del_again = rt_api::dispatch_map_method(map, "delete", 1, [key].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(del_again),
        JsValue::bool(false),
        "Map.delete should return false when key does not exist"
    );
}

// -------------------------------------------------------------------------
// 199. test_map_clear
// -------------------------------------------------------------------------

#[test]
fn test_map_clear() {
    use crate::rt_api;

    let map = rt_api::__esc_rt_create_map();

    // Add a few entries
    let k1 = rt_api::make_rt_string("a".to_string());
    let k2 = rt_api::make_rt_string("b".to_string());
    rt_api::dispatch_map_method(map, "set", 2, [k1, JsValue::int(1).raw_bits()].as_ptr());
    rt_api::dispatch_map_method(map, "set", 2, [k2, JsValue::int(2).raw_bits()].as_ptr());

    // Verify size is 2
    let size_before = rt_api::dispatch_map_method(map, "size", 0, std::ptr::null());
    assert_eq!(JsValue::from_raw_bits(size_before), JsValue::number(2.0));

    // clear()
    let clear_result = rt_api::dispatch_map_method(map, "clear", 0, std::ptr::null());
    assert!(
        JsValue::from_raw_bits(clear_result).is_undefined(),
        "Map.clear should return undefined"
    );

    // size should be 0
    let size_after = rt_api::dispatch_map_method(map, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size_after),
        JsValue::number(0.0),
        "Map.size should be 0 after clear"
    );

    // get("a") → undefined
    let get_after = rt_api::dispatch_map_method(map, "get", 1, [k1].as_ptr());
    assert!(
        JsValue::from_raw_bits(get_after).is_undefined(),
        "Map.get should return undefined after clear"
    );
}

// -------------------------------------------------------------------------
// 200. test_map_size
// -------------------------------------------------------------------------

#[test]
fn test_map_size() {
    use crate::rt_api;

    let map = rt_api::__esc_rt_create_map();

    // Empty map → size 0
    let size0 = rt_api::dispatch_map_method(map, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size0),
        JsValue::number(0.0),
        "Empty map should have size 0"
    );

    // Add one entry → size 1
    let k1 = rt_api::make_rt_string("x".to_string());
    rt_api::dispatch_map_method(map, "set", 2, [k1, JsValue::int(1).raw_bits()].as_ptr());
    let size1 = rt_api::dispatch_map_method(map, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size1),
        JsValue::number(1.0),
        "Map with one entry should have size 1"
    );

    // Add second entry → size 2
    let k2 = rt_api::make_rt_string("y".to_string());
    rt_api::dispatch_map_method(map, "set", 2, [k2, JsValue::int(2).raw_bits()].as_ptr());
    let size2 = rt_api::dispatch_map_method(map, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size2),
        JsValue::number(2.0),
        "Map with two entries should have size 2"
    );

    // Overwrite existing key → size stays 2
    rt_api::dispatch_map_method(map, "set", 2, [k1, JsValue::int(99).raw_bits()].as_ptr());
    let size_still_2 = rt_api::dispatch_map_method(map, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size_still_2),
        JsValue::number(2.0),
        "Overwriting existing key should not increase size"
    );

    // Delete one entry → size 1
    rt_api::dispatch_map_method(map, "delete", 1, [k1].as_ptr());
    let size_after_del = rt_api::dispatch_map_method(map, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size_after_del),
        JsValue::number(1.0),
        "Deleting one entry should decrease size"
    );
}

