// -------------------------------------------------------------------------
// 201. test_set_add_and_has
// -------------------------------------------------------------------------

#[test]
fn test_set_add_and_has() {
    use crate::rt_api;

    let set = rt_api::__esc_rt_create_set();

    // has(42) → false (empty set)
    let has_before =
        rt_api::dispatch_set_method(set, "has", 1, [JsValue::int(42).raw_bits()].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(has_before),
        JsValue::bool(false),
        "Set.has should return false for empty set"
    );

    // add(42) — should return the set itself
    let ret = rt_api::dispatch_set_method(set, "add", 1, [JsValue::int(42).raw_bits()].as_ptr());
    assert_eq!(ret, set, "Set.add should return the set");

    // has(42) → true
    let has_after =
        rt_api::dispatch_set_method(set, "has", 1, [JsValue::int(42).raw_bits()].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(has_after),
        JsValue::bool(true),
        "Set.has should return true after add"
    );

    // has(99) → false (not added)
    let has_other =
        rt_api::dispatch_set_method(set, "has", 1, [JsValue::int(99).raw_bits()].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(has_other),
        JsValue::bool(false),
        "Set.has should return false for value not in set"
    );

    // Adding duplicate should not change the set
    rt_api::dispatch_set_method(set, "add", 1, [JsValue::int(42).raw_bits()].as_ptr());
    let size = rt_api::dispatch_set_method(set, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size),
        JsValue::number(1.0),
        "Adding duplicate should not increase size"
    );
}

// -------------------------------------------------------------------------
// 202. test_set_delete
// -------------------------------------------------------------------------

#[test]
fn test_set_delete() {
    use crate::rt_api;

    let set = rt_api::__esc_rt_create_set();

    rt_api::dispatch_set_method(set, "add", 1, [JsValue::int(10).raw_bits()].as_ptr());
    rt_api::dispatch_set_method(set, "add", 1, [JsValue::int(20).raw_bits()].as_ptr());

    // delete(10) → true
    let del_result =
        rt_api::dispatch_set_method(set, "delete", 1, [JsValue::int(10).raw_bits()].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(del_result),
        JsValue::bool(true),
        "Set.delete should return true when value existed"
    );

    // has(10) → false (deleted)
    let has_after =
        rt_api::dispatch_set_method(set, "has", 1, [JsValue::int(10).raw_bits()].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(has_after),
        JsValue::bool(false),
        "Set.has should return false after delete"
    );

    // delete(10) again → false (already removed)
    let del_again =
        rt_api::dispatch_set_method(set, "delete", 1, [JsValue::int(10).raw_bits()].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(del_again),
        JsValue::bool(false),
        "Set.delete should return false when value does not exist"
    );

    // 20 still exists
    let has_20 = rt_api::dispatch_set_method(set, "has", 1, [JsValue::int(20).raw_bits()].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(has_20),
        JsValue::bool(true),
        "Other values should be unaffected by delete"
    );
}

