fn test_string_to_number_leading_trailing_whitespace() {
    let val = make_string_value("  42  ");
    let n = crate::value_ops::to_number(JsValue::from_raw_bits(val));
    assert_eq!(n, 42.0, "leading/trailing whitespace should be trimmed");
}

// -------------------------------------------------------------------------
// 211. test_string_to_number_unicode_whitespace
// -------------------------------------------------------------------------

#[test]
fn test_string_to_number_unicode_whitespace() {
    // \u{00A0} = non-breaking space (NBSP)
    let val = make_string_value("\u{00A0}42\u{00A0}");
    let n = crate::value_ops::to_number(JsValue::from_raw_bits(val));
    assert_eq!(n, 42.0, "NBSP should be trimmed as ES whitespace");

    // \u{2003} = em space
    let val2 = make_string_value("\u{2003}99\u{2003}");
    let n2 = crate::value_ops::to_number(JsValue::from_raw_bits(val2));
    assert_eq!(n2, 99.0, "em space should be trimmed as ES whitespace");

    // \u{FEFF} = BOM (zero-width no-break space)
    let val3 = make_string_value("\u{FEFF}7\u{FEFF}");
    let n3 = crate::value_ops::to_number(JsValue::from_raw_bits(val3));
    assert_eq!(n3, 7.0, "BOM should be trimmed as ES whitespace");

    // whitespace-only with unicode
    let val4 = make_string_value("\u{00A0}\u{2003}\u{FEFF}");
    let n4 = crate::value_ops::to_number(JsValue::from_raw_bits(val4));
    assert_eq!(n4, 0.0, "Unicode whitespace-only string should parse as 0");
}

// -------------------------------------------------------------------------
// 212. test_string_to_number_no_legacy_octal
// -------------------------------------------------------------------------

#[test]
fn test_string_to_number_no_legacy_octal() {
    // "010" should be decimal 10, NOT octal 8 (ES2015+/strict mode)
    let val = make_string_value("010");
    let n = crate::value_ops::to_number(JsValue::from_raw_bits(val));
    assert_eq!(n, 10.0, "010 should be decimal 10, not octal 8");

    let val2 = make_string_value("0777");
    let n2 = crate::value_ops::to_number(JsValue::from_raw_bits(val2));
    assert_eq!(n2, 777.0, "0777 should be decimal 777, not octal");
}

// -------------------------------------------------------------------------
// 213. test_string_to_number_infinity
// -------------------------------------------------------------------------

#[test]
fn test_string_to_number_infinity() {
    let val = make_string_value("Infinity");
    let n = crate::value_ops::to_number(JsValue::from_raw_bits(val));
    assert_eq!(n, f64::INFINITY, "Infinity should parse as +Infinity");

    let val2 = make_string_value("-Infinity");
    let n2 = crate::value_ops::to_number(JsValue::from_raw_bits(val2));
    assert_eq!(n2, f64::NEG_INFINITY, "-Infinity should parse as -Infinity");

    let val3 = make_string_value("+Infinity");
    let n3 = crate::value_ops::to_number(JsValue::from_raw_bits(val3));
    assert_eq!(n3, f64::INFINITY, "+Infinity should parse as +Infinity");

    // Whitespace around Infinity
    let val4 = make_string_value("  Infinity  ");
    let n4 = crate::value_ops::to_number(JsValue::from_raw_bits(val4));
    assert_eq!(
        n4,
        f64::INFINITY,
        "Infinity with whitespace should parse as +Infinity"
    );
}

// -------------------------------------------------------------------------
// 214. test_string_to_number_invalid_returns_nan
// -------------------------------------------------------------------------

#[test]
fn test_string_to_number_invalid_returns_nan() {
    let val = make_string_value("abc");
    let n = crate::value_ops::to_number(JsValue::from_raw_bits(val));
    assert!(n.is_nan(), "non-numeric string should return NaN");

    let val2 = make_string_value("0x");
    let n2 = crate::value_ops::to_number(JsValue::from_raw_bits(val2));
    assert!(n2.is_nan(), "bare 0x prefix should return NaN");

    let val3 = make_string_value("0o");
    let n3 = crate::value_ops::to_number(JsValue::from_raw_bits(val3));
    assert!(n3.is_nan(), "bare 0o prefix should return NaN");

    let val4 = make_string_value("0b");
    let n4 = crate::value_ops::to_number(JsValue::from_raw_bits(val4));
    assert!(n4.is_nan(), "bare 0b prefix should return NaN");

    let val5 = make_string_value("0b2");
    let n5 = crate::value_ops::to_number(JsValue::from_raw_bits(val5));
    assert!(n5.is_nan(), "invalid binary digits should return NaN");

    let val6 = make_string_value("0o8");
    let n6 = crate::value_ops::to_number(JsValue::from_raw_bits(val6));
    assert!(n6.is_nan(), "invalid octal digits should return NaN");
}

