#[test]
fn test_same_value_ffi_returns_bool() {
    let nan = JsValue::number(f64::NAN).raw_bits();
    let result = JsValue::from_raw_bits(crate::rt_api::__esc_rt_same_value(nan, nan));
    assert_eq!(
        result.as_bool(),
        Some(true),
        "__esc_rt_same_value(NaN, NaN) should return true"
    );

    let pos = JsValue::number(0.0).raw_bits();
    let neg = JsValue::number(-0.0).raw_bits();
    let result2 = JsValue::from_raw_bits(crate::rt_api::__esc_rt_same_value(pos, neg));
    assert_eq!(
        result2.as_bool(),
        Some(false),
        "__esc_rt_same_value(+0, -0) should return false"
    );
}

