// =========================================================================
// Prototype chain tests (0.3.2)
// =========================================================================

#[test]
fn test_proto_chain_basic_property_lookup() {
    // Create proto with property hello=42
    let proto = crate::rt_api::__esc_rt_create_object();
    let hello_key = make_string_value("hello");
    crate::rt_api::__esc_rt_set_prop(proto, hello_key, JsValue::int(42).raw_bits());

    // Create child with __proto__ = proto
    let child = crate::rt_api::__esc_rt_object_create(proto);

    // child.hello should resolve to 42 via prototype chain
    let hello_key2 = make_string_value("hello");
    let result = crate::rt_api::__esc_rt_get_prop(child, hello_key2);
    assert_eq!(
        JsValue::from_raw_bits(result).as_int(),
        Some(42),
        "prototype chain should resolve hello=42"
    );
}

#[test]
fn test_proto_chain_own_property_shadows_shape_based() {
    // proto.x = 10
    let proto = crate::rt_api::__esc_rt_create_object();
    let x_key = make_string_value("x");
    crate::rt_api::__esc_rt_set_prop(proto, x_key, JsValue::int(10).raw_bits());

    // child.__proto__ = proto, child.x = 20
    let child = crate::rt_api::__esc_rt_object_create(proto);
    let x_key2 = make_string_value("x");
    crate::rt_api::__esc_rt_set_prop(child, x_key2, JsValue::int(20).raw_bits());

    // child.x should return 20 (own shadows prototype)
    let x_key3 = make_string_value("x");
    let result = crate::rt_api::__esc_rt_get_prop(child, x_key3);
    assert_eq!(
        JsValue::from_raw_bits(result).as_int(),
        Some(20),
        "own property should shadow prototype"
    );
}

#[test]
fn test_proto_chain_two_levels() {
    // grandparent.a = 1
    let gp = crate::rt_api::__esc_rt_create_object();
    let a_key = make_string_value("a");
    crate::rt_api::__esc_rt_set_prop(gp, a_key, JsValue::int(1).raw_bits());

    // parent.__proto__ = grandparent, parent.b = 2
    let parent = crate::rt_api::__esc_rt_object_create(gp);
    let b_key = make_string_value("b");
    crate::rt_api::__esc_rt_set_prop(parent, b_key, JsValue::int(2).raw_bits());

    // child.__proto__ = parent
    let child = crate::rt_api::__esc_rt_object_create(parent);

    // child.a should walk two levels
    let a_key2 = make_string_value("a");
    let result_a = crate::rt_api::__esc_rt_get_prop(child, a_key2);
    assert_eq!(
        JsValue::from_raw_bits(result_a).as_int(),
        Some(1),
        "two-level prototype chain should resolve a=1"
    );

    // child.b should walk one level
    let b_key2 = make_string_value("b");
    let result_b = crate::rt_api::__esc_rt_get_prop(child, b_key2);
    assert_eq!(
        JsValue::from_raw_bits(result_b).as_int(),
        Some(2),
        "one-level prototype chain should resolve b=2"
    );
}

#[test]
