#[test]
fn test_proto_chain_set_prototype_of() {
    let obj = crate::rt_api::__esc_rt_create_object();
    let proto = crate::rt_api::__esc_rt_create_object();
    let hello_key = make_string_value("hello");
    crate::rt_api::__esc_rt_set_prop(proto, hello_key, JsValue::int(99).raw_bits());

    // Object.setPrototypeOf(obj, proto)
    let args = [JsValue::from_raw_bits(obj), JsValue::from_raw_bits(proto)];
    let result = crate::rt_api::dispatch_object_static_method(
        "setPrototypeOf",
        2,
        args.as_ptr() as *const u64,
    );
    assert!(result.is_some(), "setPrototypeOf should return Some");

    // obj.hello should now resolve to 99
    let hello_key2 = make_string_value("hello");
    let val = crate::rt_api::__esc_rt_get_prop(obj, hello_key2);
    assert_eq!(
        JsValue::from_raw_bits(val).as_int(),
        Some(99),
        "after setPrototypeOf, obj should inherit hello=99"
    );
}

