#[test]
fn test_proto_chain_switch_prototype() {
    let proto_a = crate::rt_api::__esc_rt_create_object();
    crate::rt_api::__esc_rt_set_prop(
        proto_a,
        make_string_value("from_a"),
        JsValue::int(1).raw_bits(),
    );

    let proto_b = crate::rt_api::__esc_rt_create_object();
    crate::rt_api::__esc_rt_set_prop(
        proto_b,
        make_string_value("from_b"),
        JsValue::int(2).raw_bits(),
    );

    // Start with proto_a
    let obj = crate::rt_api::__esc_rt_object_create(proto_a);
    let a_key = make_string_value("from_a");
    let result = crate::rt_api::__esc_rt_get_prop(obj, a_key);
    assert_eq!(
        JsValue::from_raw_bits(result).as_int(),
        Some(1),
        "should see from_a via proto_a"
    );

    // Switch to proto_b via Object.setPrototypeOf
    let args = [JsValue::from_raw_bits(obj), JsValue::from_raw_bits(proto_b)];
    crate::rt_api::dispatch_object_static_method("setPrototypeOf", 2, args.as_ptr() as *const u64);

    // Now obj should see from_b
    let b_key2 = make_string_value("from_b");
    let result_b = crate::rt_api::__esc_rt_get_prop(obj, b_key2);
    assert_eq!(
        JsValue::from_raw_bits(result_b).as_int(),
        Some(2),
        "after setPrototypeOf, should see from_b"
    );
}

