// =========================================================================
// Inline cache (IC) tests
// =========================================================================

#[test]
fn test_ic_register_site_returns_unique_ids() {
    let id0 = crate::ic::register_ic_site();
    let id1 = crate::ic::register_ic_site();
    let id2 = crate::ic::register_ic_site();
    // IDs must be distinct (monotonically increasing within a thread)
    assert_ne!(id0, id1);
    assert_ne!(id1, id2);
    assert_ne!(id0, id2);
}

#[test]
fn test_ic_get_prop_uncached_returns_correct_value() {
    // Create an object and set a property via the standard path
    let obj = crate::rt_api::__esc_rt_create_object();
    let key = make_string_value("foo");
    let val = JsValue::int(42).raw_bits();
    crate::rt_api::__esc_rt_set_prop(obj, key, val);

    // Now read via IC path — should return the same value
    let ic_id = crate::ic::register_ic_site();
    let result = crate::ic::__esc_rt_ic_get_prop(obj, key, ic_id);
    assert_eq!(
        JsValue::from_raw_bits(result).as_int(),
        Some(42),
        "IC get_prop should return correct value on first (uncached) access"
    );
}

#[test]
fn test_ic_set_prop_uncached_stores_correctly() {
    let obj = crate::rt_api::__esc_rt_create_object();
    let key = make_string_value("bar");
    let val = JsValue::int(99).raw_bits();
    let ic_id = crate::ic::register_ic_site();

    crate::ic::__esc_rt_ic_set_prop(obj, key, val, ic_id);

    // Read back via standard path
    let result = crate::rt_api::__esc_rt_get_prop(obj, key);
    assert_eq!(
        JsValue::from_raw_bits(result).as_int(),
        Some(99),
        "IC set_prop should store value accessible via standard get_prop"
    );
}

#[test]
fn test_ic_mono_cache_hit_returns_same_as_slow_path() {
    let obj = crate::rt_api::__esc_rt_create_object();
    let key = make_string_value("x");
    let val = JsValue::int(7).raw_bits();
    crate::rt_api::__esc_rt_set_prop(obj, key, val);

    let ic_id = crate::ic::register_ic_site();
    // First access fills the mono cache
    let r1 = crate::ic::__esc_rt_ic_get_prop(obj, key, ic_id);
    // Second access should hit the mono cache
    let r2 = crate::ic::__esc_rt_ic_get_prop(obj, key, ic_id);

    assert_eq!(r1, r2, "IC hit should return same value as first access");
    assert_eq!(
        JsValue::from_raw_bits(r2).as_int(),
        Some(7),
        "IC hit should return correct value"
    );
}

#[test]
fn test_ic_poly_promotion_on_second_shape() {
    // Create two objects with different shapes
    let obj1 = crate::rt_api::__esc_rt_create_object();
    let key_a = make_string_value("a");
    crate::rt_api::__esc_rt_set_prop(obj1, key_a, JsValue::int(1).raw_bits());

    let obj2 = crate::rt_api::__esc_rt_create_object();
    let key_b = make_string_value("b");
    let key_a2 = make_string_value("a");
    crate::rt_api::__esc_rt_set_prop(obj2, key_b, JsValue::int(2).raw_bits());
    crate::rt_api::__esc_rt_set_prop(obj2, key_a2, JsValue::int(3).raw_bits());

    let ic_id = crate::ic::register_ic_site();
    // Access obj1.a — fills mono cache
    let r1 = crate::ic::__esc_rt_ic_get_prop(obj1, key_a, ic_id);
    assert_eq!(JsValue::from_raw_bits(r1).as_int(), Some(1));

    // Access obj2.a — different shape, should promote to poly
    let r2 = crate::ic::__esc_rt_ic_get_prop(obj2, key_a2, ic_id);
    assert_eq!(JsValue::from_raw_bits(r2).as_int(), Some(3));
}

#[test]
fn test_ic_megamorphic_after_five_shapes() {
    let ic_id = crate::ic::register_ic_site();
    let key = make_string_value("val");

    // Create 5 objects with different shapes
    for i in 0..5 {
        let obj = crate::rt_api::__esc_rt_create_object();
        // Add i extra properties to create a unique shape
        for j in 0..i {
            let extra_key = make_string_value(&format!("prop{j}"));
            crate::rt_api::__esc_rt_set_prop(obj, extra_key, JsValue::int(0).raw_bits());
        }
        let key_copy = make_string_value("val");
        crate::rt_api::__esc_rt_set_prop(obj, key_copy, JsValue::int(i).raw_bits());

        let result = crate::ic::__esc_rt_ic_get_prop(obj, key, ic_id);
        assert_eq!(
            JsValue::from_raw_bits(result).as_int(),
            Some(i),
            "IC should return correct value for shape variant {i}"
        );
    }
}

#[test]
fn test_ic_epoch_invalidation() {
    let obj = crate::rt_api::__esc_rt_create_object();
    let key = make_string_value("p");
    crate::rt_api::__esc_rt_set_prop(obj, key, JsValue::int(10).raw_bits());

    let ic_id = crate::ic::register_ic_site();
    // Fill cache
    let r1 = crate::ic::__esc_rt_ic_get_prop(obj, key, ic_id);
    assert_eq!(JsValue::from_raw_bits(r1).as_int(), Some(10));

    // Bump epoch (simulating a prototype mutation)
    crate::ic::bump_prototype_epoch();

    // Access again — should still return correct value (slow path after invalidation)
    let r2 = crate::ic::__esc_rt_ic_get_prop(obj, key, ic_id);
    assert_eq!(
        JsValue::from_raw_bits(r2).as_int(),
        Some(10),
        "IC should return correct value after epoch invalidation"
    );
}

#[test]
fn test_ic_epoch_bump_increments() {
    let e1 = crate::ic::current_prototype_epoch();
    crate::ic::bump_prototype_epoch();
    let e2 = crate::ic::current_prototype_epoch();
    assert_eq!(e2, e1.wrapping_add(1), "bump should increment epoch by 1");
}

#[test]
fn test_ic_get_prop_non_object_returns_undefined() {
    // Calling IC on a non-object value should not crash
    let ic_id = crate::ic::register_ic_site();
    let key = make_string_value("x");
    let result = crate::ic::__esc_rt_ic_get_prop(JsValue::int(5).raw_bits(), key, ic_id);
    // Non-objects return undefined for property access
    assert!(
        JsValue::from_raw_bits(result).is_undefined(),
        "IC get_prop on non-object should return undefined"
    );
}

