#[test]
fn test_create_object_literal_cached_shape() {
    // Creating two objects with the same key sequence should reuse the cached shape
    let key_a = make_string_value("a");
    let key_b = make_string_value("b");
    let kvpairs1: Vec<u64> = vec![
        key_a,
        JsValue::int(10).raw_bits(),
        key_b,
        JsValue::int(20).raw_bits(),
    ];
    let kvpairs2: Vec<u64> = vec![
        make_string_value("a"),
        JsValue::int(30).raw_bits(),
        make_string_value("b"),
        JsValue::int(40).raw_bits(),
    ];

    let obj1 =
        unsafe { crate::rt_api::__esc_rt_create_object_literal(2, kvpairs1.as_ptr() as u64) };
    let obj2 =
        unsafe { crate::rt_api::__esc_rt_create_object_literal(2, kvpairs2.as_ptr() as u64) };

    // Both should have the same shape_id (cached)
    use crate::tagged_obj::deref_tagged;
    let u1 = unsafe { deref_tagged::<UnifiedObject>(obj1) };
    let u2 = unsafe { deref_tagged::<UnifiedObject>(obj2) };
    assert!(
        u1.is_some() && u2.is_some(),
        "both should be unified objects"
    );
    assert_eq!(
        u1.unwrap().shape_id,
        u2.unwrap().shape_id,
        "same key sequence should produce the same shape"
    );

    // But different values
    let a1 = crate::rt_api::__esc_rt_get_prop(obj1, make_string_value("a"));
    let a2 = crate::rt_api::__esc_rt_get_prop(obj2, make_string_value("a"));
    assert_eq!(JsValue::from_raw_bits(a1).as_int(), Some(10));
    assert_eq!(JsValue::from_raw_bits(a2).as_int(), Some(30));
}

#[test]
fn test_create_object_literal_different_shapes() {
    // Objects with different key sequences should have different shapes
    let kvpairs1: Vec<u64> = vec![make_string_value("p"), JsValue::int(1).raw_bits()];
    let kvpairs2: Vec<u64> = vec![make_string_value("q"), JsValue::int(2).raw_bits()];

    let obj1 =
        unsafe { crate::rt_api::__esc_rt_create_object_literal(1, kvpairs1.as_ptr() as u64) };
    let obj2 =
        unsafe { crate::rt_api::__esc_rt_create_object_literal(1, kvpairs2.as_ptr() as u64) };

    use crate::tagged_obj::deref_tagged;
    let u1 = unsafe { deref_tagged::<UnifiedObject>(obj1) };
    let u2 = unsafe { deref_tagged::<UnifiedObject>(obj2) };
    assert!(u1.is_some() && u2.is_some());
    assert_ne!(
        u1.unwrap().shape_id,
        u2.unwrap().shape_id,
        "different key sequences should produce different shapes"
    );
}

#[test]
fn test_create_object_literal_mutation_after_create() {
    // After creating with CreateObjectLiteral, setting new properties should still work
    let kvpairs: Vec<u64> = vec![make_string_value("x"), JsValue::int(1).raw_bits()];
    let obj = unsafe { crate::rt_api::__esc_rt_create_object_literal(1, kvpairs.as_ptr() as u64) };

    // Add a new property via set_prop
    crate::rt_api::__esc_rt_set_prop(obj, make_string_value("y"), JsValue::int(42).raw_bits());

    // Both original and new property should work
    let x = crate::rt_api::__esc_rt_get_prop(obj, make_string_value("x"));
    let y = crate::rt_api::__esc_rt_get_prop(obj, make_string_value("y"));
    assert_eq!(JsValue::from_raw_bits(x).as_int(), Some(1));
    assert_eq!(JsValue::from_raw_bits(y).as_int(), Some(42));
}

