#[test]
fn test_define_accessor_property_getter_only() {
    let interner = Interner::new();
    let mut shapes = ShapeTable::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    let getter_fn = JsValue::int(42); // Stand-in for a function

    let opts = property::DefinePropertyOptions {
        getter: Some(getter_fn),
        setter: None,
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    let result = obj.define_own_property("x", &opts, &mut shapes, &interner);
    assert!(result.is_ok());

    // The property should exist and be an accessor
    assert!(obj.is_accessor_property("x", &shapes, &interner));

    // Getter should return the function we stored
    let getter = obj.get_accessor_getter("x", &shapes, &interner);
    assert!(getter.is_some());
    assert_eq!(getter.unwrap().as_int(), Some(42));

    // Setter should be undefined
    let setter = obj.get_accessor_setter("x", &shapes, &interner);
    assert!(setter.is_some());
    assert!(setter.unwrap().is_undefined());
}

