#[test]
fn test_own_property_descriptor_methods() {
    // Test the is_data/is_accessor/is_enumerable/is_configurable methods
    let data_desc = property::OwnPropertyDescriptor::Data {
        value: JsValue::int(1),
        writable: true,
        enumerable: true,
        configurable: false,
    };
    assert!(data_desc.is_data());
    assert!(!data_desc.is_accessor());
    assert!(data_desc.is_enumerable());
    assert!(!data_desc.is_configurable());

    let accessor_desc = property::OwnPropertyDescriptor::Accessor {
        getter: JsValue::undefined(),
        setter: JsValue::undefined(),
        enumerable: false,
        configurable: true,
    };
    assert!(!accessor_desc.is_data());
    assert!(accessor_desc.is_accessor());
    assert!(!accessor_desc.is_enumerable());
    assert!(accessor_desc.is_configurable());
}

#[test]
fn test_define_property_options_descriptor_type_detection() {
    let opts_data = property::DefinePropertyOptions {
        value: Some(JsValue::int(1)),
        writable: Some(true),
        ..Default::default()
    };
    assert!(opts_data.is_data_descriptor());
    assert!(!opts_data.is_accessor_descriptor());
    assert!(!opts_data.is_invalid_mixed());

    let opts_accessor = property::DefinePropertyOptions {
        getter: Some(JsValue::int(1)),
        setter: Some(JsValue::int(2)),
        ..Default::default()
    };
    assert!(!opts_accessor.is_data_descriptor());
    assert!(opts_accessor.is_accessor_descriptor());
    assert!(!opts_accessor.is_invalid_mixed());

    let opts_mixed = property::DefinePropertyOptions {
        value: Some(JsValue::int(1)),
        getter: Some(JsValue::int(2)),
        ..Default::default()
    };
    assert!(opts_mixed.is_data_descriptor());
    assert!(opts_mixed.is_accessor_descriptor());
    assert!(opts_mixed.is_invalid_mixed());
}

#[test]
fn test_update_accessor_property_getter() {
    let interner = Interner::new();
    let mut shapes = ShapeTable::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Define accessor
    let opts = property::DefinePropertyOptions {
        getter: Some(JsValue::int(10)),
        setter: Some(JsValue::int(20)),
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("x", &opts, &mut shapes, &interner)
        .unwrap();

    // Update just the getter
    let update_opts = property::DefinePropertyOptions {
        getter: Some(JsValue::int(30)),
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("x", &update_opts, &mut shapes, &interner)
        .unwrap();

    // Getter should be updated, setter should be unchanged
    assert_eq!(
        obj.get_accessor_getter("x", &shapes, &interner)
            .unwrap()
            .as_int(),
        Some(30)
    );
    assert_eq!(
        obj.get_accessor_setter("x", &shapes, &interner)
            .unwrap()
            .as_int(),
        Some(20)
    );
}

