#[test]
fn test_construct_with_prototype() {
    // new Constructor() should set the __proto__ of the new object to
    // Constructor.prototype when prototype is an object
    let ctor = crate::rt_api::__esc_rt_create_closure(0, 0, 0);
    let proto = crate::rt_api::__esc_rt_create_object();

    // Set a marker property on the prototype
    let marker_key = crate::rt_api::make_rt_string("marker".to_string());
    crate::rt_api::__esc_rt_set_prop(proto, marker_key, JsValue::int(999).raw_bits());

    // Set Constructor.prototype = proto
    let proto_key = crate::rt_api::make_rt_string("prototype".to_string());
    crate::rt_api::__esc_rt_set_prop(ctor, proto_key, proto);

    let result = unsafe { crate::rt_api::__esc_rt_call_new(ctor, 0, std::ptr::null()) };
    assert!(
        JsValue::from_raw_bits(result).is_object(),
        "result must be an object"
    );

    // Check that __proto__ was set correctly
    let proto_link_key = crate::rt_api::make_rt_string("__proto__".to_string());
    let result_proto = crate::rt_api::__esc_rt_get_prop(result, proto_link_key);
    assert_eq!(
        result_proto, proto,
        "new obj.__proto__ should be Constructor.prototype"
    );
}

