#[test]
fn test_new_target_cleared_for_indirect_call() {
    // When a constructor body makes a regular call via __esc_rt_call_indirect,
    // the called function should see new.target === undefined.
    //
    // Simulate: set CURRENT_NEW_TARGET to something, then call_indirect
    // should clear it for the duration of the call.
    let ctor = crate::rt_api::__esc_rt_create_closure(0, 0, 0);

    // Manually set new.target (simulating being inside a constructor)
    crate::rt_api::CURRENT_NEW_TARGET.with(|cell| cell.set(ctor));

    // Call an undefined callee via call_indirect (will return undefined)
    let callee = JsValue::undefined().raw_bits();
    let _result = unsafe { crate::rt_api::__esc_rt_call_indirect(callee, 0, std::ptr::null()) };

    // After call_indirect returns, CURRENT_NEW_TARGET should be restored
    let nt = crate::rt_api::CURRENT_NEW_TARGET.with(|cell| cell.get());
    assert_eq!(
        nt, ctor,
        "CURRENT_NEW_TARGET should be restored after call_indirect"
    );

    // Clean up
    crate::rt_api::CURRENT_NEW_TARGET.with(|cell| cell.set(0));
}

#[test]
fn test_construct_generator_throws_type_error() {
    // Generators cannot be constructed with new (ES spec 15.5.2)
    crate::exceptions::clear_exception();

    let ctor = crate::rt_api::__esc_rt_create_closure(0, 0, 0);

    // Set the __is_generator flag on the closure (matching desugar behavior)
    let gen_key = crate::rt_api::make_rt_string("__is_generator".to_string());
    crate::rt_api::__esc_rt_set_prop(ctor, gen_key, JsValue::bool(true).raw_bits());

    let _result = unsafe { crate::rt_api::__esc_rt_call_new(ctor, 0, std::ptr::null()) };

    // Should have thrown a TypeError
    assert!(
        crate::exceptions::is_exception(),
        "new Generator() should throw a TypeError"
    );

    crate::exceptions::clear_exception();
}

