#[test]
fn test_new_target_thread_local_isolation() {
    // Verify that CURRENT_NEW_TARGET is properly isolated per thread
    // (thread_local ensures this, but let's verify the API)
    crate::rt_api::CURRENT_NEW_TARGET.with(|cell| {
        // Start at 0 (undefined)
        let initial = cell.get();
        assert_eq!(initial, 0, "CURRENT_NEW_TARGET should start at 0");

        // Set it
        cell.set(0xDEAD);
        assert_eq!(cell.get(), 0xDEAD);

        // Reset
        cell.set(0);
        assert_eq!(cell.get(), 0);
    });
}

