    let _result = unsafe { crate::rt_api::__esc_rt_call_new(ctor, 0, std::ptr::null()) };

    // After construct, CURRENT_THIS should be restored to original
    let restored = crate::rt_api::CURRENT_THIS.with(|cell| cell.get());
