#[test]
fn test_prototype_cycle_detection_indirect() {
    // a -> b -> a would be a cycle
    crate::exceptions::clear_exception();

    let a = crate::rt_api::__esc_rt_create_object();
    let b = crate::rt_api::__esc_rt_create_object();

    // Set b's prototype to a (this is fine)
    let args1 = [JsValue::from_raw_bits(b), JsValue::from_raw_bits(a)];
    crate::rt_api::dispatch_object_static_method("setPrototypeOf", 2, args1.as_ptr() as *const u64);
    assert!(
        !crate::exceptions::is_exception(),
        "Setting b -> a should be fine"
    );

    // Now set a's prototype to b — this would create a -> b -> a cycle
    let args2 = [JsValue::from_raw_bits(a), JsValue::from_raw_bits(b)];
    crate::rt_api::dispatch_object_static_method("setPrototypeOf", 2, args2.as_ptr() as *const u64);
    assert!(
        crate::exceptions::is_exception(),
        "Setting a -> b when b -> a already exists should throw TypeError (cycle)"
    );
    crate::exceptions::clear_exception();
}

#[test]
fn test_prototype_non_cyclic_chain_allowed() {
    // a -> b -> c should be fine (no cycle)
    crate::exceptions::clear_exception();

    let a = crate::rt_api::__esc_rt_create_object();
    let b = crate::rt_api::__esc_rt_create_object();
    let c = crate::rt_api::__esc_rt_create_object();

    // Set b's prototype to c
    let args1 = [JsValue::from_raw_bits(b), JsValue::from_raw_bits(c)];
    crate::rt_api::dispatch_object_static_method("setPrototypeOf", 2, args1.as_ptr() as *const u64);
    assert!(!crate::exceptions::is_exception());

    // Set a's prototype to b — a -> b -> c, no cycle
    let args2 = [JsValue::from_raw_bits(a), JsValue::from_raw_bits(b)];
    crate::rt_api::dispatch_object_static_method("setPrototypeOf", 2, args2.as_ptr() as *const u64);
    assert!(
        !crate::exceptions::is_exception(),
        "a -> b -> c should not throw (no cycle)"
    );

    // Verify a can access c's properties via prototype chain
    crate::rt_api::__esc_rt_set_prop(c, make_string_value("deep"), JsValue::int(99).raw_bits());
    let val = crate::rt_api::__esc_rt_get_prop(a, make_string_value("deep"));
    assert_eq!(
        JsValue::from_raw_bits(val).as_int(),
        Some(99),
        "a should inherit from c through b"
    );
}

#[test]
fn test_prototype_set_null_no_cycle_check() {
    // Object.setPrototypeOf(obj, null) should always work
    crate::exceptions::clear_exception();

    let obj = crate::rt_api::__esc_rt_create_object();
    let args = [JsValue::from_raw_bits(obj), JsValue::null()];
    crate::rt_api::dispatch_object_static_method("setPrototypeOf", 2, args.as_ptr() as *const u64);

    assert!(
        !crate::exceptions::is_exception(),
        "setPrototypeOf(obj, null) should not throw"
    );
}

