#[test]
fn test_symbol_property_not_in_object_keys() {
    let obj = crate::rt_api::__esc_rt_create_object();

    // Set a string property and a symbol property
    let str_key = crate::rt_api::make_rt_string("visible".to_string());
    crate::rt_api::__esc_rt_set_prop(obj, str_key, JsValue::int(1).raw_bits());

    let sym_id = crate::symbol::create_symbol(Some("hidden"));
    let sym_key = JsValue::symbol(sym_id).raw_bits();
    crate::rt_api::__esc_rt_set_prop(obj, sym_key, JsValue::int(2).raw_bits());

    // Object.keys should only return string keys
    let keys = crate::rt_api::__esc_rt_object_keys(obj);
    let keys_val = JsValue::from_raw_bits(keys);
    assert!(keys_val.is_object());

    let uni =
        unsafe { crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(keys) };
    let u = uni.unwrap();
    assert_eq!(
        u.as_array_length(),
        Some(1),
        "Object.keys should only return string keys, not symbol keys"
    );
}

#[test]
fn test_symbol_property_in_get_own_property_symbols() {
    let obj = crate::rt_api::__esc_rt_create_object();

    // Set string and symbol properties
    let str_key = crate::rt_api::make_rt_string("name".to_string());
    crate::rt_api::__esc_rt_set_prop(obj, str_key, JsValue::int(1).raw_bits());

    let sym_id = crate::symbol::create_symbol(Some("sym_prop"));
    let sym_key = JsValue::symbol(sym_id).raw_bits();
    crate::rt_api::__esc_rt_set_prop(obj, sym_key, JsValue::int(2).raw_bits());

    // Object.getOwnPropertySymbols should return the symbol key
    let args = [JsValue::from_raw_bits(obj)];
    let result = crate::rt_api::dispatch_object_static_method(
        "getOwnPropertySymbols",
        1,
        args.as_ptr() as *const u64,
    );
    let result_bits = result.unwrap();
    let result_val = JsValue::from_raw_bits(result_bits);
    assert!(result_val.is_object());

    let uni = unsafe {
        crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(result_bits)
    };
    let u = uni.unwrap();
    assert_eq!(
        u.as_array_length(),
        Some(1),
        "should have exactly 1 symbol key"
    );
    let elem = u.get_element(0).unwrap();
    assert!(elem.is_symbol(), "element should be a symbol value");
    assert_eq!(elem.as_symbol(), Some(sym_id));
}

