#[test]
fn test_well_known_symbols_are_all_different() {
    let sym_str = crate::rt_api::make_rt_string("Symbol".to_string());

    let iter_key = crate::rt_api::make_rt_string("iterator".to_string());
    let prim_key = crate::rt_api::make_rt_string("toPrimitive".to_string());
    let has_key = crate::rt_api::make_rt_string("hasInstance".to_string());
    let tag_key = crate::rt_api::make_rt_string("toStringTag".to_string());
    let async_key = crate::rt_api::make_rt_string("asyncIterator".to_string());
    let species_key = crate::rt_api::make_rt_string("species".to_string());

    let iter = crate::rt_api::__esc_rt_get_prop(sym_str, iter_key);
    let prim = crate::rt_api::__esc_rt_get_prop(sym_str, prim_key);
    let has = crate::rt_api::__esc_rt_get_prop(sym_str, has_key);
    let tag = crate::rt_api::__esc_rt_get_prop(sym_str, tag_key);
    let async_it = crate::rt_api::__esc_rt_get_prop(sym_str, async_key);
    let species = crate::rt_api::__esc_rt_get_prop(sym_str, species_key);

    let all = [iter, prim, has, tag, async_it, species];
    for i in 0..all.len() {
        for j in (i + 1)..all.len() {
            assert_ne!(
                all[i], all[j],
                "well-known symbols at index {i} and {j} should be different"
            );
        }
    }
}

#[test]
fn test_well_known_symbols_are_stable_across_accesses() {
    let sym_str = crate::rt_api::make_rt_string("Symbol".to_string());
    let key = crate::rt_api::make_rt_string("iterator".to_string());

    let first = crate::rt_api::__esc_rt_get_prop(sym_str, key);
    let second = crate::rt_api::__esc_rt_get_prop(sym_str, key);

    assert_eq!(
        first, second,
        "Symbol.iterator should return the same value on repeated access"
    );
}

