#[test]
fn test_to_primitive_falls_back_to_ordinary_when_no_symbol() {
    // An ordinary object without [Symbol.toPrimitive] should still
    // use the valueOf/toString fallback path.
    let obj = crate::rt_api::__esc_rt_create_object();
    let val = JsValue::from_raw_bits(obj);
    let prim = crate::value_ops::to_primitive(val, crate::value_ops::ToPrimitiveHint::String);
    // Should get "[object Object]" from default toString
    assert!(prim.is_string(), "ToPrimitive should return a string");
    let s = crate::string_ops::get_string_data(prim);
    assert_eq!(
        s, "[object Object]",
        "ordinary object without Symbol.toPrimitive should fall back to toString"
    );
}

#[test]
fn test_to_primitive_with_symbol_to_primitive_on_object() {
    // Set [Symbol.toPrimitive] as a native function on an object
    let obj = crate::rt_api::__esc_rt_create_object();

    // Set a symbol-keyed property with a known value (not callable, so it
    // should be ignored and fall back to OrdinaryToPrimitive)
    let sym_key = JsValue::symbol(crate::symbol::SYMBOL_TO_PRIMITIVE).raw_bits();
    let non_callable_val = JsValue::int(42).raw_bits();
    crate::rt_api::__esc_rt_set_prop(obj, sym_key, non_callable_val);

    // Since the Symbol.toPrimitive is not callable, it should fall through
    // to OrdinaryToPrimitive
    let val = JsValue::from_raw_bits(obj);
    let prim = crate::value_ops::to_primitive(val, crate::value_ops::ToPrimitiveHint::Number);
    // Should fall through to default (OrdinaryToPrimitive)
    assert!(
        !prim.is_object() || prim.is_string(),
        "ToPrimitive should return a primitive even when Symbol.toPrimitive is non-callable"
    );
}

