#[test]
fn test_to_primitive_on_primitives_passthrough() {
    // Primitives should pass through ToPrimitive unchanged
    let cases = [
        JsValue::int(42),
        JsValue::number(2.5),
        JsValue::bool(true),
        JsValue::null(),
        JsValue::undefined(),
        JsValue::symbol(1),
    ];
    for val in &cases {
        let result =
            crate::value_ops::to_primitive(*val, crate::value_ops::ToPrimitiveHint::Default);
        assert_eq!(
            result.raw_bits(),
            val.raw_bits(),
            "ToPrimitive on a primitive should return it unchanged"
        );
    }
}

