#[test]
fn test_install_private_field_adds_to_shape() {
    crate::exceptions::clear_exception();
    use crate::internal_data::UnifiedObject;
    use crate::rt_api::__esc_rt_private_field_has;
    use crate::tagged_obj::{ObjTag, TaggedObj, deref_tagged};

    // Directly create and test without going through __esc_rt_create_object
    let obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);
    let obj_bits = TaggedObj::boxed(ObjTag::Unified, obj);

    let pid = JsValue::int(0).raw_bits();
    let val = JsValue::int(42).raw_bits();
    crate::rt_api::__esc_rt_install_private_field(obj_bits, pid, val);

    // Verify the field exists via has check
    let has_result = __esc_rt_private_field_has(obj_bits, pid);
    let has_val = JsValue::from_raw_bits(has_result);
    assert_eq!(
        has_val.as_bool(),
        Some(true),
        "private field should exist after install"
    );

    // Directly inspect the object
    let uni = unsafe { deref_tagged::<UnifiedObject>(obj_bits) };
    let u = uni.expect("should be valid unified object");
    assert_eq!(u.slots.len(), 1, "should have 1 slot after install");
    assert_eq!(u.slots[0].as_int(), Some(42), "slot 0 should be int 42");

    // Now test via get API
    let result = crate::rt_api::__esc_rt_private_field_get(obj_bits, pid);
    let v = JsValue::from_raw_bits(result);
    assert_eq!(v.as_int(), Some(42));
}

