#[test]
fn test_two_classes_same_field_name_isolated() {
    crate::exceptions::clear_exception();
    use crate::internal_data::UnifiedObject;
    use crate::rt_api::{
        __esc_rt_install_private_field, __esc_rt_private_field_get, __esc_rt_private_field_has,
    };
    use crate::tagged_obj::{ObjTag, TaggedObj};
    // Simulate two classes each with #x, but different IDs
    let obj_a = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE),
    );
    let pid_a = JsValue::int(0).raw_bits();
    __esc_rt_install_private_field(obj_a, pid_a, JsValue::int(100).raw_bits());

    let obj_b = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE),
    );
    let pid_b = JsValue::int(1).raw_bits();
    __esc_rt_install_private_field(obj_b, pid_b, JsValue::int(200).raw_bits());

    // obj_a has pid_a but not pid_b
    let has_a = JsValue::from_raw_bits(__esc_rt_private_field_has(obj_a, pid_a));
    assert_eq!(has_a.as_bool(), Some(true));
    let has_b = JsValue::from_raw_bits(__esc_rt_private_field_has(obj_a, pid_b));
    assert_eq!(has_b.as_bool(), Some(false));

    // obj_b has pid_b but not pid_a
    let has_a2 = JsValue::from_raw_bits(__esc_rt_private_field_has(obj_b, pid_a));
    assert_eq!(has_a2.as_bool(), Some(false));
    let has_b2 = JsValue::from_raw_bits(__esc_rt_private_field_has(obj_b, pid_b));
    assert_eq!(has_b2.as_bool(), Some(true));

    // Values are correct
    let val_a = JsValue::from_raw_bits(__esc_rt_private_field_get(obj_a, pid_a));
    assert_eq!(val_a.as_int(), Some(100));
    let val_b = JsValue::from_raw_bits(__esc_rt_private_field_get(obj_b, pid_b));
    assert_eq!(val_b.as_int(), Some(200));
}

