#[test]
fn test_instanceof_prototype_chain_walk() {
    crate::exceptions::clear_exception();
    // Per ES spec, instanceof requires a callable RHS.
    // Plain objects are not callable, so they throw TypeError.
    // Use a string-valued builtin constructor instead (our internal
    // representation for builtins uses string names).
    let name = crate::rt_api::make_rt_string("TypeError".to_string());
    let err = crate::rt_api::__esc_rt_create_error(
        crate::exceptions::error_tag::TYPE_ERROR,
        crate::rt_api::make_rt_string("test".to_string()),
    );
    let result = crate::rt_api::__esc_rt_instanceof(err, name);
    assert_eq!(
        JsValue::from_raw_bits(result).as_bool(),
        Some(true),
        "TypeError instance should be instanceof TypeError"
    );
}

