// -------------------------------------------------------------------------
// instanceof: Symbol.hasInstance
// -------------------------------------------------------------------------

#[test]
fn test_instanceof_symbol_has_instance_native_func() {
    crate::exceptions::clear_exception();
    use crate::internal_data::UnifiedObject;
    use crate::tagged_obj::{ObjTag, TaggedObj};

    // Create a constructor object with Symbol.hasInstance set to a native function
    // that always returns true
    let ctor = crate::rt_api::__esc_rt_create_object();

    // Create a native function that returns true
    fn always_true(_ctx: u64) -> u64 {
        JsValue::bool(true).raw_bits()
    }
    let has_instance_fn =
        TaggedObj::boxed(ObjTag::Unified, UnifiedObject::native_func(always_true, 0));

    // Set Symbol.hasInstance property on the constructor
    let sym_key = JsValue::symbol(crate::symbol::SYMBOL_HAS_INSTANCE).raw_bits();
    crate::rt_api::__esc_rt_set_prop(ctor, sym_key, has_instance_fn);

    // Any object should be instanceof the constructor since Symbol.hasInstance returns true
    let obj = crate::rt_api::__esc_rt_create_object();
    let result = crate::rt_api::__esc_rt_instanceof(obj, ctor);
    assert_eq!(
        JsValue::from_raw_bits(result).as_bool(),
        Some(true),
        "Symbol.hasInstance returning true should override prototype check"
    );
}

#[test]
fn test_instanceof_symbol_has_instance_returns_false() {
    crate::exceptions::clear_exception();
    use crate::internal_data::UnifiedObject;
    use crate::tagged_obj::{ObjTag, TaggedObj};

    // Create a constructor with Symbol.hasInstance that always returns false
    let ctor = crate::rt_api::__esc_rt_create_object();

    fn always_false(_ctx: u64) -> u64 {
        JsValue::bool(false).raw_bits()
    }
    let has_instance_fn =
        TaggedObj::boxed(ObjTag::Unified, UnifiedObject::native_func(always_false, 0));

    let sym_key = JsValue::symbol(crate::symbol::SYMBOL_HAS_INSTANCE).raw_bits();
    crate::rt_api::__esc_rt_set_prop(ctor, sym_key, has_instance_fn);

    // Even if obj has matching prototype, Symbol.hasInstance returning false overrides
    let proto = crate::rt_api::__esc_rt_create_object();
    let proto_key = crate::rt_api::make_rt_string("prototype".to_string());
    crate::rt_api::__esc_rt_set_prop(ctor, proto_key, proto);
    let obj = crate::rt_api::__esc_rt_create_object();
    let proto_link_key = crate::rt_api::make_rt_string("__proto__".to_string());
    crate::rt_api::__esc_rt_set_prop(obj, proto_link_key, proto);

    let result = crate::rt_api::__esc_rt_instanceof(obj, ctor);
    assert_eq!(
        JsValue::from_raw_bits(result).as_bool(),
        Some(false),
        "Symbol.hasInstance returning false should override prototype chain"
    );
}

