// -------------------------------------------------------------------------
// error_name covers all tags
// -------------------------------------------------------------------------

#[test]
fn test_error_name_all_tags() {
    use crate::exceptions::{error_name, error_tag};
    assert_eq!(error_name(error_tag::ERROR), "Error");
    assert_eq!(error_name(error_tag::TYPE_ERROR), "TypeError");
    assert_eq!(error_name(error_tag::RANGE_ERROR), "RangeError");
    assert_eq!(error_name(error_tag::REFERENCE_ERROR), "ReferenceError");
    assert_eq!(error_name(error_tag::SYNTAX_ERROR), "SyntaxError");
    assert_eq!(error_name(error_tag::URI_ERROR), "URIError");
    assert_eq!(error_name(error_tag::EVAL_ERROR), "EvalError");
    // Unknown tag falls back to "Error"
    assert_eq!(error_name(99), "Error");
}

