// -------------------------------------------------------------------------
// 0.4.28: Symbol.iterator wired into iter_init
// -------------------------------------------------------------------------

#[test]
fn test_iter_init_custom_iterable_via_symbol_iterator() {
    crate::exceptions::clear_exception();
    // Create an object and install a [Symbol.iterator] method on it
    let obj = crate::rt_api::__esc_rt_create_object();

    // Create a "next counter" object that acts as the iterator
    let iter_obj = crate::rt_api::__esc_rt_create_object();
    let count_key = crate::rt_api::make_rt_string("count".to_string());
    crate::rt_api::__esc_rt_set_prop(iter_obj, count_key, JsValue::int(0).raw_bits());

    // Install [Symbol.iterator] as a native func that returns `this`
    // (the object itself is what iter_init sees, and it delegates to
    // the custom iterator path when Symbol.iterator is found)
    let sym_iter = JsValue::symbol(crate::symbol::SYMBOL_ITERATOR).raw_bits();
    // Create a native function that returns `this`
    let native_fn = crate::tagged_obj::TaggedObj::boxed(
        crate::tagged_obj::ObjTag::Unified,
        UnifiedObject::native_func(
            |_ctx| crate::rt_api::CURRENT_THIS.with(|cell| cell.get()),
            0,
        ),
    );
    crate::rt_api::__esc_rt_set_prop(obj, sym_iter, native_fn);

    // Verify the symbol property is installed
    let retrieved = crate::rt_api::__esc_rt_get_prop(obj, sym_iter);
    assert!(
        !JsValue::from_raw_bits(retrieved).is_undefined(),
        "[Symbol.iterator] should be installed on the object"
    );
}

