#[test]
fn test_generator_symbol_iterator_returns_this() {
    crate::exceptions::clear_exception();
    // Create a generator object
    let state = crate::rt_api::__esc_rt_create_object();
    let key = crate::rt_api::make_rt_string("state_index".to_string());
    crate::rt_api::__esc_rt_set_prop(state, key, JsValue::int(-1).raw_bits());
    let generator = crate::rt_api::__esc_rt_create_generator(state, 0);

    // Get [Symbol.iterator] method
    let sym_key = JsValue::symbol(crate::symbol::SYMBOL_ITERATOR).raw_bits();
    let method = crate::rt_api::__esc_rt_get_prop(generator, sym_key);
    assert!(
        !JsValue::from_raw_bits(method).is_undefined(),
        "Generator should have [Symbol.iterator]"
    );

    // Call [Symbol.iterator]() with this=generator
    crate::rt_api::CURRENT_THIS.with(|cell| cell.set(generator));
    let result = unsafe { crate::rt_api::__esc_rt_call_indirect(method, 0, std::ptr::null()) };
    assert_eq!(
        result, generator,
        "Generator[Symbol.iterator]() should return the generator itself"
    );
}

