// -------------------------------------------------------------------------
// Iterator protocol: .next() returns {value, done}
// -------------------------------------------------------------------------

#[test]
fn test_iterator_result_has_value_and_done() {
    crate::exceptions::clear_exception();
    let arr = crate::rt_api::__esc_rt_create_empty_array(0);
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(42).raw_bits());
    let iter = crate::rt_api::__esc_rt_iter_init(arr);
    let result = crate::rt_api::__esc_rt_iter_next(iter);
    let value = crate::rt_api::__esc_rt_iter_value(result);
    let done = crate::rt_api::__esc_rt_iter_done(result);
    assert_eq!(
        JsValue::from_raw_bits(value).as_int(),
        Some(42),
        "iterator result .value should be 42"
    );
    assert_eq!(
        JsValue::from_raw_bits(done).as_bool(),
        Some(false),
        "iterator result .done should be false"
    );
}

#[test]
fn test_iterator_result_done_after_exhaustion() {
    crate::exceptions::clear_exception();
    let arr = crate::rt_api::__esc_rt_create_empty_array(0);
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(1).raw_bits());
    let iter = crate::rt_api::__esc_rt_iter_init(arr);
    // Consume the single element
    let _r1 = crate::rt_api::__esc_rt_iter_next(iter);
    // Now should be done
    let r2 = crate::rt_api::__esc_rt_iter_next(iter);
    let done = crate::rt_api::__esc_rt_iter_done(r2);
    assert_eq!(
        JsValue::from_raw_bits(done).as_bool(),
        Some(true),
        "iterator should be done after all elements consumed"
    );
}

