// -------------------------------------------------------------------------
// test_async_wrap_returns_promise
// -------------------------------------------------------------------------

#[test]
fn test_async_wrap_returns_promise() {
    crate::exceptions::clear_exception();
    // Create a "done" generator (state_index = -2)
    let state = crate::rt_api::__esc_rt_create_object();
    let si_key = crate::rt_api::make_rt_string("state_index".to_string());
    crate::rt_api::__esc_rt_set_prop(
        state,
        si_key,
        JsValue::int(crate::generator::STATE_DONE).raw_bits(),
    );
    let generator = crate::rt_api::__esc_rt_create_generator(state, 0);

    let result = crate::rt_api::__esc_rt_async_wrap(generator);
    let val = JsValue::from_raw_bits(result);
    assert!(
        val.is_object(),
        "async_wrap should return an object (Promise)"
    );

    // Check it's a Promise
    let tag = crate::tagged_obj::read_obj_tag(result);
    assert_eq!(tag, Some(crate::tagged_obj::ObjTag::Unified as u8));
    let uni =
        unsafe { crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(result) };
    assert!(uni.is_some());
    assert_eq!(
        uni.unwrap().kind,
        crate::internal_data::InternalKind::Promise
    );
}

// -------------------------------------------------------------------------
// test_async_wrap_done_generator_resolves_promise
// -------------------------------------------------------------------------

#[test]
fn test_async_wrap_done_generator_resolves_promise() {
    crate::exceptions::clear_exception();
    use crate::promise::PromiseState;

    // A done generator returns {value: undefined, done: true} from .next()
    // The async_wrap should resolve the promise with undefined
    let state = crate::rt_api::__esc_rt_create_object();
    let si_key = crate::rt_api::make_rt_string("state_index".to_string());
    crate::rt_api::__esc_rt_set_prop(
        state,
        si_key,
        JsValue::int(crate::generator::STATE_DONE).raw_bits(),
    );
    let generator = crate::rt_api::__esc_rt_create_generator(state, 0);

    let prom_bits = crate::rt_api::__esc_rt_async_wrap(generator);

    // Drain microtasks to process all pending reactions
    crate::promise::drain_microtasks();

    // The promise should be fulfilled
    let uni = unsafe {
        crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(prom_bits)
    };
    let u = uni.unwrap();
    if let Some(crate::internal_data::InternalData::Promise { inner }) = u.internal_data() {
        // The generator returns {value: undefined, done: true} immediately
        // so the promise should be resolved (though the value depends on
        // whether the result was properly extracted)
        assert_eq!(
            inner.state,
            PromiseState::Fulfilled,
            "promise should be fulfilled after done generator"
        );
    } else {
        panic!("expected Promise internal data");
    }
}

