// -------------------------------------------------------------------------
// test_async_continuation_on_fulfilled_promise
// -------------------------------------------------------------------------

#[test]
fn test_async_continuation_on_fulfilled_promise() {
    crate::exceptions::clear_exception();
    use std::cell::RefCell;
    use std::rc::Rc;

    // Create and resolve a promise
    let mut prom = crate::promise::JsPromise::new();
    prom.resolve(JsValue::int(42).raw_bits());

    // Register continuation on already-fulfilled promise
    let called = Rc::new(RefCell::new(false));
    let value = Rc::new(RefCell::new(0u64));
    let was_fulfilled = Rc::new(RefCell::new(false));

    let called_c = called.clone();
    let value_c = value.clone();
    let was_fulfilled_c = was_fulfilled.clone();

    prom.register_async_continuation(Box::new(move |val, fulfilled| {
        *called_c.borrow_mut() = true;
        *value_c.borrow_mut() = val;
        *was_fulfilled_c.borrow_mut() = fulfilled;
    }));

    // Should be enqueued as microtask, not called synchronously
    assert!(
        !*called.borrow(),
        "callback should not be called synchronously"
    );

    // Drain microtasks
    crate::promise::drain_microtasks();

    assert!(*called.borrow(), "callback should be called after drain");
    assert_eq!(JsValue::from_raw_bits(*value.borrow()).as_int(), Some(42));
    assert!(*was_fulfilled.borrow(), "should report fulfilled");
}

