// test_promise_microtask_closure
// -------------------------------------------------------------------------

#[test]
fn test_promise_microtask_closure() {
    crate::exceptions::clear_exception();
    use std::cell::RefCell;
    use std::rc::Rc;

    let called = Rc::new(RefCell::new(false));
    let called_c = called.clone();

    crate::promise::queue_microtask_closure(Box::new(move || {
        *called_c.borrow_mut() = true;
    }));

    assert!(!*called.borrow(), "should not run before drain");
    crate::promise::drain_microtasks();
    assert!(*called.borrow(), "should run after drain");
}

