// -------------------------------------------------------------------------
// test_async_continuation_double_resolve_ignored
// -------------------------------------------------------------------------

#[test]
fn test_async_continuation_double_resolve_ignored() {
    crate::exceptions::clear_exception();
    use std::cell::RefCell;
    use std::rc::Rc;

    let mut prom = crate::promise::JsPromise::new();

    let call_count = Rc::new(RefCell::new(0u32));
    let call_count_c = call_count.clone();

    prom.register_async_continuation(Box::new(move |_val, _fulfilled| {
        *call_count_c.borrow_mut() += 1;
    }));

    // Resolve and drain
    prom.resolve(JsValue::int(1).raw_bits());
    crate::promise::drain_microtasks();
    assert_eq!(*call_count.borrow(), 1);

    // Second resolve should be ignored (promise already settled)
    prom.resolve(JsValue::int(2).raw_bits());
    crate::promise::drain_microtasks();
    // Still 1 call
    assert_eq!(*call_count.borrow(), 1);
}

