// ES2025 Iterator Helpers tests
// =========================================================================

// -------------------------------------------------------------------------
// test_iterator_helper_take_limits_values
// -------------------------------------------------------------------------

#[test]
fn test_iterator_helper_take_limits_values() {
    // Create an array [10, 20, 30, 40, 50]
    let arr = crate::rt_api::__esc_rt_create_empty_array(0);
    for i in [10, 20, 30, 40, 50] {
        crate::rt_api::__esc_rt_array_push(arr, JsValue::int(i).raw_bits());
    }
    let iter = crate::rt_api::__esc_rt_iter_init(arr);

    // take(3) should yield only 3 values
    let take_iter = crate::iterator_helpers::iterator_take(iter, 3);

    let r1 = crate::rt_api::__esc_rt_iter_next(take_iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r1)).as_bool(),
        Some(false)
    );
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_value(r1)).as_int(),
        Some(10)
    );

    let r2 = crate::rt_api::__esc_rt_iter_next(take_iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r2)).as_bool(),
        Some(false)
    );
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_value(r2)).as_int(),
        Some(20)
    );

    let r3 = crate::rt_api::__esc_rt_iter_next(take_iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r3)).as_bool(),
        Some(false)
    );
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_value(r3)).as_int(),
        Some(30)
    );

    // Fourth call should be done
    let r4 = crate::rt_api::__esc_rt_iter_next(take_iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r4)).as_bool(),
        Some(true),
        "take(3) should be done after 3 values"
    );
}

