// -------------------------------------------------------------------------
// test_iterator_from_array
// -------------------------------------------------------------------------

#[test]
fn test_iterator_from_array() {
    let arr = crate::rt_api::__esc_rt_create_empty_array(0);
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(42).raw_bits());

    let iter = crate::iterator_helpers::iterator_from(arr);

    // Should be a proper iterator
    let tag = crate::tagged_obj::read_obj_tag(iter);
    assert_eq!(tag, Some(crate::tagged_obj::ObjTag::Unified as u8));

    // Should iterate the array
    let r1 = crate::rt_api::__esc_rt_iter_next(iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r1)).as_bool(),
        Some(false)
    );
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_value(r1)).as_int(),
        Some(42)
    );

    let r2 = crate::rt_api::__esc_rt_iter_next(iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r2)).as_bool(),
        Some(true)
    );
}

