// -------------------------------------------------------------------------
// test_iterator_helper_map_next_pulls_from_underlying
// -------------------------------------------------------------------------

#[test]
fn test_iterator_helper_map_next_pulls_from_underlying() {
    // map with dummy NativeFunc callback: the callback returns undefined,
    // but the iterator should still advance and return results
    let arr = crate::rt_api::__esc_rt_create_empty_array(0);
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(10).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(20).raw_bits());
    let iter = crate::rt_api::__esc_rt_iter_init(arr);
    let dummy_cb = crate::tagged_obj::TaggedObj::boxed(
        crate::tagged_obj::ObjTag::Unified,
        crate::internal_data::UnifiedObject::native_func(|_ctx| JsValue::undefined().raw_bits(), 0),
    );
    let map_iter = crate::iterator_helpers::iterator_map(iter, dummy_cb);

    // First next: callback returns undefined (stub), but iterator advances
    let r1 = crate::rt_api::__esc_rt_iter_next(map_iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r1)).as_bool(),
        Some(false)
    );
    // Value is the callback's return value (undefined in test)

    // Second next
    let r2 = crate::rt_api::__esc_rt_iter_next(map_iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r2)).as_bool(),
        Some(false)
    );

    // Third next: done
    let r3 = crate::rt_api::__esc_rt_iter_next(map_iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r3)).as_bool(),
        Some(true),
        "map iterator should be done after underlying is exhausted"
    );
}

