// -------------------------------------------------------------------------
// test_iterator_helper_dispatch_via_call_method
// -------------------------------------------------------------------------

#[test]
fn test_iterator_helper_dispatch_via_call_method() {
    // Verify that calling .take() on an iterator via __esc_rt_call_method works
    let arr = crate::rt_api::__esc_rt_create_empty_array(0);
    for i in 1..=5 {
        crate::rt_api::__esc_rt_array_push(arr, JsValue::int(i).raw_bits());
    }
    let iter = crate::rt_api::__esc_rt_iter_init(arr);

    // Call .take(2) via method dispatch
    let method_key = crate::rt_api::make_rt_string("take".to_string());
    let argv = [JsValue::int(2).raw_bits()];
    let take_iter =
        unsafe { crate::rt_api::__esc_rt_call_method(iter, method_key, 1, argv.as_ptr()) };

    // Should return an iterator
    let tag = crate::tagged_obj::read_obj_tag(take_iter);
    assert_eq!(tag, Some(crate::tagged_obj::ObjTag::Unified as u8));

    // Verify take(2) gives 2 values
    let r1 = crate::rt_api::__esc_rt_iter_next(take_iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r1)).as_bool(),
        Some(false)
    );
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_value(r1)).as_int(),
        Some(1)
    );

    let r2 = crate::rt_api::__esc_rt_iter_next(take_iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r2)).as_bool(),
        Some(false)
    );
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_value(r2)).as_int(),
        Some(2)
    );

    let r3 = crate::rt_api::__esc_rt_iter_next(take_iter);
    assert_eq!(
        JsValue::from_raw_bits(crate::rt_api::__esc_rt_iter_done(r3)).as_bool(),
        Some(true)
    );
}

