// -------------------------------------------------------------------------
// test_async_generator_next_completes_done_generator
// -------------------------------------------------------------------------

#[test]
fn test_async_generator_next_completes_done_generator() {
    crate::exceptions::clear_exception();
    use crate::async_generator::AsyncGeneratorState;
    use crate::promise::PromiseState;

    // The test stub __esc_dispatch returns undefined, which extract_iter_result
    // treats as {value: undefined, done: true}. So the async generator
    // immediately completes on the first .next().
    let state = crate::rt_api::__esc_rt_create_object();
    let si_key = crate::rt_api::make_rt_string("state_index".to_string());
    crate::rt_api::__esc_rt_set_prop(
        state,
        si_key,
        JsValue::int(crate::generator::STATE_NOT_STARTED).raw_bits(),
    );
    let sync_gen = crate::rt_api::__esc_rt_create_generator(state, 0);
    let ag = crate::rt_api::__esc_rt_create_async_generator(sync_gen);

    let promise = crate::rt_api::__esc_rt_async_generator_next(ag, JsValue::undefined().raw_bits());

    // Drain microtasks
    crate::promise::drain_microtasks();

    // State should be Completed
    let ag_state = crate::async_generator::get_async_generator_state(ag);
    assert_eq!(ag_state, Some(AsyncGeneratorState::Completed));

    // Promise should be fulfilled
    let uni =
        unsafe { crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(promise) };
    let u = uni.unwrap();
    if let Some(crate::internal_data::InternalData::Promise { inner }) = u.internal_data() {
        assert_eq!(
            inner.state,
            PromiseState::Fulfilled,
            "promise should be fulfilled after generator completes"
        );
    } else {
        panic!("expected Promise internal data");
    }
}

