#[test]
fn test_async_generator_unified_object_constructor() {
    use crate::async_generator::AsyncGeneratorState;
    use shapes::ShapeId;

    let sync_gen_bits = 0xDEAD_BEEF_u64;
    let obj = UnifiedObject::async_generator(ShapeId(0), sync_gen_bits);

    assert_eq!(obj.kind, crate::internal_data::InternalKind::AsyncGenerator);
    assert!(!obj.is_callable());

    if let Some(crate::internal_data::InternalData::AsyncGenerator {
        state,
        queue,
        generator,
    }) = obj.internal_data()
    {
        assert_eq!(*state, AsyncGeneratorState::SuspendedStart);
        assert!(queue.is_empty());
        assert_eq!(*generator, sync_gen_bits);
    } else {
        panic!("expected AsyncGenerator internal data");
    }
}

// -------------------------------------------------------------------------
// test_async_generator_queued_requests_drain_on_complete
// -------------------------------------------------------------------------

#[test]
fn test_async_generator_queued_requests_drain_on_complete() {
    crate::exceptions::clear_exception();
    use crate::async_generator::AsyncGeneratorState;
    use crate::promise::PromiseState;

    let state = crate::rt_api::__esc_rt_create_object();
    let si_key = crate::rt_api::make_rt_string("state_index".to_string());
    crate::rt_api::__esc_rt_set_prop(
        state,
        si_key,
        JsValue::int(crate::generator::STATE_NOT_STARTED).raw_bits(),
    );
    let sync_gen = crate::rt_api::__esc_rt_create_generator(state, 0);
    let ag = crate::rt_api::__esc_rt_create_async_generator(sync_gen);

    // Queue up 5 requests at once (first completes, rest should be drained as done)
    let promises: Vec<u64> = (0..5)
        .map(|_| crate::rt_api::__esc_rt_async_generator_next(ag, JsValue::undefined().raw_bits()))
        .collect();

    crate::promise::drain_microtasks();

    // After draining, all promises should be fulfilled
    for (i, &prom) in promises.iter().enumerate() {
        let uni =
            unsafe { crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(prom) };
        let u = uni.unwrap();
        if let Some(crate::internal_data::InternalData::Promise { inner }) = u.internal_data() {
            assert_eq!(
                inner.state,
                PromiseState::Fulfilled,
                "promise {i} of 5 queued should be fulfilled"
            );
        } else {
            panic!("expected Promise internal data for promise {i}");
        }
    }

    // Generator should be completed
    assert_eq!(
        crate::async_generator::get_async_generator_state(ag),
        Some(AsyncGeneratorState::Completed),
    );

    // Queue should be empty
    let uni = unsafe { crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(ag) };
    let u = uni.unwrap();
    if let Some(crate::internal_data::InternalData::AsyncGenerator { queue, .. }) =
        u.internal_data()
    {
        assert!(queue.is_empty(), "queue should be empty after drain");
    } else {
        panic!("expected AsyncGenerator internal data");
    }
}

