// =========================================================================
// Async Iterator Helpers Tests
// =========================================================================

/// Create a sync array iterator over `[10, 20, 30]` for use as an async
/// iterator source (the async wrapper will wrap sync results in Promises).
fn make_sync_array_iter(values: &[i32]) -> u64 {
    let arr = crate::rt_api::create_empty_array();
    for (i, &v) in values.iter().enumerate() {
        let idx = JsValue::int(i as i32).raw_bits();
        crate::rt_api::__esc_rt_set_prop(arr, idx, JsValue::int(v).raw_bits());
    }
    // Set length
    let len_key = crate::rt_api::make_rt_string("length".to_string());
    crate::rt_api::__esc_rt_set_prop(arr, len_key, JsValue::int(values.len() as i32).raw_bits());
    crate::rt_api::__esc_rt_iter_init(arr)
}

/// Helper to check that a NaN-boxed value is a Promise object.
fn is_promise(bits: u64) -> bool {
    let tag = crate::tagged_obj::read_obj_tag(bits);
    if tag != Some(crate::tagged_obj::ObjTag::Unified as u8) {
        return false;
    }
    let uni =
        unsafe { crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(bits) };
    uni.is_some_and(|u| u.kind == crate::internal_data::InternalKind::Promise)
}

/// Helper to check that a NaN-boxed value is an AsyncIterator object.
fn is_async_iterator(bits: u64) -> bool {
    let tag = crate::tagged_obj::read_obj_tag(bits);
    if tag != Some(crate::tagged_obj::ObjTag::Unified as u8) {
        return false;
    }
    let uni =
        unsafe { crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(bits) };
    uni.is_some_and(|u| u.kind == crate::internal_data::InternalKind::AsyncIterator)
}

/// Helper to get the resolved value from a fulfilled Promise.
fn get_promise_value(bits: u64) -> Option<u64> {
    let tag = crate::tagged_obj::read_obj_tag(bits);
    if tag != Some(crate::tagged_obj::ObjTag::Unified as u8) {
        return None;
    }
    let uni =
        unsafe { crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(bits) };
    let u = uni?;
    if let Some(crate::internal_data::InternalData::Promise { inner }) = u.internal_data()
        && inner.state == crate::promise::PromiseState::Fulfilled
    {
        return Some(inner.value);
    }
    None
}

