// -------------------------------------------------------------------------
// test_async_iterator_take_yields_values
// -------------------------------------------------------------------------

#[test]
fn test_async_iterator_take_yields_values() {
    crate::exceptions::clear_exception();
    let source = make_sync_array_iter(&[10, 20, 30]);
    let wrapper = crate::async_iterator_helpers::async_iterator_take(source, 2);

    // First .next() — should yield 10
    let p1 = crate::async_iterator_helpers::async_iterator_next(wrapper);
    crate::promise::drain_microtasks();

    let val1 = get_promise_value(p1);
    assert!(val1.is_some(), "first next() Promise should be fulfilled");
    let (v1, d1) = crate::async_wrap::extract_iter_result(val1.unwrap());
    assert!(!d1, "first result should not be done");
    assert_eq!(
        JsValue::from_raw_bits(v1).as_int(),
        Some(10),
        "first value should be 10"
    );

    // Second .next() — should yield 20
    let p2 = crate::async_iterator_helpers::async_iterator_next(wrapper);
    crate::promise::drain_microtasks();

    let val2 = get_promise_value(p2);
    assert!(val2.is_some(), "second next() Promise should be fulfilled");
    let (v2, d2) = crate::async_wrap::extract_iter_result(val2.unwrap());
    assert!(!d2, "second result should not be done");
    assert_eq!(
        JsValue::from_raw_bits(v2).as_int(),
        Some(20),
        "second value should be 20"
    );

    // Third .next() — should be done (take limited to 2)
    let p3 = crate::async_iterator_helpers::async_iterator_next(wrapper);
    crate::promise::drain_microtasks();

    let val3 = get_promise_value(p3);
    assert!(val3.is_some(), "third next() Promise should be fulfilled");
    let (_v3, d3) = crate::async_wrap::extract_iter_result(val3.unwrap());
    assert!(d3, "third result should be done (take limit reached)");
}

// -------------------------------------------------------------------------
// test_async_iterator_drop_skips_values
// -------------------------------------------------------------------------

#[test]
fn test_async_iterator_drop_skips_values() {
    crate::exceptions::clear_exception();
    let source = make_sync_array_iter(&[10, 20, 30, 40]);
    let wrapper = crate::async_iterator_helpers::async_iterator_drop(source, 2);

    // First .next() — should yield 30 (skipped 10, 20)
    let p1 = crate::async_iterator_helpers::async_iterator_next(wrapper);
    crate::promise::drain_microtasks();

    let val1 = get_promise_value(p1);
    assert!(val1.is_some(), "first next() Promise should be fulfilled");
    let (v1, d1) = crate::async_wrap::extract_iter_result(val1.unwrap());
    assert!(!d1, "first result should not be done");
    assert_eq!(
        JsValue::from_raw_bits(v1).as_int(),
        Some(30),
        "first value should be 30 (after dropping 10, 20)"
    );

    // Second .next() — should yield 40
    let p2 = crate::async_iterator_helpers::async_iterator_next(wrapper);
    crate::promise::drain_microtasks();

    let val2 = get_promise_value(p2);
    assert!(val2.is_some(), "second next() Promise should be fulfilled");
    let (v2, d2) = crate::async_wrap::extract_iter_result(val2.unwrap());
    assert!(!d2, "second result should not be done");
    assert_eq!(
        JsValue::from_raw_bits(v2).as_int(),
        Some(40),
        "second value should be 40"
    );

    // Third .next() — should be done
    let p3 = crate::async_iterator_helpers::async_iterator_next(wrapper);
    crate::promise::drain_microtasks();

    let val3 = get_promise_value(p3);
    assert!(val3.is_some(), "third next() Promise should be fulfilled");
    let (_v3, d3) = crate::async_wrap::extract_iter_result(val3.unwrap());
    assert!(d3, "third result should be done");
}

