// -------------------------------------------------------------------------
// test_async_iterator_some_short_circuits_true
// -------------------------------------------------------------------------

#[test]
fn test_async_iterator_some_returns_promise() {
    crate::exceptions::clear_exception();
    let source = make_sync_array_iter(&[1, 2, 3]);
    let promise =
        crate::async_iterator_helpers::async_iterator_some(source, JsValue::undefined().raw_bits());
    assert!(is_promise(promise), "some() should return a Promise");
    // The test stub returns undefined (falsy) for callbacks, so some() should
    // resolve with false after exhausting the iterator.
    crate::promise::drain_microtasks();
    let val = get_promise_value(promise);
    assert!(
        val.is_some(),
        "some() Promise should be fulfilled after drain"
    );
    assert_eq!(
        JsValue::from_raw_bits(val.unwrap()).as_bool(),
        Some(false),
        "some() should resolve with false when callback always returns falsy"
    );
}

