// -------------------------------------------------------------------------
// test_async_iterator_reduce_no_initial_empty
// -------------------------------------------------------------------------

#[test]
fn test_async_iterator_reduce_no_initial_empty() {
    crate::exceptions::clear_exception();
    let source = make_sync_array_iter(&[]);
    let promise = crate::async_iterator_helpers::async_iterator_reduce(
        source,
        JsValue::undefined().raw_bits(),
        JsValue::undefined().raw_bits(),
        false,
    );
    assert!(is_promise(promise), "reduce should return a Promise");
    crate::promise::drain_microtasks();
    // With empty iterator and no initial value, should reject with TypeError.
    // In our test environment, the promise may be rejected.
    let tag = crate::tagged_obj::read_obj_tag(promise);
    assert_eq!(tag, Some(crate::tagged_obj::ObjTag::Unified as u8));
    let uni =
        unsafe { crate::tagged_obj::deref_tagged::<crate::internal_data::UnifiedObject>(promise) };
    let u = uni.unwrap();
    if let Some(crate::internal_data::InternalData::Promise { inner }) = u.internal_data() {
        assert_eq!(
            inner.state,
            crate::promise::PromiseState::Rejected,
            "reduce on empty with no initial should reject"
        );
    }
}

// =========================================================================
// Type coercion hardening tests (v0.5 Wave 7)
// =========================================================================

// -------------------------------------------------------------------------
// abstract_eq: boolean coercion before object ToPrimitive (spec steps 6-7)
// -------------------------------------------------------------------------

#[test]
fn test_abstract_eq_bool_vs_string() {
    // true == "1" → ToNumber(true) = 1, then 1 == "1" → ToNumber("1") = 1, 1 == 1 → true
    let t = JsValue::bool(true);
    let s = JsValue::from_raw_bits(make_string_value("1"));
    assert!(crate::value_ops::abstract_eq(t, s));

    // false == "0" → ToNumber(false) = 0, then 0 == "0" → ToNumber("0") = 0, 0 == 0 → true
    let f = JsValue::bool(false);
    let s0 = JsValue::from_raw_bits(make_string_value("0"));
    assert!(crate::value_ops::abstract_eq(f, s0));

    // false == "" → ToNumber(false) = 0, then 0 == "" → ToNumber("") = 0, 0 == 0 → true
    let empty = JsValue::from_raw_bits(make_string_value(""));
    assert!(crate::value_ops::abstract_eq(f, empty));

    // true == "2" → ToNumber(true) = 1, then 1 == "2" → ToNumber("2") = 2, 1 != 2 → false
    let s2 = JsValue::from_raw_bits(make_string_value("2"));
    assert!(!crate::value_ops::abstract_eq(t, s2));
}

#[test]
fn test_abstract_eq_bool_vs_number() {
    // true == 1 → ToNumber(true) = 1, 1 == 1 → true
    assert!(crate::value_ops::abstract_eq(
        JsValue::bool(true),
        JsValue::int(1)
    ));
    // false == 0 → ToNumber(false) = 0, 0 == 0 → true
    assert!(crate::value_ops::abstract_eq(
        JsValue::bool(false),
        JsValue::int(0)
    ));
    // true == 0 → false
    assert!(!crate::value_ops::abstract_eq(
        JsValue::bool(true),
        JsValue::int(0)
    ));
    // false == 1 → false
    assert!(!crate::value_ops::abstract_eq(
        JsValue::bool(false),
        JsValue::int(1)
    ));
}

// -------------------------------------------------------------------------
// abstract_eq: number vs string cross-type
// -------------------------------------------------------------------------

#[test]
fn test_abstract_eq_number_vs_string() {
    // 0 == "" → true
    let empty = JsValue::from_raw_bits(make_string_value(""));
    assert!(crate::value_ops::abstract_eq(JsValue::int(0), empty));

    // 42 == "42" → true
    let s42 = JsValue::from_raw_bits(make_string_value("42"));
    assert!(crate::value_ops::abstract_eq(JsValue::int(42), s42));

    // 2.5 == "2.5" → true
    let spi = JsValue::from_raw_bits(make_string_value("2.5"));
    assert!(crate::value_ops::abstract_eq(JsValue::number(2.5), spi));

    // 0 == "  " → true (whitespace-only string is 0)
    let ws = JsValue::from_raw_bits(make_string_value("  "));
    assert!(crate::value_ops::abstract_eq(JsValue::int(0), ws));

    // 255 == "0xFF" → true
    let hex = JsValue::from_raw_bits(make_string_value("0xFF"));
    assert!(crate::value_ops::abstract_eq(JsValue::int(255), hex));

    // NaN != "NaN" — NaN != anything
    let snan = JsValue::from_raw_bits(make_string_value("NaN"));
    assert!(!crate::value_ops::abstract_eq(
        JsValue::number(f64::NAN),
        snan
    ));
}

// -------------------------------------------------------------------------
// abstract_eq: null/undefined edge cases
// -------------------------------------------------------------------------

#[test]
fn test_abstract_eq_null_not_equal_to_zero() {
    // null != 0 (null only equals undefined)
    assert!(!crate::value_ops::abstract_eq(
        JsValue::null(),
        JsValue::int(0)
    ));
    // null != "" (null only equals undefined)
    let empty = JsValue::from_raw_bits(make_string_value(""));
    assert!(!crate::value_ops::abstract_eq(JsValue::null(), empty));
    // null != false
    assert!(!crate::value_ops::abstract_eq(
        JsValue::null(),
        JsValue::bool(false)
    ));
}

#[test]
fn test_abstract_eq_undefined_not_equal_to_zero() {
    // undefined != 0
    assert!(!crate::value_ops::abstract_eq(
        JsValue::undefined(),
        JsValue::int(0)
    ));
    // undefined != ""
    let empty = JsValue::from_raw_bits(make_string_value(""));
    assert!(!crate::value_ops::abstract_eq(JsValue::undefined(), empty));
    // undefined != false
    assert!(!crate::value_ops::abstract_eq(
        JsValue::undefined(),
        JsValue::bool(false)
    ));
}

// -------------------------------------------------------------------------
// abstract_eq: symbol cases
// -------------------------------------------------------------------------

#[test]
fn test_abstract_eq_symbol_not_equal_to_string() {
    // Symbol() != "symbol" — symbols are only equal to themselves
    let sym = JsValue::symbol(99);
    let s = JsValue::from_raw_bits(make_string_value("symbol"));
    assert!(!crate::value_ops::abstract_eq(sym, s));

    // Symbol() != 0
    assert!(!crate::value_ops::abstract_eq(sym, JsValue::int(0)));

    // Symbol() != null
    assert!(!crate::value_ops::abstract_eq(sym, JsValue::null()));

    // Symbol(1) == Symbol(1) (same ID → same type → strict eq)
    let sym2 = JsValue::symbol(99);
    assert!(crate::value_ops::abstract_eq(sym, sym2));

    // Symbol(1) != Symbol(2) (different IDs)
    let sym3 = JsValue::symbol(100);
    assert!(!crate::value_ops::abstract_eq(sym, sym3));
}

// -------------------------------------------------------------------------
// ToNumber: string edge cases
// -------------------------------------------------------------------------

#[test]
fn test_to_number_whitespace_strings() {
    // "  " → 0 (whitespace-only)
    let ws = JsValue::from_raw_bits(make_string_value("  "));
    assert_eq!(crate::value_ops::to_number(ws), 0.0);

    // "\t\n" → 0 (tabs and newlines)
    let tn = JsValue::from_raw_bits(make_string_value("\t\n"));
    assert_eq!(crate::value_ops::to_number(tn), 0.0);

    // "  42  " → 42 (leading/trailing whitespace)
    let padded = JsValue::from_raw_bits(make_string_value("  42  "));
    assert_eq!(crate::value_ops::to_number(padded), 42.0);
}

#[test]
fn test_to_number_signed_prefix_hex_is_nan() {
    // "+0xFF" → NaN (sign not allowed for hex prefix)
    let phex = JsValue::from_raw_bits(make_string_value("+0xFF"));
    assert!(crate::value_ops::to_number(phex).is_nan());

    // "-0xFF" → NaN
    let nhex = JsValue::from_raw_bits(make_string_value("-0xFF"));
    assert!(crate::value_ops::to_number(nhex).is_nan());
}

#[test]
fn test_to_number_special_decimal_strings() {
    // "+1" → 1
    let p1 = JsValue::from_raw_bits(make_string_value("+1"));
    assert_eq!(crate::value_ops::to_number(p1), 1.0);

    // "-1" → -1
    let n1 = JsValue::from_raw_bits(make_string_value("-1"));
    assert_eq!(crate::value_ops::to_number(n1), -1.0);

    // "+Infinity" → Infinity
    let pinf = JsValue::from_raw_bits(make_string_value("+Infinity"));
    assert_eq!(crate::value_ops::to_number(pinf), f64::INFINITY);

    // "  -Infinity  " → -Infinity
    let ninf = JsValue::from_raw_bits(make_string_value("  -Infinity  "));
    assert_eq!(crate::value_ops::to_number(ninf), f64::NEG_INFINITY);
}

// -------------------------------------------------------------------------
