// -------------------------------------------------------------------------

#[test]
fn test_display_number_small_values_threshold() {
    // 1e-6 → "0.000001" (NOT scientific notation)
    assert_eq!(crate::display::display_number(1e-6), "0.000001");

    // 1e-7 → "1e-7" (scientific notation)
    assert_eq!(crate::display::display_number(1e-7), "1e-7");

    // 5e-7 → "5e-7" (scientific notation)
    assert_eq!(crate::display::display_number(5e-7), "5e-7");

    // 9.9e-7 → "9.9e-7" (scientific notation, exponent is -7)
    assert_eq!(crate::display::display_number(9.9e-7), "9.9e-7");
}

#[test]
fn test_display_number_large_integer_values() {
    // 1e20 → "100000000000000000000" (20 zeros, no scientific)
    assert_eq!(
        crate::display::display_number(1e20),
        "100000000000000000000"
    );

    // 1e21 → "1e+21" (scientific notation)
    assert_eq!(crate::display::display_number(1e21), "1e+21");
}

#[test]
fn test_display_number_negative_zero() {
    // -0 → "0" per spec
    assert_eq!(crate::display::display_number(-0.0), "0");
}

#[test]
fn test_display_number_negative_integers() {
    assert_eq!(crate::display::display_number(-42.0), "-42");
    assert_eq!(crate::display::display_number(-1.0), "-1");
}

// -------------------------------------------------------------------------
// js_add: type coercion in addition
// -------------------------------------------------------------------------

#[test]
fn test_js_add_number_plus_string() {
    // 1 + "2" → "12" (string concatenation)
    let one = JsValue::int(1);
    let two = JsValue::from_raw_bits(make_string_value("2"));
    let result = crate::value_ops::js_add(one, two);
    assert!(result.is_string());
    assert_eq!(crate::string_ops::get_string_data(result), "12");
}

#[test]
fn test_js_add_null_plus_number() {
    // null + 1 → 1 (ToNumber(null) = 0, 0 + 1 = 1)
    let result = crate::value_ops::js_add(JsValue::null(), JsValue::int(1));
    // result should be number(1)
    let n = crate::value_ops::to_number(result);
    assert_eq!(n, 1.0);
}

#[test]
fn test_js_add_undefined_plus_number() {
    // undefined + 1 → NaN (ToNumber(undefined) = NaN)
    let result = crate::value_ops::js_add(JsValue::undefined(), JsValue::int(1));
    let n = crate::value_ops::to_number(result);
    assert!(n.is_nan());
}

#[test]
fn test_js_add_bool_plus_number() {
    // true + 1 → 2
    let result = crate::value_ops::js_add(JsValue::bool(true), JsValue::int(1));
    let n = crate::value_ops::to_number(result);
    assert_eq!(n, 2.0);

    // false + 1 → 1
    let result2 = crate::value_ops::js_add(JsValue::bool(false), JsValue::int(1));
    let n2 = crate::value_ops::to_number(result2);
    assert_eq!(n2, 1.0);
}

#[test]
fn test_js_add_string_concat_with_bool() {
    // "a" + true → "atrue"
    let a = JsValue::from_raw_bits(make_string_value("a"));
    let result = crate::value_ops::js_add(a, JsValue::bool(true));
    assert!(result.is_string());
    assert_eq!(crate::string_ops::get_string_data(result), "atrue");

    // "a" + null → "anull"
    let a2 = JsValue::from_raw_bits(make_string_value("a"));
    let result2 = crate::value_ops::js_add(a2, JsValue::null());
    assert!(result2.is_string());
    assert_eq!(crate::string_ops::get_string_data(result2), "anull");
}

