// -------------------------------------------------------------------------
// Relational comparison coercion
// -------------------------------------------------------------------------

#[test]
fn test_relational_string_vs_number() {
    // "5" > 3 → true (ToNumber("5") = 5, 5 > 3)
    let s5 = JsValue::from_raw_bits(make_string_value("5"));
    assert!(crate::value_ops::js_gt(s5, JsValue::int(3)));

    // "2" < 3 → true
    let s2 = JsValue::from_raw_bits(make_string_value("2"));
    assert!(crate::value_ops::js_lt(s2, JsValue::int(3)));
}

#[test]
fn test_relational_bool_coercion() {
    // true > 0 → true (ToNumber(true) = 1, 1 > 0)
    assert!(crate::value_ops::js_gt(
        JsValue::bool(true),
        JsValue::int(0)
    ));

    // false >= 0 → true (ToNumber(false) = 0, 0 >= 0)
    assert!(crate::value_ops::js_ge(
        JsValue::bool(false),
        JsValue::int(0)
    ));
}

#[test]
fn test_relational_null_coercion() {
    // null >= 0 → true (ToNumber(null) = 0, 0 >= 0)
    assert!(crate::value_ops::js_ge(JsValue::null(), JsValue::int(0)));

    // null > 0 → false (0 > 0 is false)
    assert!(!crate::value_ops::js_gt(JsValue::null(), JsValue::int(0)));

    // null < 1 → true (0 < 1)
    assert!(crate::value_ops::js_lt(JsValue::null(), JsValue::int(1)));
}

#[test]
fn test_relational_undefined_nan() {
    // undefined < 0 → false (NaN comparisons are always false)
    assert!(!crate::value_ops::js_lt(
        JsValue::undefined(),
        JsValue::int(0)
    ));
    assert!(!crate::value_ops::js_gt(
        JsValue::undefined(),
        JsValue::int(0)
    ));
    assert!(!crate::value_ops::js_le(
        JsValue::undefined(),
        JsValue::int(0)
    ));
    assert!(!crate::value_ops::js_ge(
        JsValue::undefined(),
        JsValue::int(0)
    ));
}

