#[test]
fn test_object_has_own_undefined_value_property() {
    // Bug fix: Object.hasOwn should return true for properties with undefined value.
    // Previously used __esc_rt_get_prop which returned undefined and treated it as "not found".
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    let atom = interner.intern("x");
    let new_shape = shapes.add_property(obj.shape_id, atom);
    obj.shape_id = new_shape;
    obj.slots.push(JsValue::undefined()); // property exists but value is undefined

    assert!(
        obj.has_own_property("x", &shapes, &interner),
        "has_own_property should return true even when value is undefined"
    );
}

#[test]
fn test_define_property_non_configurable_rejects_make_configurable() {
    // Object.defineProperty on a non-configurable property should throw TypeError
    // when trying to make it configurable again
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Add a non-configurable property
    let opts = property::DefinePropertyOptions {
        value: Some(JsValue::number(42.0)),
        writable: Some(false),
        enumerable: Some(false),
        configurable: Some(false),
        ..Default::default()
    };
    let result = obj.define_own_property("x", &opts, &mut shapes, &interner);
    assert!(result.is_ok());

    // Try to make it configurable — should fail
    let opts2 = property::DefinePropertyOptions {
        configurable: Some(true),
        ..Default::default()
    };
    let result2 = obj.define_own_property("x", &opts2, &mut shapes, &interner);
    assert_eq!(result2, Err(PropertyError::NotConfigurable));
}

