#[test]
fn test_freeze_sets_all_properties_non_writable_non_configurable() {
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Add two data properties
    let opts_a = property::DefinePropertyOptions {
        value: Some(JsValue::number(1.0)),
        writable: Some(true),
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("a", &opts_a, &mut shapes, &interner)
        .unwrap();

    let opts_b = property::DefinePropertyOptions {
        value: Some(JsValue::number(2.0)),
        writable: Some(true),
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("b", &opts_b, &mut shapes, &interner)
        .unwrap();

    // Freeze the object
    obj.freeze();
    if let Some(new_shape) = shapes.freeze_all_properties(obj.shape_id) {
        obj.shape_id = new_shape;
    }

    // Both properties should now be non-writable and non-configurable
    let desc_a = obj
        .get_property_descriptor("a", &shapes, &interner)
        .unwrap();
    assert!(
        !desc_a.is_configurable(),
        "frozen property should be non-configurable"
    );
    if let property::OwnPropertyDescriptor::Data { writable, .. } = desc_a {
        assert!(!writable, "frozen data property should be non-writable");
    }

    let desc_b = obj
        .get_property_descriptor("b", &shapes, &interner)
        .unwrap();
    assert!(
        !desc_b.is_configurable(),
        "frozen property should be non-configurable"
    );
}

#[test]
fn test_seal_sets_all_properties_non_configurable_preserves_writable() {
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Add a writable property
    let opts = property::DefinePropertyOptions {
        value: Some(JsValue::number(1.0)),
        writable: Some(true),
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("a", &opts, &mut shapes, &interner)
        .unwrap();

    // Seal the object
    obj.seal();
    if let Some(new_shape) = shapes.seal_all_properties(obj.shape_id) {
        obj.shape_id = new_shape;
    }

    // Property should be non-configurable but still writable
    let desc = obj
        .get_property_descriptor("a", &shapes, &interner)
        .unwrap();
    assert!(
        !desc.is_configurable(),
        "sealed property should be non-configurable"
    );
    if let property::OwnPropertyDescriptor::Data { writable, .. } = desc {
        assert!(writable, "sealed data property should preserve writable");
    }
}

#[test]
fn test_property_enumeration_spec_order() {
    // Numeric indices first (ascending), then string keys in insertion order
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Add properties in non-spec order
    let names = ["b", "10", "a", "2", "0"];
    for name in names {
        let atom = interner.intern(name);
        let new_shape = shapes.add_property(obj.shape_id, atom);
        obj.shape_id = new_shape;
        obj.slots.push(JsValue::number(0.0));
    }

    let keys = obj.own_keys(&shapes, &interner);
    // Expected: "0", "2", "10" (numeric ascending), then "b", "a" (insertion order)
    assert_eq!(keys, vec!["0", "2", "10", "b", "a"]);
}

#[test]
fn test_enumerable_keys_excludes_non_enumerable() {
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Add enumerable property
    let opts = property::DefinePropertyOptions {
        value: Some(JsValue::number(1.0)),
        writable: Some(true),
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("visible", &opts, &mut shapes, &interner)
        .unwrap();

    // Add non-enumerable property
    let opts2 = property::DefinePropertyOptions {
        value: Some(JsValue::number(2.0)),
        writable: Some(true),
        enumerable: Some(false),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("hidden", &opts2, &mut shapes, &interner)
        .unwrap();

    let enum_keys = obj.enumerable_keys(&shapes, &interner);
    assert_eq!(enum_keys, vec!["visible"]);

    let all_keys = obj.own_keys(&shapes, &interner);
    assert_eq!(all_keys, vec!["visible", "hidden"]);
}

#[test]
fn test_iterator_result_value_done_fields() {
    // IteratorResult must be a proper {value, done} object
    let result = crate::iterator::IteratorResult::with_value(JsValue::number(42.0).raw_bits());
    assert_eq!(JsValue::from_raw_bits(result.value), JsValue::number(42.0));
    assert_eq!(JsValue::from_raw_bits(result.done), JsValue::bool(false));

    let done_result = crate::iterator::IteratorResult::done();
    assert_eq!(
        JsValue::from_raw_bits(done_result.value),
        JsValue::undefined()
    );
    assert_eq!(
        JsValue::from_raw_bits(done_result.done),
        JsValue::bool(true)
    );
}

#[test]
fn test_iterator_done_uses_to_boolean() {
    // The done field should be checked with ToBoolean, not strict comparison.
    // done=0 should be false, done=1 should be true, done="" should be false.
    use crate::value_ops::to_boolean;

    assert!(!to_boolean(JsValue::bool(false)));
    assert!(to_boolean(JsValue::bool(true)));
    assert!(!to_boolean(JsValue::number(0.0)));
    assert!(to_boolean(JsValue::number(1.0)));
}

#[test]
fn test_function_name_length_compute() {
    // Test compute_function_length: counts params before first default/rest
    // This is tested indirectly through the desugar crate but we verify the
    // runtime behavior: UnifiedObject stores param_count in InternalData.
    let obj = UnifiedObject::function(
        ShapeTable::EMPTY_SHAPE,
        0, // code_idx
        0, // env
        0, // name
        3, // param_count = 3 params before default
        false,
    );
    if let Some(crate::internal_data::InternalData::Function { param_count, .. }) =
        obj.internal_data()
    {
        assert_eq!(*param_count, 3);
    } else {
        panic!("expected Function internal data");
    }
}

