#[test]
fn test_default_data_property_attributes() {
    // Properties created via assignment should be writable, enumerable, configurable
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Simulate assignment: add_property creates with default flags (all true)
    let atom = interner.intern("x");
    let new_shape = shapes.add_property(obj.shape_id, atom);
    obj.shape_id = new_shape;
    obj.slots.push(JsValue::number(1.0));

    let desc = obj
        .get_property_descriptor("x", &shapes, &interner)
        .unwrap();
    match desc {
        property::OwnPropertyDescriptor::Data {
            writable,
            enumerable,
            configurable,
            ..
        } => {
            assert!(writable, "assignment creates writable property");
            assert!(enumerable, "assignment creates enumerable property");
            assert!(configurable, "assignment creates configurable property");
        }
        _ => panic!("expected data descriptor"),
    }
}

#[test]
fn test_define_property_defaults_to_false() {
    // Per spec, Object.defineProperty defaults writable/enumerable/configurable to false
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    let opts = property::DefinePropertyOptions {
        value: Some(JsValue::number(42.0)),
        // writable, enumerable, configurable all None -> defaults to false
        ..Default::default()
    };
    obj.define_own_property("x", &opts, &mut shapes, &interner)
        .unwrap();

    let desc = obj
        .get_property_descriptor("x", &shapes, &interner)
        .unwrap();
    match desc {
        property::OwnPropertyDescriptor::Data {
            writable,
            enumerable,
            configurable,
            ..
        } => {
            assert!(!writable, "defineProperty defaults writable to false");
            assert!(!enumerable, "defineProperty defaults enumerable to false");
            assert!(
                !configurable,
                "defineProperty defaults configurable to false"
            );
        }
        _ => panic!("expected data descriptor"),
    }
}

