#[test]
fn test_error_to_string_method_type_error() {
    let msg = crate::rt_api::make_rt_string("is not a function".to_string());
    let err = crate::rt_api::__esc_rt_create_error(crate::exceptions::error_tag::TYPE_ERROR, msg);
    let method_key = crate::rt_api::make_rt_string("toString".to_string());
    let result = unsafe {
        // SAFETY: err is a valid error object, 0 args, null argv.
        crate::rt_api::__esc_rt_call_method(err, method_key, 0, std::ptr::null())
    };
    let result_str = crate::string_ops::get_string_data(JsValue::from_raw_bits(result));
    assert_eq!(
        result_str, "TypeError: is not a function",
        "error.toString() should return 'TypeName: message'"
    );
}

