#[test]
fn test_array_length_get_own_property_descriptor() {
    use crate::internal_data::UnifiedObject;
    use crate::property::OwnPropertyDescriptor;
    use interner::Interner;

    let elems = vec![JsValue::int(1), JsValue::int(2), JsValue::int(3)];
    let arr = UnifiedObject::array(shapes::ShapeId(0), elems);
    let shapes = shapes::ShapeTable::new();
    let interner = Interner::new();

    let desc = arr.get_property_descriptor("length", &shapes, &interner);
    assert!(desc.is_some(), "array .length descriptor should exist");
    match desc.unwrap() {
        OwnPropertyDescriptor::Data {
            value,
            writable,
            enumerable,
            configurable,
        } => {
            // length should be 3
            assert_eq!(value.as_number(), Some(3.0));
            // writable: true, enumerable: false, configurable: false
            assert!(writable, "array .length should be writable");
            assert!(!enumerable, "array .length should not be enumerable");
            assert!(!configurable, "array .length should not be configurable");
        }
        OwnPropertyDescriptor::Accessor { .. } => {
            panic!("array .length should be a data descriptor, not accessor");
        }
    }
}

