fn test_define_property_non_writable_same_value_succeeds() {
    use crate::internal_data::UnifiedObject;
    use crate::property::DefinePropertyOptions;
    use interner::Interner;

    let mut obj = UnifiedObject::ordinary(shapes::ShapeId(0));
    let mut shapes = shapes::ShapeTable::new();
    let interner = Interner::new();

    // Add property {value: 42, writable: false, configurable: false}
    let opts = DefinePropertyOptions {
        value: Some(JsValue::int(42)),
        writable: Some(false),
        enumerable: Some(true),
        configurable: Some(false),
        getter: None,
        setter: None,
    };
    obj.define_own_property("x", &opts, &mut shapes, &interner)
        .unwrap();

    // Redefining with the SAME value should succeed
    let opts2 = DefinePropertyOptions {
        value: Some(JsValue::int(42)),
        writable: None,
        enumerable: None,
        configurable: None,
        getter: None,
        setter: None,
    };
    let result = obj.define_own_property("x", &opts2, &mut shapes, &interner);
    assert!(
        result.is_ok(),
        "defineProperty with same value on non-writable property should succeed"
    );
}

#[test]
fn test_define_property_non_writable_different_value_rejects() {
    use crate::internal_data::UnifiedObject;
    use crate::property::{DefinePropertyOptions, PropertyError};
    use interner::Interner;

    let mut obj = UnifiedObject::ordinary(shapes::ShapeId(0));
    let mut shapes = shapes::ShapeTable::new();
    let interner = Interner::new();

    // Add property {value: 42, writable: false, configurable: false}
    let opts = DefinePropertyOptions {
        value: Some(JsValue::int(42)),
        writable: Some(false),
        enumerable: Some(true),
        configurable: Some(false),
        getter: None,
        setter: None,
    };
    obj.define_own_property("x", &opts, &mut shapes, &interner)
        .unwrap();

    // Redefining with a DIFFERENT value should reject
    let opts2 = DefinePropertyOptions {
        value: Some(JsValue::int(99)),
        writable: None,
        enumerable: None,
        configurable: None,
        getter: None,
        setter: None,
    };
    let result = obj.define_own_property("x", &opts2, &mut shapes, &interner);
    assert_eq!(
        result,
        Err(PropertyError::NotWritable),
        "defineProperty with different value on non-writable property should fail"
    );
}

