#[test]
fn test_esc_env_get_set_slot() {
    let mut env = crate::esc_environment::EscEnvironment::new(5);
    env.set_slot(0, JsValue::int(42).raw_bits());
    env.set_slot(4, JsValue::bool(true).raw_bits());

    assert_eq!(JsValue::from_raw_bits(env.get_slot(0)).as_int(), Some(42));
    assert_eq!(
        JsValue::from_raw_bits(env.get_slot(4)).as_bool(),
        Some(true)
    );
    // Unset slot returns undefined
    assert!(JsValue::from_raw_bits(env.get_slot(2)).is_undefined());
}

#[test]
fn test_esc_env_get_slot_out_of_range() {
    let env = crate::esc_environment::EscEnvironment::new(2);
    // Out of range returns undefined
    assert!(JsValue::from_raw_bits(env.get_slot(10)).is_undefined());
    assert!(JsValue::from_raw_bits(env.get_slot(u32::MAX)).is_undefined());
}

#[test]
fn test_esc_env_set_slot_out_of_range_is_noop() {
    let mut env = crate::esc_environment::EscEnvironment::new(2);
    env.set_slot(0, JsValue::int(1).raw_bits());
    // Setting out of range should be a no-op
    env.set_slot(10, JsValue::int(99).raw_bits());
    env.set_slot(u32::MAX, JsValue::int(99).raw_bits());
    // Original slots unchanged
    assert_eq!(env.slots.len(), 2);
    assert_eq!(JsValue::from_raw_bits(env.get_slot(0)).as_int(), Some(1));
}

