#[test]
fn test_esc_env_nested_three_levels_lookup() {
    use std::sync::Arc;
    let interner = Interner::new();
    let a = interner.intern("a");
    let b = interner.intern("b");
    let c = interner.intern("c");

    // Level 0 (grandparent): has "a"
    let mut gp = crate::esc_environment::EscEnvironment::new(1);
    gp.slot_map.insert(a, 0);
    gp.set_slot(0, JsValue::int(1).raw_bits());
    let gp = Arc::new(gp);

    // Level 1 (parent): has "b"
    let mut p = crate::esc_environment::EscEnvironment::with_outer(1, Arc::clone(&gp));
    p.slot_map.insert(b, 0);
    p.set_slot(0, JsValue::int(2).raw_bits());
    let p = Arc::new(p);

    // Level 2 (child): has "c"
    let mut child = crate::esc_environment::EscEnvironment::with_outer(1, Arc::clone(&p));
    child.slot_map.insert(c, 0);
    child.set_slot(0, JsValue::int(3).raw_bits());

    // Child can find all three
    assert_eq!(
        JsValue::from_raw_bits(child.lookup(&a).unwrap()).as_int(),
        Some(1)
    );
    assert_eq!(
        JsValue::from_raw_bits(child.lookup(&b).unwrap()).as_int(),
        Some(2)
    );
    assert_eq!(
        JsValue::from_raw_bits(child.lookup(&c).unwrap()).as_int(),
        Some(3)
    );
}

