#[test]
fn test_esc_env_binding_shadows_slot() {
    let interner = Interner::new();
    let x = interner.intern("x");

    let mut env = crate::esc_environment::EscEnvironment::new(1);
    env.slot_map.insert(x, 0);
    env.set_slot(0, JsValue::int(10).raw_bits());

    // slot_map is checked before bindings, so slot wins
    assert_eq!(
        JsValue::from_raw_bits(env.lookup(&x).unwrap()).as_int(),
        Some(10)
    );

    // But if we DON'T have it in slot_map (different name), binding works
    let y = interner.intern("y");
    env.add_binding(y, JsValue::int(20).raw_bits());
    assert_eq!(
        JsValue::from_raw_bits(env.lookup(&y).unwrap()).as_int(),
        Some(20)
    );
}

