#[test]
fn test_esc_env_abi_create_and_get_set() {
    // Test the ABI functions: create, get, set
    let env_bits = crate::rt_api::__esc_rt_esc_env_create(3, 0);
    assert_ne!(env_bits, 0);

    // Initially all undefined
    let val = crate::rt_api::__esc_rt_esc_env_get(env_bits, 0);
    assert!(JsValue::from_raw_bits(val).is_undefined());

    // Set and get back
    crate::rt_api::__esc_rt_esc_env_set(env_bits, 0, JsValue::int(42).raw_bits());
    let val = crate::rt_api::__esc_rt_esc_env_get(env_bits, 0);
    assert_eq!(JsValue::from_raw_bits(val).as_int(), Some(42));

    // Set slot 2
    crate::rt_api::__esc_rt_esc_env_set(env_bits, 2, JsValue::bool(true).raw_bits());
    let val = crate::rt_api::__esc_rt_esc_env_get(env_bits, 2);
    assert_eq!(JsValue::from_raw_bits(val).as_bool(), Some(true));
}

