/// Helper to call Reflect methods via the dispatch API.
fn call_reflect(method: &str, args: &[u64]) -> Option<u64> {
    crate::rt_api::dispatch_reflect_method(method, args.len() as u32, args.as_ptr())
}

#[test]
fn test_reflect_get_plain_object() {
    let obj = crate::rt_api::__esc_rt_create_object();
    let key = crate::rt_api::make_rt_string("x".to_string());
    crate::rt_api::__esc_rt_set_prop(obj, key, JsValue::int(42).raw_bits());

    let key2 = crate::rt_api::make_rt_string("x".to_string());
    let result = call_reflect("get", &[obj, key2]);
    assert!(result.is_some());
    let val = JsValue::from_raw_bits(result.unwrap());
    assert_eq!(val.as_int(), Some(42));
}

#[test]
fn test_reflect_get_missing_key_returns_undefined() {
    let obj = crate::rt_api::__esc_rt_create_object();
    let key = crate::rt_api::make_rt_string("nonexistent".to_string());
    let result = call_reflect("get", &[obj, key]);
    assert!(result.is_some());
    assert!(JsValue::from_raw_bits(result.unwrap()).is_undefined());
}

#[test]
fn test_reflect_set_returns_true_on_success() {
    let obj = crate::rt_api::__esc_rt_create_object();
    let key = crate::rt_api::make_rt_string("y".to_string());
    let result = call_reflect("set", &[obj, key, JsValue::int(99).raw_bits()]);
    assert!(result.is_some());
    let val = JsValue::from_raw_bits(result.unwrap());
    assert_eq!(val.as_bool(), Some(true));

    // Verify value was actually set
    let key2 = crate::rt_api::make_rt_string("y".to_string());
    let get_result = call_reflect("get", &[obj, key2]);
    assert_eq!(
        JsValue::from_raw_bits(get_result.unwrap()).as_int(),
        Some(99)
    );
}

