#[test]
fn test_esc_env_unscopables_name_listed_skips_with_object() {
    // Create a with-object that has {x: 1} and @@unscopables = {x: true}
    let obj_bits = crate::rt_api::__esc_rt_create_object();
    let x_key = crate::rt_api::make_rt_string("x".to_string());
    crate::rt_api::__esc_rt_set_prop(obj_bits, x_key, JsValue::int(1).raw_bits());

    // Set @@unscopables on the object
    let unscopables_obj = crate::rt_api::__esc_rt_create_object();
    let x_key2 = crate::rt_api::make_rt_string("x".to_string());
    crate::rt_api::__esc_rt_set_prop(unscopables_obj, x_key2, JsValue::bool(true).raw_bits());
    crate::rt_api::__esc_rt_set_prop(
        obj_bits,
        JsValue::symbol(crate::symbol::SYMBOL_UNSCOPABLES).raw_bits(),
        unscopables_obj,
    );

    // Create with-environment wrapping this object
    let outer_bits = crate::rt_api::__esc_rt_esc_env_create(0, 0);
    let with_env = crate::rt_api::__esc_rt_with_env_create(obj_bits, outer_bits);

    // Lookup "x" — should NOT find it because x is listed in @@unscopables
    let x_name = crate::rt_api::make_rt_string("x".to_string());
    let result = crate::rt_api::__esc_rt_esc_env_lookup(with_env, x_name);
    assert!(
        JsValue::from_raw_bits(result).is_undefined(),
        "x should be unscopable and NOT found via with-object"
    );
}

