#[test]
fn test_esc_env_unscopables_store_respects_unscopables() {
    // Create a with-object with {x: 1} and @@unscopables = {x: true}
    let obj_bits = crate::rt_api::__esc_rt_create_object();
    let x_key = crate::rt_api::make_rt_string("x".to_string());
    crate::rt_api::__esc_rt_set_prop(obj_bits, x_key, JsValue::int(1).raw_bits());

    let unscopables_obj = crate::rt_api::__esc_rt_create_object();
    let x_key2 = crate::rt_api::make_rt_string("x".to_string());
    crate::rt_api::__esc_rt_set_prop(unscopables_obj, x_key2, JsValue::bool(true).raw_bits());
    crate::rt_api::__esc_rt_set_prop(
        obj_bits,
        JsValue::symbol(crate::symbol::SYMBOL_UNSCOPABLES).raw_bits(),
        unscopables_obj,
    );

    let outer_bits = crate::rt_api::__esc_rt_esc_env_create(0, 0);
    let with_env = crate::rt_api::__esc_rt_with_env_create(obj_bits, outer_bits);

    // Store "x" — should NOT store to with-object (x is unscopable)
    let x_name = crate::rt_api::make_rt_string("x".to_string());
    let result =
        crate::rt_api::__esc_rt_esc_env_store(with_env, x_name, JsValue::int(999).raw_bits());
    assert_eq!(
        JsValue::from_raw_bits(result).as_bool(),
        Some(false),
        "store of unscopable name should return false (not stored to with-object)"
    );

    // Verify the with-object still has the original value
    let x_key3 = crate::rt_api::make_rt_string("x".to_string());
    let val = crate::rt_api::__esc_rt_get_prop(obj_bits, x_key3);
    assert_eq!(
        JsValue::from_raw_bits(val).as_int(),
        Some(1),
        "with-object's x should be unchanged after unscopable store"
    );
}

