#[test]
fn test_esc_env_abi_populate_slot_map() {
    // Create an env with 3 slots, populate slot_map entries, and verify
    // that dynamic name lookup works through the slot_map.
    let env = crate::rt_api::__esc_rt_esc_env_create(3, 0);

    // Populate slot_map: "x" -> slot 0, "y" -> slot 1
    let x_name = crate::rt_api::make_rt_string("x".to_string());
    let y_name = crate::rt_api::make_rt_string("y".to_string());
    let slot_0 = JsValue::int(0).raw_bits();
    let slot_1 = JsValue::int(1).raw_bits();
    crate::rt_api::__esc_rt_esc_env_populate_slot_map(env, x_name, slot_0);
    crate::rt_api::__esc_rt_esc_env_populate_slot_map(env, y_name, slot_1);

    // Set values in slots
    crate::rt_api::__esc_rt_esc_env_set(env, 0, JsValue::int(42).raw_bits());
    crate::rt_api::__esc_rt_esc_env_set(env, 1, JsValue::int(99).raw_bits());

    // Dynamic lookup by name should find the values
    let x_val =
        crate::rt_api::__esc_rt_esc_env_lookup(env, crate::rt_api::make_rt_string("x".to_string()));
    let y_val =
        crate::rt_api::__esc_rt_esc_env_lookup(env, crate::rt_api::make_rt_string("y".to_string()));
    assert_eq!(JsValue::from_raw_bits(x_val).as_int(), Some(42));
    assert_eq!(JsValue::from_raw_bits(y_val).as_int(), Some(99));
}

