#[test]
fn test_detect_strict_mode() {
    // Exposed via the runtime ABI call
    let strict_code = "\"use strict\"; var x = 1;";
    let trimmed = strict_code.trim_start();
    assert!(
        trimmed.starts_with("\"use strict\""),
        "should detect double-quoted use strict"
    );

    let strict_single = "'use strict'; var x = 1;";
    let trimmed2 = strict_single.trim_start();
    assert!(
        trimmed2.starts_with("'use strict'"),
        "should detect single-quoted use strict"
    );

    let not_strict = "var x = 1;";
    let trimmed3 = not_strict.trim_start();
    assert!(
        !trimmed3.starts_with("\"use strict\"") && !trimmed3.starts_with("'use strict'"),
        "should not detect use strict in non-strict code"
    );
}

