// -------------------------------------------------------------------------
// Proxy intercepts ownKeys (Object.keys returns trap result)
// -------------------------------------------------------------------------
#[test]
fn test_proxy_dispatch_own_keys_intercept() {
    use crate::internal_data::UnifiedObject;
    use crate::rt_api::{__esc_rt_create_object, __esc_rt_create_proxy, __esc_rt_set_prop};
    use crate::tagged_obj::{ObjTag, TaggedObj};

    let target = __esc_rt_create_object();
    __esc_rt_set_prop(target, make_string_value("a"), JsValue::int(1).raw_bits());

    // Create a handler with an ownKeys trap that returns ["x", "y"]
    let trap_fn = UnifiedObject::native_func(
        |_ctx| {
            crate::rt_api::create_array_from_elements(vec![
                JsValue::from_raw_bits(make_string_value("x")),
                JsValue::from_raw_bits(make_string_value("y")),
            ])
        },
        0,
    );
    let trap_bits = TaggedObj::boxed(ObjTag::Unified, trap_fn);

    let handler = __esc_rt_create_object();
    __esc_rt_set_prop(handler, make_string_value("ownKeys"), trap_bits);

    let proxy = __esc_rt_create_proxy(target, handler);

    // Object.keys on the proxy should return the trap result
    let keys = crate::rt_api::__esc_rt_object_keys(proxy);
    let keys_tag = crate::tagged_obj::read_obj_tag(keys);
    assert_eq!(keys_tag, Some(ObjTag::Unified as u8));

    let uni = unsafe { crate::tagged_obj::deref_tagged::<UnifiedObject>(keys) };
    assert!(uni.is_some());
    let u = uni.unwrap();
    assert_eq!(u.kind, crate::internal_data::InternalKind::Array);
    // Should have 2 elements: "x" and "y"
    assert_eq!(u.array_len(), 2);
}

// -------------------------------------------------------------------------
// Proxy intercepts getPrototypeOf
// -------------------------------------------------------------------------
#[test]
fn test_proxy_dispatch_get_prototype_of_intercept() {
    use crate::internal_data::UnifiedObject;
    use crate::rt_api::{__esc_rt_create_object, __esc_rt_create_proxy, __esc_rt_set_prop};
    use crate::tagged_obj::{ObjTag, TaggedObj};

    let target = __esc_rt_create_object();
    let custom_proto = __esc_rt_create_object();
    __esc_rt_set_prop(
        custom_proto,
        make_string_value("marker"),
        JsValue::int(888).raw_bits(),
    );

    // Create a handler with a getPrototypeOf trap that returns custom_proto
    // Store custom_proto in the context parameter, the native func reads it back
    let trap_fn = UnifiedObject::native_func(|ctx| ctx, custom_proto);
    let trap_bits = TaggedObj::boxed(ObjTag::Unified, trap_fn);

    let handler = __esc_rt_create_object();
    __esc_rt_set_prop(handler, make_string_value("getPrototypeOf"), trap_bits);

    let proxy = __esc_rt_create_proxy(target, handler);

    let args = [JsValue::from_raw_bits(proxy)];
    let result = crate::rt_api::dispatch_object_static_method(
        "getPrototypeOf",
        1,
        args.iter()
            .map(|v| v.raw_bits())
            .collect::<Vec<_>>()
            .as_ptr(),
    );

    assert!(
        result.is_some(),
        "getPrototypeOf on proxy should return result"
    );
    // The result might be the custom_proto or the trap result
    // Since the trap returns custom_proto which is a valid object
    assert!(
        JsValue::from_raw_bits(result.unwrap_or(0)).is_object(),
        "getPrototypeOf trap should return an object"
    );
}

