// -------------------------------------------------------------------------
// Proxy intercepts preventExtensions
// -------------------------------------------------------------------------
#[test]
fn test_proxy_dispatch_prevent_extensions_intercept() {
    use crate::internal_data::UnifiedObject;
    use crate::rt_api::{__esc_rt_create_object, __esc_rt_create_proxy, __esc_rt_set_prop};
    use crate::tagged_obj::{ObjTag, TaggedObj};

    let target = __esc_rt_create_object();

    // preventExtensions on the target first so the invariant check passes
    {
        let tag = crate::tagged_obj::read_obj_tag(target);
        if tag == Some(ObjTag::Unified as u8) {
            let uni = unsafe { crate::tagged_obj::deref_tagged_mut::<UnifiedObject>(target) };
            if let Some(u) = uni {
                u.prevent_extensions();
            }
        }
    }

    // Create a handler with a preventExtensions trap that returns true
    let trap_fn = UnifiedObject::native_func(|_ctx| JsValue::bool(true).raw_bits(), 0);
    let trap_bits = TaggedObj::boxed(ObjTag::Unified, trap_fn);

    let handler = __esc_rt_create_object();
    __esc_rt_set_prop(handler, make_string_value("preventExtensions"), trap_bits);

    let proxy = __esc_rt_create_proxy(target, handler);

    let args = [JsValue::from_raw_bits(proxy)];
    let result = crate::rt_api::dispatch_object_static_method(
        "preventExtensions",
        1,
        args.iter()
            .map(|v| v.raw_bits())
            .collect::<Vec<_>>()
            .as_ptr(),
    );

    assert!(result.is_some());
    assert_eq!(
        result.unwrap_or(0),
        proxy,
        "preventExtensions should return the proxy"
    );
}

