// -------------------------------------------------------------------------
// Constructable Proxy: new goes through construct trap
// -------------------------------------------------------------------------
#[test]
fn test_proxy_dispatch_constructable_proxy_construct_trap() {
    use crate::internal_data::UnifiedObject;
    use crate::rt_api::{__esc_rt_create_object, __esc_rt_create_proxy, __esc_rt_set_prop};
    use crate::tagged_obj::{ObjTag, TaggedObj};

    // Create a constructable target (function with is_constructable flag)
    let mut target_fn = UnifiedObject::native_func(|_ctx| JsValue::undefined().raw_bits(), 0);
    target_fn.flags.set_constructable();
    let target = TaggedObj::boxed(ObjTag::Unified, target_fn);

    // Create a handler with a construct trap that returns a new object with marker
    let construct_trap = UnifiedObject::native_func(
        |_ctx| {
            let obj = crate::rt_api::__esc_rt_create_object();
            crate::rt_api::__esc_rt_set_prop(
                obj,
                make_string_value("constructed"),
                JsValue::bool(true).raw_bits(),
            );
            obj
        },
        0,
    );
    let construct_bits = TaggedObj::boxed(ObjTag::Unified, construct_trap);

    let handler = __esc_rt_create_object();
    __esc_rt_set_prop(handler, make_string_value("construct"), construct_bits);

    let proxy = __esc_rt_create_proxy(target, handler);

    // Construct through the proxy — should go through the construct trap
    let result = crate::proxy::proxy_construct(proxy, &[], proxy);
    assert!(result.is_ok());
    let obj = result.unwrap_or(0);
    assert!(
        JsValue::from_raw_bits(obj).is_object(),
        "construct trap should return an object"
    );
    // Check the marker property
    let marker = crate::rt_api::__esc_rt_get_prop(obj, make_string_value("constructed"));
    assert_eq!(
        JsValue::from_raw_bits(marker).as_bool(),
        Some(true),
        "constructed object should have marker"
    );
}

