// -------------------------------------------------------------------------
// Nested Proxy: Proxy wrapping Proxy
// -------------------------------------------------------------------------
#[test]
fn test_proxy_dispatch_nested_proxy() {
    use crate::internal_data::UnifiedObject;
    use crate::rt_api::{
        __esc_rt_create_object, __esc_rt_create_proxy, __esc_rt_get_prop, __esc_rt_set_prop,
    };
    use crate::tagged_obj::{ObjTag, TaggedObj};

    let target = __esc_rt_create_object();
    __esc_rt_set_prop(target, make_string_value("x"), JsValue::int(42).raw_bits());

    // Inner proxy: no traps (transparent)
    let inner_handler = __esc_rt_create_object();
    let inner_proxy = __esc_rt_create_proxy(target, inner_handler);

    // Outer proxy: get trap that returns 999
    let trap_fn = UnifiedObject::native_func(|_ctx| JsValue::int(999).raw_bits(), 0);
    let trap_bits = TaggedObj::boxed(ObjTag::Unified, trap_fn);

    let outer_handler = __esc_rt_create_object();
    __esc_rt_set_prop(outer_handler, make_string_value("get"), trap_bits);

    let outer_proxy = __esc_rt_create_proxy(inner_proxy, outer_handler);

    // Get through the outer proxy should invoke the outer trap
    let result = __esc_rt_get_prop(outer_proxy, make_string_value("x"));
    assert_eq!(
        JsValue::from_raw_bits(result).as_int(),
        Some(999),
        "outer proxy get trap should be invoked"
    );
}

