fn test_proxy_dispatch_object_keys_no_trap_forwards() {
    use crate::internal_data::UnifiedObject;
    use crate::rt_api::{
        __esc_rt_create_object, __esc_rt_create_proxy, __esc_rt_object_keys, __esc_rt_set_prop,
    };

    let target = __esc_rt_create_object();
    __esc_rt_set_prop(target, make_string_value("a"), JsValue::int(1).raw_bits());
    __esc_rt_set_prop(target, make_string_value("b"), JsValue::int(2).raw_bits());

    // Handler with no ownKeys trap
    let handler = __esc_rt_create_object();
    let proxy = __esc_rt_create_proxy(target, handler);

    let keys = __esc_rt_object_keys(proxy);
    let keys_tag = crate::tagged_obj::read_obj_tag(keys);
    assert_eq!(keys_tag, Some(ObjTag::Unified as u8));

    let uni = unsafe { crate::tagged_obj::deref_tagged::<UnifiedObject>(keys) };
    assert!(uni.is_some());
    let u = uni.unwrap();
    assert_eq!(u.kind, crate::internal_data::InternalKind::Array);
    // Should have 2 elements from the target's own properties
    assert_eq!(u.array_len(), 2, "keys from target should have 2 elements");
}

// -------------------------------------------------------------------------
// Proxy callable with no apply trap falls through to target call
// -------------------------------------------------------------------------
#[test]
fn test_proxy_dispatch_callable_no_apply_trap_fallthrough() {
    use crate::internal_data::UnifiedObject;
    use crate::rt_api::{__esc_rt_create_object, __esc_rt_create_proxy};
    use crate::tagged_obj::{ObjTag, TaggedObj};

    // Create a callable target that returns 42
    let target_fn = UnifiedObject::native_func(|_ctx| JsValue::int(42).raw_bits(), 0);
    let target = TaggedObj::boxed(ObjTag::Unified, target_fn);

    // Handler with no traps
    let handler = __esc_rt_create_object();
    let proxy = __esc_rt_create_proxy(target, handler);

    // Calling the proxy without an apply trap should forward to target
    let result = crate::proxy::proxy_call(proxy, JsValue::undefined().raw_bits(), &[]);
    assert!(result.is_ok());
    assert_eq!(
        JsValue::from_raw_bits(result.unwrap_or(0)).as_int(),
        Some(42),
        "proxy call without apply trap should forward to target"
    );
}

