#[test]
fn test_has_own_property_ordinary_object() {
    use crate::rt_api::{__esc_rt_create_object, __esc_rt_set_prop, make_rt_string};

    let obj = __esc_rt_create_object();
    let key = make_rt_string("x".to_string());
    __esc_rt_set_prop(obj, key, JsValue::int(42).raw_bits());

    let x_key = make_rt_string("x".to_string());
    let result = unsafe {
        crate::rt_api::__esc_rt_call_method(
            obj,
            make_rt_string("hasOwnProperty".to_string()),
            1,
            [x_key].as_ptr(),
        )
    };
    let val = JsValue::from_raw_bits(result);
    assert_eq!(
        val.as_bool(),
        Some(true),
        "hasOwnProperty should return true for own property"
    );

    let y_key = make_rt_string("y".to_string());
    let result2 = unsafe {
        crate::rt_api::__esc_rt_call_method(
            obj,
            make_rt_string("hasOwnProperty".to_string()),
            1,
            [y_key].as_ptr(),
        )
    };
    let val2 = JsValue::from_raw_bits(result2);
    assert_eq!(
        val2.as_bool(),
        Some(false),
        "hasOwnProperty should return false for missing property"
    );
}

