    assert_eq!(es_parse_int("0xFF", 0), 255.0);
    assert_eq!(es_parse_int("0XFF", 0), 255.0);
    assert_eq!(es_parse_int("ff", 16), 255.0);
    assert_eq!(es_parse_int("0xff", 16), 255.0);
