#[test]
fn test_parse_int_nan_cases() {
    use crate::rt_api::es_parse_int;
    assert!(es_parse_int("", 0).is_nan());
    assert!(es_parse_int("abc", 0).is_nan());
    assert!(es_parse_int("xyz", 10).is_nan());
}

#[test]
fn test_parse_int_radix() {
    use crate::rt_api::es_parse_int;
    assert_eq!(es_parse_int("10", 2), 2.0); // binary
    assert_eq!(es_parse_int("10", 8), 8.0); // octal
    assert_eq!(es_parse_int("10", 16), 16.0); // hex
    assert_eq!(es_parse_int("10", 36), 36.0); // base 36
    assert!(es_parse_int("10", 37).is_nan()); // invalid radix
    assert!(es_parse_int("10", 1).is_nan()); // invalid radix
}

