// =========================================================================
// H4: Exponentiation edge-case tests (ES2023 6.1.6.1.6)
// =========================================================================

// -------------------------------------------------------------------------
// H4.1 test_exp_zero_exponent_returns_one
// -------------------------------------------------------------------------

#[test]
fn test_exp_zero_exponent_returns_one() {
    // Any value ** 0 === 1, including NaN ** 0
    assert_eq!(
        crate::value_ops::js_exp(JsValue::int(2), JsValue::int(0)).as_number(),
        Some(1.0),
        "2 ** 0 should be 1"
    );
    assert_eq!(
        crate::value_ops::js_exp(JsValue::number(f64::NAN), JsValue::int(0)).as_number(),
        Some(1.0),
        "NaN ** 0 should be 1"
    );
    assert_eq!(
        crate::value_ops::js_exp(JsValue::number(f64::INFINITY), JsValue::int(0)).as_number(),
        Some(1.0),
        "Infinity ** 0 should be 1"
    );
    assert_eq!(
        crate::value_ops::js_exp(JsValue::number(f64::NEG_INFINITY), JsValue::int(0)).as_number(),
        Some(1.0),
        "-Infinity ** 0 should be 1"
    );
}

// -------------------------------------------------------------------------
// H4.2 test_exp_negative_zero_exponent_returns_one
// -------------------------------------------------------------------------

#[test]
fn test_exp_negative_zero_exponent_returns_one() {
    // x ** -0 === 1 for any x
    let neg_zero = JsValue::number(-0.0);
    assert_eq!(
        crate::value_ops::js_exp(JsValue::int(2), neg_zero).as_number(),
        Some(1.0),
        "2 ** (-0) should be 1"
    );
    assert_eq!(
        crate::value_ops::js_exp(JsValue::number(f64::NAN), neg_zero).as_number(),
        Some(1.0),
        "NaN ** (-0) should be 1"
    );
}

// -------------------------------------------------------------------------
// H4.3 test_exp_nan_exponent
// -------------------------------------------------------------------------

#[test]
fn test_exp_nan_exponent() {
    // x ** NaN === NaN for any x (except covered by step 4: x ** 0 = 1)
    let result = crate::value_ops::js_exp(JsValue::int(2), JsValue::number(f64::NAN));
    assert!(
        result.as_number().is_some_and(|n| n.is_nan()),
        "2 ** NaN should be NaN"
    );
    let result2 = crate::value_ops::js_exp(JsValue::int(0), JsValue::number(f64::NAN));
    assert!(
        result2.as_number().is_some_and(|n| n.is_nan()),
        "0 ** NaN should be NaN"
    );
}

// -------------------------------------------------------------------------
// H4.4 test_exp_nan_base
// -------------------------------------------------------------------------

#[test]
fn test_exp_nan_base() {
    // NaN ** non-zero === NaN
    let result = crate::value_ops::js_exp(JsValue::number(f64::NAN), JsValue::int(2));
    assert!(
        result.as_number().is_some_and(|n| n.is_nan()),
        "NaN ** 2 should be NaN"
    );
    let result2 = crate::value_ops::js_exp(JsValue::number(f64::NAN), JsValue::int(-1));
    assert!(
        result2.as_number().is_some_and(|n| n.is_nan()),
        "NaN ** -1 should be NaN"
    );
}

// -------------------------------------------------------------------------
// H4.5 test_exp_abs_base_1_infinite_exponent
// -------------------------------------------------------------------------

#[test]
fn test_exp_abs_base_1_infinite_exponent() {
    // ES spec divergence from IEEE 754: |base| == 1, exp == ±Infinity → NaN
    let result = crate::value_ops::js_exp(JsValue::int(1), JsValue::number(f64::INFINITY));
    assert!(
        result.as_number().is_some_and(|n| n.is_nan()),
        "1 ** Infinity should be NaN (ES spec)"
    );
    let result2 = crate::value_ops::js_exp(JsValue::int(1), JsValue::number(f64::NEG_INFINITY));
    assert!(
        result2.as_number().is_some_and(|n| n.is_nan()),
        "1 ** -Infinity should be NaN (ES spec)"
    );
    let result3 = crate::value_ops::js_exp(JsValue::int(-1), JsValue::number(f64::INFINITY));
    assert!(
        result3.as_number().is_some_and(|n| n.is_nan()),
        "(-1) ** Infinity should be NaN (ES spec)"
    );
    let result4 = crate::value_ops::js_exp(JsValue::int(-1), JsValue::number(f64::NEG_INFINITY));
    assert!(
        result4.as_number().is_some_and(|n| n.is_nan()),
        "(-1) ** -Infinity should be NaN (ES spec)"
    );
}

// -------------------------------------------------------------------------
// H4.6 test_exp_abs_greater_than_1_infinite_exponent
// -------------------------------------------------------------------------

#[test]
fn test_exp_abs_greater_than_1_infinite_exponent() {
    // |base| > 1 and exp == +Infinity → +Infinity
    assert_eq!(
        crate::value_ops::js_exp(JsValue::int(2), JsValue::number(f64::INFINITY)).as_number(),
        Some(f64::INFINITY),
        "2 ** Infinity should be Infinity"
    );
    // |base| > 1 and exp == -Infinity → +0
    assert_eq!(
        crate::value_ops::js_exp(JsValue::int(2), JsValue::number(f64::NEG_INFINITY)).as_number(),
        Some(0.0),
        "2 ** -Infinity should be 0"
    );
}

// -------------------------------------------------------------------------
// H4.7 test_exp_abs_less_than_1_infinite_exponent
// -------------------------------------------------------------------------

#[test]
fn test_exp_abs_less_than_1_infinite_exponent() {
    // |base| < 1 and exp == +Infinity → +0
    assert_eq!(
        crate::value_ops::js_exp(JsValue::number(0.5), JsValue::number(f64::INFINITY)).as_number(),
        Some(0.0),
        "0.5 ** Infinity should be 0"
    );
    // |base| < 1 and exp == -Infinity → +Infinity
    assert_eq!(
        crate::value_ops::js_exp(JsValue::number(0.5), JsValue::number(f64::NEG_INFINITY))
            .as_number(),
        Some(f64::INFINITY),
        "0.5 ** -Infinity should be Infinity"
    );
}

// -------------------------------------------------------------------------
// H4.8 test_exp_infinity_base
// -------------------------------------------------------------------------

#[test]
fn test_exp_infinity_base() {
    // Infinity ** positive → Infinity
    assert_eq!(
        crate::value_ops::js_exp(JsValue::number(f64::INFINITY), JsValue::int(2)).as_number(),
        Some(f64::INFINITY),
        "Infinity ** 2 should be Infinity"
    );
    // Infinity ** negative → 0
    assert_eq!(
        crate::value_ops::js_exp(JsValue::number(f64::INFINITY), JsValue::int(-2)).as_number(),
        Some(0.0),
        "Infinity ** -2 should be 0"
    );
}

// -------------------------------------------------------------------------
// H4.9 test_exp_zero_base
// -------------------------------------------------------------------------

#[test]
fn test_exp_zero_base() {
    // 0 ** positive → 0
    assert_eq!(
        crate::value_ops::js_exp(JsValue::int(0), JsValue::int(2)).as_number(),
        Some(0.0),
        "0 ** 2 should be 0"
    );
    // 0 ** negative → Infinity
    assert_eq!(
        crate::value_ops::js_exp(JsValue::int(0), JsValue::int(-1)).as_number(),
        Some(f64::INFINITY),
        "0 ** -1 should be Infinity"
    );
}

// -------------------------------------------------------------------------
// H4.10 test_exp_right_associativity
// -------------------------------------------------------------------------

#[test]
fn test_exp_right_associativity() {
    // 2 ** 3 ** 2 should be 2 ** (3 ** 2) = 2 ** 9 = 512
    // We test the numeric result here; the parser handles associativity.
    // First compute 3 ** 2 = 9
    let inner = crate::value_ops::js_exp(JsValue::int(3), JsValue::int(2));
    assert_eq!(inner.as_number(), Some(9.0), "3 ** 2 should be 9");
    // Then 2 ** 9 = 512
    let result = crate::value_ops::js_exp(JsValue::int(2), inner);
    assert_eq!(result.as_number(), Some(512.0), "2 ** 9 should be 512");
}

// -------------------------------------------------------------------------
// H4.11 test_exp_negative_base_fractional_exponent
// -------------------------------------------------------------------------

#[test]
fn test_exp_negative_base_fractional_exponent() {
    // (-2) ** 0.5 → NaN (square root of negative number)
    let result = crate::value_ops::js_exp(JsValue::number(-2.0), JsValue::number(0.5));
    assert!(
        result.as_number().is_some_and(|n| n.is_nan()),
        "(-2) ** 0.5 should be NaN"
    );
}

// -------------------------------------------------------------------------
// H4.12 test_exp_basic_cases
// -------------------------------------------------------------------------

#[test]
fn test_exp_basic_cases() {
    // 2 ** 10 = 1024
    assert_eq!(
        crate::value_ops::js_exp(JsValue::int(2), JsValue::int(10)).as_number(),
        Some(1024.0),
        "2 ** 10 should be 1024"
    );
    // 2 ** -1 = 0.5
    assert_eq!(
        crate::value_ops::js_exp(JsValue::int(2), JsValue::int(-1)).as_number(),
        Some(0.5),
        "2 ** -1 should be 0.5"
    );
    // 10 ** 3 = 1000
    assert_eq!(
        crate::value_ops::js_exp(JsValue::int(10), JsValue::int(3)).as_number(),
        Some(1000.0),
        "10 ** 3 should be 1000"
    );
}

// -------------------------------------------------------------------------
// H4.13 test_exp_negative_zero_base
// -------------------------------------------------------------------------

#[test]
fn test_exp_negative_zero_base() {
    // (-0) ** positive odd integer → -0
    let result = crate::value_ops::js_exp(JsValue::number(-0.0), JsValue::int(3));
    let n = result.as_number().expect("should be number");
    assert!(n == 0.0 && n.is_sign_negative(), "(-0) ** 3 should be -0");

    // (-0) ** positive even integer → +0
    let result2 = crate::value_ops::js_exp(JsValue::number(-0.0), JsValue::int(2));
    let n2 = result2.as_number().expect("should be number");
    assert!(n2 == 0.0 && n2.is_sign_positive(), "(-0) ** 2 should be +0");
}

