// -------------------------------------------------------------------------
// H5.1 test_instanceof_primitive_obj_returns_false
// -------------------------------------------------------------------------

#[test]
fn test_instanceof_primitive_obj_returns_false() {
    // Non-object LHS always returns false in OrdinaryHasInstance
    let result = crate::rt_api::__esc_rt_instanceof(
        JsValue::int(42).raw_bits(),
        // Create a callable object to avoid the "not callable" TypeError
        crate::tagged_obj::TaggedObj::boxed(
            crate::tagged_obj::ObjTag::Unified,
            crate::internal_data::UnifiedObject::closure(ShapeTable::EMPTY_SHAPE, 0, 0, 0),
        ),
    );
    assert_eq!(
        JsValue::from_raw_bits(result).as_bool(),
        Some(false),
        "42 instanceof func should be false"
    );
}

