// -------------------------------------------------------------------------
// H5.4 test_instanceof_error_subtype_is_error
// -------------------------------------------------------------------------

#[test]
fn test_instanceof_error_subtype_is_error() {
    // All error subtypes should be instanceof Error (string-based constructor path)
    let msg = crate::rt_api::make_rt_string("test".to_string());
    let type_err =
        crate::rt_api::__esc_rt_create_error(crate::exceptions::error_tag::TYPE_ERROR, msg);
    let error_ctor = crate::rt_api::make_rt_string("Error".to_string());
    let result = crate::rt_api::__esc_rt_instanceof(type_err, error_ctor);
    assert_eq!(
        JsValue::from_raw_bits(result).as_bool(),
        Some(true),
        "TypeError instance should be instanceof Error"
    );

    let type_ctor = crate::rt_api::make_rt_string("TypeError".to_string());
    let result2 = crate::rt_api::__esc_rt_instanceof(type_err, type_ctor);
    assert_eq!(
        JsValue::from_raw_bits(result2).as_bool(),
        Some(true),
        "TypeError instance should be instanceof TypeError"
    );
}

