#[test]
fn test_instanceof_error_wrong_subtype() {
    let msg = crate::rt_api::make_rt_string("test".to_string());
    let type_err =
        crate::rt_api::__esc_rt_create_error(crate::exceptions::error_tag::TYPE_ERROR, msg);
    let range_ctor = crate::rt_api::make_rt_string("RangeError".to_string());
    let result = crate::rt_api::__esc_rt_instanceof(type_err, range_ctor);
    assert_eq!(
        JsValue::from_raw_bits(result).as_bool(),
        Some(false),
        "TypeError instance should NOT be instanceof RangeError"
    );
}

// -------------------------------------------------------------------------
// H5.6 test_instanceof_all_error_subtypes
// -------------------------------------------------------------------------

#[test]
fn test_instanceof_all_error_subtypes() {
    use crate::exceptions::error_tag;

    let subtypes = [
        (error_tag::TYPE_ERROR, "TypeError"),
        (error_tag::RANGE_ERROR, "RangeError"),
        (error_tag::REFERENCE_ERROR, "ReferenceError"),
        (error_tag::SYNTAX_ERROR, "SyntaxError"),
        (error_tag::URI_ERROR, "URIError"),
        (error_tag::EVAL_ERROR, "EvalError"),
    ];
    for (tag, name) in subtypes {
        let msg = crate::rt_api::make_rt_string("test".to_string());
        let err = crate::rt_api::__esc_rt_create_error(tag, msg);

        // Should be instanceof its own type
        let own_ctor = crate::rt_api::make_rt_string(name.to_string());
        let result = crate::rt_api::__esc_rt_instanceof(err, own_ctor);
        assert_eq!(
            JsValue::from_raw_bits(result).as_bool(),
            Some(true),
            "{name} should be instanceof {name}"
        );

        // Should be instanceof Error (base class)
        let base_ctor = crate::rt_api::make_rt_string("Error".to_string());
        let result2 = crate::rt_api::__esc_rt_instanceof(err, base_ctor);
        assert_eq!(
            JsValue::from_raw_bits(result2).as_bool(),
            Some(true),
            "{name} should be instanceof Error"
        );
    }
}

