// =========================================================================
// H1 — Type Coercion Hardening: Abstract equality edge cases
// =========================================================================

#[test]
fn test_abstract_eq_null_equals_undefined() {
    // null == undefined is true
    assert!(crate::value_ops::abstract_eq(
        JsValue::null(),
        JsValue::undefined()
    ));
    assert!(crate::value_ops::abstract_eq(
        JsValue::undefined(),
        JsValue::null()
    ));
}

#[test]
fn test_abstract_eq_null_not_equals_zero() {
    // null == 0 is false (null only == null or undefined)
    assert!(!crate::value_ops::abstract_eq(
        JsValue::null(),
        JsValue::int(0)
    ));
}

#[test]
fn test_abstract_eq_null_not_equals_empty_string() {
    // null == "" is false
    let empty = JsValue::from_raw_bits(make_string_value(""));
    assert!(!crate::value_ops::abstract_eq(JsValue::null(), empty));
}

#[test]
fn test_abstract_eq_null_not_equals_false() {
    // null == false is false
    assert!(!crate::value_ops::abstract_eq(
        JsValue::null(),
        JsValue::bool(false)
    ));
}

#[test]
fn test_abstract_eq_undefined_not_equals_zero() {
    // undefined == 0 is false
    assert!(!crate::value_ops::abstract_eq(
        JsValue::undefined(),
        JsValue::int(0)
    ));
}

#[test]
fn test_abstract_eq_undefined_not_equals_empty_string() {
    // undefined == "" is false
    let empty = JsValue::from_raw_bits(make_string_value(""));
    assert!(!crate::value_ops::abstract_eq(JsValue::undefined(), empty));
}

#[test]
fn test_abstract_eq_bool_converts_to_number() {
    // true == 1 is true (ToNumber(true) = 1)
    assert!(crate::value_ops::abstract_eq(
        JsValue::bool(true),
        JsValue::int(1)
    ));
    // false == 0 is true (ToNumber(false) = 0)
    assert!(crate::value_ops::abstract_eq(
        JsValue::bool(false),
        JsValue::int(0)
    ));
    // true == 2 is false
    assert!(!crate::value_ops::abstract_eq(
        JsValue::bool(true),
        JsValue::int(2)
    ));
}

#[test]
fn test_abstract_eq_string_converts_to_number() {
    // "1" == 1 is true (ToNumber("1") = 1)
    let one_str = JsValue::from_raw_bits(make_string_value("1"));
    assert!(crate::value_ops::abstract_eq(one_str, JsValue::int(1)));
    // "" == 0 is true (ToNumber("") = 0)
    let empty = JsValue::from_raw_bits(make_string_value(""));
    assert!(crate::value_ops::abstract_eq(empty, JsValue::int(0)));
}

#[test]
fn test_abstract_eq_nan_not_equals_nan() {
    // NaN == NaN is false (even with abstract equality)
    assert!(!crate::value_ops::abstract_eq(
        JsValue::number(f64::NAN),
        JsValue::number(f64::NAN)
    ));
}

// =========================================================================
// H1 — Type Coercion Hardening: Relational operator coercion
// =========================================================================

#[test]
fn test_relational_string_vs_number_coercion() {
    // "2" > 1 is true (string "2" coerced to number 2)
    let two_str = JsValue::from_raw_bits(make_string_value("2"));
    assert!(crate::value_ops::js_gt(two_str, JsValue::int(1)));
}

#[test]
fn test_relational_null_coercion_to_zero() {
    // null < 1 is true (ToNumber(null) = 0)
    assert!(crate::value_ops::js_lt(JsValue::null(), JsValue::int(1)));
    // null > -1 is true
    assert!(crate::value_ops::js_gt(JsValue::null(), JsValue::int(-1)));
    // null >= 0 is true
    assert!(crate::value_ops::js_ge(JsValue::null(), JsValue::int(0)));
    // null <= 0 is true
    assert!(crate::value_ops::js_le(JsValue::null(), JsValue::int(0)));
}

#[test]
fn test_relational_undefined_returns_false() {
    // Any comparison with undefined returns false (NaN comparisons)
    assert!(!crate::value_ops::js_lt(
        JsValue::undefined(),
        JsValue::int(0)
    ));
    assert!(!crate::value_ops::js_gt(
        JsValue::undefined(),
        JsValue::int(0)
    ));
    assert!(!crate::value_ops::js_le(
        JsValue::undefined(),
        JsValue::int(0)
    ));
    assert!(!crate::value_ops::js_ge(
        JsValue::undefined(),
        JsValue::int(0)
    ));
}

#[test]
fn test_relational_bool_coercion_to_number() {
    // true > false is true (1 > 0)
    assert!(crate::value_ops::js_gt(
        JsValue::bool(true),
        JsValue::bool(false)
    ));
    // false < true is true
    assert!(crate::value_ops::js_lt(
        JsValue::bool(false),
        JsValue::bool(true)
    ));
}

// =========================================================================
// H1 — Type Coercion Hardening: ToPrimitive hint handling
// =========================================================================

#[test]
fn test_to_primitive_on_non_object_is_identity() {
    // Primitives pass through ToPrimitive unchanged
    let n = JsValue::int(42);
    assert_eq!(
        crate::value_ops::to_primitive(n, crate::value_ops::ToPrimitiveHint::Number).raw_bits(),
        n.raw_bits()
    );

    let s = JsValue::from_raw_bits(make_string_value("hello"));
    assert_eq!(
        crate::value_ops::to_primitive(s, crate::value_ops::ToPrimitiveHint::String).raw_bits(),
        s.raw_bits()
    );

    let b = JsValue::bool(true);
    assert_eq!(
        crate::value_ops::to_primitive(b, crate::value_ops::ToPrimitiveHint::Default).raw_bits(),
        b.raw_bits()
    );
}

