// S5: JSON.stringify array replacer + string space tests
// =========================================================================

#[test]
fn test_json_stringify_string_space() {
    use crate::rt_api::dispatch_json_method;
    // JSON.stringify({a:1}, null, "--")
    let obj = crate::rt_api::__esc_rt_create_object();
    let key = make_string_value("a");
    crate::rt_api::__esc_rt_set_prop(obj, key, JsValue::int(1).raw_bits());
    let args: [u64; 3] = [obj, JsValue::null().raw_bits(), make_string_value("--")];
    let result = dispatch_json_method("stringify", 3, args.as_ptr());
    let result_str = crate::string_ops::get_string_data(JsValue::from_raw_bits(result.unwrap()));
    // Should have "--" indentation
    assert!(
        result_str.contains("--"),
        "Expected '--' indent, got: {result_str}"
    );
    assert!(result_str.contains("\"a\""), "Expected key 'a' in output");
}

#[test]
fn test_json_stringify_array_replacer() {
    use crate::rt_api::dispatch_json_method;
    // JSON.stringify({a:1, b:2, c:3}, ["a", "c"])
    let obj = crate::rt_api::__esc_rt_create_object();
    crate::rt_api::__esc_rt_set_prop(obj, make_string_value("a"), JsValue::int(1).raw_bits());
    crate::rt_api::__esc_rt_set_prop(obj, make_string_value("b"), JsValue::int(2).raw_bits());
    crate::rt_api::__esc_rt_set_prop(obj, make_string_value("c"), JsValue::int(3).raw_bits());
    // Create replacer array ["a", "c"]
    let replacer_elems = vec![
        JsValue::from_raw_bits(make_string_value("a")),
        JsValue::from_raw_bits(make_string_value("c")),
    ];
    let replacer = crate::rt_api::create_array_from_elements(replacer_elems);
    let args: [u64; 2] = [obj, replacer];
    let result = dispatch_json_method("stringify", 2, args.as_ptr());
    let result_str = crate::string_ops::get_string_data(JsValue::from_raw_bits(result.unwrap()));
    // Should only contain "a" and "c", not "b"
    assert!(result_str.contains("\"a\""), "Expected 'a' in output");
    assert!(result_str.contains("\"c\""), "Expected 'c' in output");
    assert!(
        !result_str.contains("\"b\""),
        "Should not contain 'b' in output, got: {result_str}"
    );
}

