fn test_configurable_data_to_accessor_transition() {
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Define configurable data property
    let data_opts = property::DefinePropertyOptions {
        value: Some(JsValue::int(42)),
        writable: Some(true),
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("x", &data_opts, &mut shapes, &interner)
        .unwrap();
    assert!(!obj.is_accessor_property("x", &shapes, &interner));

    // Redefine as accessor
    let acc_opts = property::DefinePropertyOptions {
        getter: Some(JsValue::int(100)),
        setter: Some(JsValue::int(200)),
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("x", &acc_opts, &mut shapes, &interner)
        .unwrap();
    assert!(obj.is_accessor_property("x", &shapes, &interner));

    // Verify getter/setter
    assert_eq!(
        obj.get_accessor_getter("x", &shapes, &interner)
            .unwrap()
            .as_int(),
        Some(100)
    );
    assert_eq!(
        obj.get_accessor_setter("x", &shapes, &interner)
            .unwrap()
            .as_int(),
        Some(200)
    );
}

