// H3-PD9: Accessor to accessor update getter/setter
// -------------------------------------------------------------------------
#[test]
fn test_accessor_to_accessor_update_getter_setter() {
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Define configurable accessor
    let opts1 = property::DefinePropertyOptions {
        getter: Some(JsValue::int(10)),
        setter: Some(JsValue::int(20)),
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("x", &opts1, &mut shapes, &interner)
        .unwrap();

    // Update just the getter
    let opts2 = property::DefinePropertyOptions {
        getter: Some(JsValue::int(30)),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("x", &opts2, &mut shapes, &interner)
        .unwrap();

    // Getter should be updated, setter should remain
    assert_eq!(
        obj.get_accessor_getter("x", &shapes, &interner)
            .unwrap()
            .as_int(),
        Some(30)
    );
    assert_eq!(
        obj.get_accessor_setter("x", &shapes, &interner)
            .unwrap()
            .as_int(),
        Some(20)
    );
}

