// =========================================================================
// H3 — Error Type Correctness
// =========================================================================

// -------------------------------------------------------------------------
// H3-ET1: exception state — throw and check
// -------------------------------------------------------------------------
#[test]
fn test_exception_throw_and_check() {
    use crate::exceptions;
    // Clear any leftover state
    exceptions::clear_exception();
    assert!(!exceptions::is_exception());

    exceptions::throw(JsValue::int(42).raw_bits());
    assert!(exceptions::is_exception());

    let exc = exceptions::get_exception();
    assert_eq!(JsValue::from_raw_bits(exc).as_int(), Some(42));

    exceptions::clear_exception();
    assert!(!exceptions::is_exception());
}

// -------------------------------------------------------------------------
// H3-ET2: exception state — catch_begin/catch_end
// -------------------------------------------------------------------------
#[test]
fn test_exception_catch_begin_end() {
    use crate::exceptions;
    exceptions::clear_exception();

    // No exception pending: catch_begin returns false
    let pending = exceptions::catch_begin();
    assert!(!pending);

    // Throw an exception
    exceptions::throw(JsValue::int(1).raw_bits());

    // Pop catch frame
    exceptions::catch_end();
    // Exception is still pending (catch_end doesn't clear it)
    assert!(exceptions::is_exception());

    // Clean up
    exceptions::clear_exception();
}

// -------------------------------------------------------------------------
// H3-ET3: exception state — catch_begin with pending exception
// -------------------------------------------------------------------------
#[test]
fn test_exception_catch_begin_with_pending() {
    use crate::exceptions;
    exceptions::clear_exception();

    // Set a pending exception first
    exceptions::throw(JsValue::int(7).raw_bits());

    // catch_begin should return true because an exception is already pending
    let pending = exceptions::catch_begin();
    assert!(pending);

    exceptions::catch_end();
    exceptions::clear_exception();
}

// -------------------------------------------------------------------------
// H3-ET4: error_name returns correct names
// -------------------------------------------------------------------------
#[test]
fn test_error_name_mapping() {
    use crate::exceptions;
    assert_eq!(
        exceptions::error_name(exceptions::error_tag::ERROR),
        "Error"
    );
    assert_eq!(
        exceptions::error_name(exceptions::error_tag::TYPE_ERROR),
        "TypeError"
    );
    assert_eq!(
        exceptions::error_name(exceptions::error_tag::RANGE_ERROR),
        "RangeError"
    );
    assert_eq!(
        exceptions::error_name(exceptions::error_tag::REFERENCE_ERROR),
        "ReferenceError"
    );
    assert_eq!(
        exceptions::error_name(exceptions::error_tag::SYNTAX_ERROR),
        "SyntaxError"
    );
    assert_eq!(
        exceptions::error_name(exceptions::error_tag::URI_ERROR),
        "URIError"
    );
    assert_eq!(
        exceptions::error_name(exceptions::error_tag::EVAL_ERROR),
        "EvalError"
    );
    assert_eq!(exceptions::error_name(99), "Error");
}

// -------------------------------------------------------------------------
// H3-ET5: PropertyError types are correct
// -------------------------------------------------------------------------
#[test]
fn test_property_error_display() {
    assert_eq!(format!("{}", PropertyError::Frozen), "object is frozen");
    assert_eq!(format!("{}", PropertyError::Sealed), "object is sealed");
    assert_eq!(
        format!("{}", PropertyError::NotWritable),
        "property is not writable"
    );
    assert_eq!(
        format!("{}", PropertyError::NotConfigurable),
        "property is not configurable"
    );
    assert_eq!(
        format!("{}", PropertyError::NotExtensible),
        "object is not extensible"
    );
    assert_eq!(
        format!("{}", PropertyError::NoSetter),
        "Cannot set property which has only a getter"
    );
    assert_eq!(
        format!("{}", PropertyError::MixedDescriptor),
        "Invalid property descriptor. Cannot both specify accessors and a value or writable attribute"
    );
    assert_eq!(
        format!("{}", PropertyError::InvalidArrayLength),
        "Invalid array length"
    );
}

