// -------------------------------------------------------------------------
// H3-ET15: Define property with all defaults creates non-writable
// -------------------------------------------------------------------------
#[test]
fn test_define_property_defaults_all_false() {
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Omit all flags — spec says defaults to false for defineProperty
    let opts = property::DefinePropertyOptions {
        value: Some(JsValue::int(1)),
        ..Default::default()
    };
    obj.define_own_property("x", &opts, &mut shapes, &interner)
        .unwrap();

    let desc = obj
        .get_property_descriptor("x", &shapes, &interner)
        .unwrap();
    match desc {
        property::OwnPropertyDescriptor::Data {
            writable,
            enumerable,
            configurable,
            ..
        } => {
            assert!(!writable, "default writable should be false");
            assert!(!enumerable, "default enumerable should be false");
            assert!(!configurable, "default configurable should be false");
        }
        _ => panic!("expected data descriptor"),
    }
}

