fn test_array_define_property_invalid_length() {
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::array(ShapeTable::EMPTY_SHAPE, vec![]);

    // Negative length should be rejected
    let opts = property::DefinePropertyOptions {
        value: Some(JsValue::number(-1.0)),
        ..Default::default()
    };
    let result = obj.define_own_property("length", &opts, &mut shapes, &interner);
    assert_eq!(result, Err(PropertyError::InvalidArrayLength));
}

