// -------------------------------------------------------------------------
// H3-ET19: DefinePropertyOptions is_invalid_mixed detection
// -------------------------------------------------------------------------
#[test]
fn test_define_property_options_mixed_detection() {
    // value + getter = mixed
    let opts1 = property::DefinePropertyOptions {
        value: Some(JsValue::int(1)),
        getter: Some(JsValue::int(2)),
        ..Default::default()
    };
    assert!(opts1.is_invalid_mixed());

    // writable + setter = mixed
    let opts2 = property::DefinePropertyOptions {
        writable: Some(true),
        setter: Some(JsValue::int(3)),
        ..Default::default()
    };
    assert!(opts2.is_invalid_mixed());

    // value only = not mixed
    let opts3 = property::DefinePropertyOptions {
        value: Some(JsValue::int(1)),
        ..Default::default()
    };
    assert!(!opts3.is_invalid_mixed());

    // getter only = not mixed
    let opts4 = property::DefinePropertyOptions {
        getter: Some(JsValue::int(1)),
        ..Default::default()
    };
    assert!(!opts4.is_invalid_mixed());
}

// -------------------------------------------------------------------------
// H3-ET20: OwnPropertyDescriptor helper methods
// -------------------------------------------------------------------------
#[test]
fn test_own_property_descriptor_helpers() {
    let data_desc = property::OwnPropertyDescriptor::Data {
        value: JsValue::int(1),
        writable: true,
        enumerable: true,
        configurable: false,
    };
    assert!(data_desc.is_data());
    assert!(!data_desc.is_accessor());
    assert!(data_desc.is_enumerable());
    assert!(!data_desc.is_configurable());

    let acc_desc = property::OwnPropertyDescriptor::Accessor {
        getter: JsValue::undefined(),
        setter: JsValue::undefined(),
        enumerable: false,
        configurable: true,
    };
    assert!(!acc_desc.is_data());
    assert!(acc_desc.is_accessor());
    assert!(!acc_desc.is_enumerable());
    assert!(acc_desc.is_configurable());
}

// -------------------------------------------------------------------------
// H3-ET21: Non-configurable writable data property can still be written
// -------------------------------------------------------------------------
#[test]
fn test_non_configurable_writable_data_can_be_written() {
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    let opts = property::DefinePropertyOptions {
        value: Some(JsValue::int(1)),
        writable: Some(true),
        enumerable: Some(true),
        configurable: Some(false),
        ..Default::default()
    };
    obj.define_own_property("x", &opts, &mut shapes, &interner)
        .unwrap();

    // Can update value even though non-configurable (because writable)
    let opts2 = property::DefinePropertyOptions {
        value: Some(JsValue::int(99)),
        ..Default::default()
    };
    let result = obj.define_own_property("x", &opts2, &mut shapes, &interner);
    assert!(result.is_ok());

    let val = obj.get_slot_by_name("x", &shapes, &interner);
    assert_eq!(val.unwrap().as_int(), Some(99));
}

// -------------------------------------------------------------------------
// H3-ET22: DefinePropertyOptions is_accessor_descriptor/is_data_descriptor
// -------------------------------------------------------------------------
#[test]
fn test_define_property_options_descriptor_type() {
    let opts_data = property::DefinePropertyOptions {
        value: Some(JsValue::int(1)),
        writable: Some(true),
        ..Default::default()
    };
    assert!(opts_data.is_data_descriptor());
    assert!(!opts_data.is_accessor_descriptor());

    let opts_acc = property::DefinePropertyOptions {
        getter: Some(JsValue::int(1)),
        ..Default::default()
    };
    assert!(opts_acc.is_accessor_descriptor());
    assert!(!opts_acc.is_data_descriptor());

    let opts_empty = property::DefinePropertyOptions::default();
    assert!(!opts_empty.is_data_descriptor());
    assert!(!opts_empty.is_accessor_descriptor());
}

// -------------------------------------------------------------------------
// H3-ET23: Sealed object allows modifying existing writable property
// -------------------------------------------------------------------------
#[test]
fn test_sealed_object_allows_modify_existing_writable() {
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Add writable property, then seal
    let opts = property::DefinePropertyOptions {
        value: Some(JsValue::int(1)),
        writable: Some(true),
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("x", &opts, &mut shapes, &interner)
        .unwrap();

    obj.seal();
    // After sealing, set_slot_by_name should still work because the object
    // is sealed (not frozen) and the property exists
    let result = obj.set_slot_by_name("x", JsValue::int(42), &mut shapes, &interner);
    // sealed is not frozen — set_slot_by_name only checks is_frozen
    assert!(
        result,
        "sealed object should allow modifying existing writable property"
    );
}

// -------------------------------------------------------------------------
// H3-ET24: Array element descriptor returns correct attributes
// -------------------------------------------------------------------------
#[test]
fn test_array_element_descriptor_attributes() {
    let shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::array(ShapeTable::EMPTY_SHAPE, vec![]);

    // Add an element
    obj.set_element(0, JsValue::int(42));
    if let Some(crate::internal_data::InternalData::Array { length, .. }) = obj.internal_data_mut()
    {
        *length = 1;
    }

    // Per spec, array elements are writable, enumerable, configurable
    let desc = obj.get_property_descriptor("0", &shapes, &interner);
    assert!(desc.is_some());
    match desc.unwrap() {
        property::OwnPropertyDescriptor::Data {
            value,
            writable,
            enumerable,
            configurable,
        } => {
            assert_eq!(value.as_int(), Some(42));
            assert!(writable);
            assert!(enumerable);
            assert!(configurable);
        }
        _ => panic!("expected data descriptor for array element"),
    }
}

// -------------------------------------------------------------------------
// H3-ET25: Array length descriptor returns correct attributes
// -------------------------------------------------------------------------
#[test]
fn test_array_length_descriptor_attributes() {
    let shapes = ShapeTable::new();
    let interner = Interner::new();
    let obj = UnifiedObject::array(ShapeTable::EMPTY_SHAPE, vec![]);

    // Per spec, array length is writable, non-enumerable, non-configurable
    let desc = obj.get_property_descriptor("length", &shapes, &interner);
    assert!(desc.is_some());
    match desc.unwrap() {
        property::OwnPropertyDescriptor::Data {
            writable,
            enumerable,
            configurable,
            ..
        } => {
            assert!(writable, "array length should be writable");
            assert!(!enumerable, "array length should be non-enumerable");
            assert!(!configurable, "array length should be non-configurable");
        }
        _ => panic!("expected data descriptor for array length"),
    }
}

// -------------------------------------------------------------------------
// H3-ET26: Accessor enumerable flag is respected in enumeration
// -------------------------------------------------------------------------
#[test]
fn test_accessor_enumerable_flag_respected() {
    let mut shapes = ShapeTable::new();
    let interner = Interner::new();
    let mut obj = UnifiedObject::ordinary(ShapeTable::EMPTY_SHAPE);

    // Non-enumerable accessor
    let opts = property::DefinePropertyOptions {
        getter: Some(JsValue::int(1)),
        enumerable: Some(false),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("hidden", &opts, &mut shapes, &interner)
        .unwrap();

    // Enumerable data property
    let data_opts = property::DefinePropertyOptions {
        value: Some(JsValue::int(42)),
        writable: Some(true),
        enumerable: Some(true),
        configurable: Some(true),
        ..Default::default()
    };
    obj.define_own_property("visible", &data_opts, &mut shapes, &interner)
        .unwrap();

    let enum_keys = obj.enumerable_keys(&shapes, &interner);
    assert_eq!(enum_keys, vec!["visible"]);

    let all_keys = obj.own_keys(&shapes, &interner);
    assert!(all_keys.contains(&"hidden".to_string()));
    assert!(all_keys.contains(&"visible".to_string()));
}
