// -------------------------------------------------------------------------
// Array.prototype.copyWithin()
// -------------------------------------------------------------------------

#[test]
fn test_array_copywithin_basic() {
    // [1,2,3,4,5].copyWithin(0, 3) => [4,5,3,4,5]
    let obj = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::array(
            ShapeTable::EMPTY_SHAPE,
            vec![
                JsValue::int(1),
                JsValue::int(2),
                JsValue::int(3),
                JsValue::int(4),
                JsValue::int(5),
            ],
        ),
    );
    let args = [JsValue::int(0).raw_bits(), JsValue::int(3).raw_bits()];
    let result = dispatch_array_method(obj, "copyWithin", 2, args.as_ptr());
    // Should return the same array
    assert_eq!(result, obj);
    let uni = unsafe { deref_tagged::<UnifiedObject>(obj) }.unwrap();
    let elems = uni.array_elements_resolved();
    assert_eq!(elems[0].as_int(), Some(4));
    assert_eq!(elems[1].as_int(), Some(5));
    assert_eq!(elems[2].as_int(), Some(3));
    assert_eq!(elems[3].as_int(), Some(4));
    assert_eq!(elems[4].as_int(), Some(5));
    unsafe { free_tagged::<UnifiedObject>(obj) };
}

