// -------------------------------------------------------------------------
// Array.prototype.toSorted()
// -------------------------------------------------------------------------

#[test]
fn test_array_tosorted_basic() {
    let obj = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::array(
            ShapeTable::EMPTY_SHAPE,
            vec![JsValue::int(3), JsValue::int(1), JsValue::int(2)],
        ),
    );
    let result = dispatch_array_method(obj, "toSorted", 0, std::ptr::null());
    // Original should be unchanged
    let orig = unsafe { deref_tagged::<UnifiedObject>(obj) }.unwrap();
    let orig_elems = orig.array_elements_resolved();
    assert_eq!(orig_elems[0].as_int(), Some(3), "original array unchanged");
    assert_eq!(orig_elems[1].as_int(), Some(1), "original array unchanged");
    assert_eq!(orig_elems[2].as_int(), Some(2), "original array unchanged");

    // Result should be sorted
    let result_arr = unsafe { deref_tagged::<UnifiedObject>(result) }.unwrap();
    let sorted_elems = result_arr.array_elements_resolved();
    assert_eq!(sorted_elems[0].as_int(), Some(1));
    assert_eq!(sorted_elems[1].as_int(), Some(2));
    assert_eq!(sorted_elems[2].as_int(), Some(3));
    unsafe {
        free_tagged::<UnifiedObject>(result);
        free_tagged::<UnifiedObject>(obj);
    }
}

