#[test]
fn test_array_tospliced_remove_elements() {
    // [1,2,3,4,5].toSpliced(1, 2) => [1,4,5]
    let obj = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::array(
            ShapeTable::EMPTY_SHAPE,
            vec![
                JsValue::int(1),
                JsValue::int(2),
                JsValue::int(3),
                JsValue::int(4),
                JsValue::int(5),
            ],
        ),
    );
    let args = [JsValue::int(1).raw_bits(), JsValue::int(2).raw_bits()];
    let result = dispatch_array_method(obj, "toSpliced", 2, args.as_ptr());

    // Original should be unchanged
    let orig = unsafe { deref_tagged::<UnifiedObject>(obj) }.unwrap();
    assert_eq!(orig.array_len(), 5, "original unchanged");

    // Result should have elements removed
    let result_arr = unsafe { deref_tagged::<UnifiedObject>(result) }.unwrap();
    let elems = result_arr.array_elements_resolved();
    assert_eq!(elems.len(), 3);
    assert_eq!(elems[0].as_int(), Some(1));
    assert_eq!(elems[1].as_int(), Some(4));
    assert_eq!(elems[2].as_int(), Some(5));
    unsafe {
        free_tagged::<UnifiedObject>(result);
        free_tagged::<UnifiedObject>(obj);
    }
}

