#[test]
fn test_array_tosorted_does_not_modify_original() {
    let obj = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::array(
            ShapeTable::EMPTY_SHAPE,
            vec![JsValue::int(3), JsValue::int(1), JsValue::int(2)],
        ),
    );
    let _result = dispatch_array_method(obj, "toSorted", 0, std::ptr::null());
    let orig = unsafe { deref_tagged::<UnifiedObject>(obj) }.unwrap();
    let elems = orig.array_elements_resolved();
    assert_eq!(elems[0].as_int(), Some(3), "first element unchanged");
    assert_eq!(elems[1].as_int(), Some(1), "second element unchanged");
    assert_eq!(elems[2].as_int(), Some(2), "third element unchanged");
    unsafe { free_tagged::<UnifiedObject>(obj) };
}

