// -------------------------------------------------------------------------
// encodeURI / decodeURI / encodeURIComponent / decodeURIComponent
// -------------------------------------------------------------------------

#[test]
fn test_encode_uri_basic_ascii() {
    use crate::rt_api::es_encode_uri;
    assert_eq!(es_encode_uri("hello world").unwrap(), "hello%20world");
    assert_eq!(es_encode_uri("abc").unwrap(), "abc");
}

#[test]
fn test_encode_uri_preserves_reserved() {
    use crate::rt_api::es_encode_uri;
    // encodeURI preserves URI-reserved + # characters
    assert_eq!(
        es_encode_uri("http://example.com/path?q=1&r=2#frag").unwrap(),
        "http://example.com/path?q=1&r=2#frag"
    );
    assert_eq!(es_encode_uri(";,/?:@&=+$#").unwrap(), ";,/?:@&=+$#");
}

#[test]
fn test_encode_uri_preserves_unreserved() {
    use crate::rt_api::es_encode_uri;
    // Unreserved characters: A-Z a-z 0-9 - _ . ! ~ * ' ( )
    assert_eq!(
        es_encode_uri("ABCxyz019-_.!~*'()").unwrap(),
        "ABCxyz019-_.!~*'()"
    );
}

#[test]
fn test_encode_uri_encodes_special_chars() {
    use crate::rt_api::es_encode_uri;
    // Space, curly braces, pipe, etc. should be encoded
    assert_eq!(es_encode_uri(" ").unwrap(), "%20");
    assert_eq!(es_encode_uri("{").unwrap(), "%7B");
    assert_eq!(es_encode_uri("}").unwrap(), "%7D");
    assert_eq!(es_encode_uri("|").unwrap(), "%7C");
    assert_eq!(es_encode_uri("^").unwrap(), "%5E");
}

#[test]
fn test_encode_uri_component_basic_ascii() {
    use crate::rt_api::es_encode_uri_component;
    assert_eq!(
        es_encode_uri_component("hello world").unwrap(),
        "hello%20world"
    );
    assert_eq!(es_encode_uri_component("abc").unwrap(), "abc");
}

#[test]
fn test_encode_uri_component_encodes_reserved() {
    use crate::rt_api::es_encode_uri_component;
    // encodeURIComponent encodes reserved characters
    assert_eq!(es_encode_uri_component("/").unwrap(), "%2F");
    assert_eq!(es_encode_uri_component("?").unwrap(), "%3F");
    assert_eq!(es_encode_uri_component("#").unwrap(), "%23");
    assert_eq!(es_encode_uri_component("&").unwrap(), "%26");
    assert_eq!(es_encode_uri_component("=").unwrap(), "%3D");
    assert_eq!(es_encode_uri_component("+").unwrap(), "%2B");
    assert_eq!(es_encode_uri_component("@").unwrap(), "%40");
    assert_eq!(es_encode_uri_component(":").unwrap(), "%3A");
}

#[test]
fn test_encode_uri_component_preserves_unreserved() {
    use crate::rt_api::es_encode_uri_component;
    assert_eq!(
        es_encode_uri_component("ABCxyz019-_.!~*'()").unwrap(),
        "ABCxyz019-_.!~*'()"
    );
}

#[test]
fn test_encode_uri_vs_encode_uri_component() {
    use crate::rt_api::{es_encode_uri, es_encode_uri_component};
    // The key difference: reserved chars like / ? # & = are preserved by encodeURI
    // but encoded by encodeURIComponent
    let input = "http://example.com/path?q=hello world&r=2#frag";
    let uri_result = es_encode_uri(input).unwrap();
    let component_result = es_encode_uri_component(input).unwrap();

    // encodeURI preserves the URI structure
    assert!(uri_result.contains("http://"));
    assert!(uri_result.contains("?q="));
    assert!(uri_result.contains("&r="));
    assert!(uri_result.contains("#frag"));

    // encodeURIComponent encodes everything including structure
    assert!(component_result.contains("%3A%2F%2F"));
    assert!(component_result.contains("%3Fq%3D"));
    assert!(component_result.contains("%26r%3D"));
    assert!(component_result.contains("%23frag"));
}

#[test]
fn test_encode_uri_unicode() {
    use crate::rt_api::es_encode_uri;
    // Multi-byte UTF-8: e.g. Euro sign U+20AC = E2 82 AC in UTF-8
    assert_eq!(es_encode_uri("\u{20AC}").unwrap(), "%E2%82%AC");
    // CJK character U+4E16 (世) = E4 B8 96
    assert_eq!(es_encode_uri("世").unwrap(), "%E4%B8%96");
}

#[test]
fn test_encode_uri_component_unicode() {
    use crate::rt_api::es_encode_uri_component;
    assert_eq!(es_encode_uri_component("\u{20AC}").unwrap(), "%E2%82%AC");
    // 4-byte UTF-8: U+1F600 (grinning face emoji) = F0 9F 98 80
    assert_eq!(
        es_encode_uri_component("\u{1F600}").unwrap(),
        "%F0%9F%98%80"
    );
}

#[test]
fn test_decode_uri_basic() {
    use crate::rt_api::es_decode_uri;
    assert_eq!(es_decode_uri("hello%20world").unwrap(), "hello world");
    assert_eq!(es_decode_uri("abc").unwrap(), "abc");
}

#[test]
fn test_decode_uri_preserves_reserved() {
    use crate::rt_api::es_decode_uri;
    // decodeURI does NOT decode reserved characters
    assert_eq!(es_decode_uri("%23").unwrap(), "%23"); // #
    assert_eq!(es_decode_uri("%2F").unwrap(), "%2F"); // /
    assert_eq!(es_decode_uri("%3F").unwrap(), "%3F"); // ?
    assert_eq!(es_decode_uri("%3A").unwrap(), "%3A"); // :
    assert_eq!(es_decode_uri("%40").unwrap(), "%40"); // @
    assert_eq!(es_decode_uri("%26").unwrap(), "%26"); // &
    assert_eq!(es_decode_uri("%3D").unwrap(), "%3D"); // =
    assert_eq!(es_decode_uri("%2B").unwrap(), "%2B"); // +
    assert_eq!(es_decode_uri("%24").unwrap(), "%24"); // $
    assert_eq!(es_decode_uri("%2C").unwrap(), "%2C"); // ,
    assert_eq!(es_decode_uri("%3B").unwrap(), "%3B"); // ;
}

#[test]
fn test_decode_uri_component_basic() {
    use crate::rt_api::es_decode_uri_component;
    assert_eq!(
        es_decode_uri_component("hello%20world").unwrap(),
        "hello world"
    );
    assert_eq!(es_decode_uri_component("abc").unwrap(), "abc");
}

#[test]
fn test_decode_uri_component_decodes_reserved() {
    use crate::rt_api::es_decode_uri_component;
    // decodeURIComponent decodes ALL percent-encoded sequences
    assert_eq!(es_decode_uri_component("%23").unwrap(), "#");
    assert_eq!(es_decode_uri_component("%2F").unwrap(), "/");
    assert_eq!(es_decode_uri_component("%3F").unwrap(), "?");
    assert_eq!(es_decode_uri_component("%26").unwrap(), "&");
    assert_eq!(es_decode_uri_component("%3D").unwrap(), "=");
    assert_eq!(es_decode_uri_component("%40").unwrap(), "@");
}

