#[test]
fn test_bind_of_bind_length() {
    // bind(f, a).bind(null, b) => length should account for both partial args
    // f.length = 5, first bind has 2 partial args => bound1.length = 3
    // second bind has 1 partial arg => bound2.length = 2
    use crate::rt_api::{__esc_rt_get_prop, dispatch_function_bind};
    use shapes::ShapeTable;

    let func = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::function(
            ShapeTable::EMPTY_SHAPE,
            0,
            0,
            make_rt_string("g".to_string()),
            5,
            false,
        ),
    );

    let this_arg = JsValue::undefined().raw_bits();
    let partial1 = JsValue::int(1).raw_bits();
    let partial2 = JsValue::int(2).raw_bits();
    let args1: [u64; 3] = [this_arg, partial1, partial2];
    let bound1 = dispatch_function_bind(func, 3, args1.as_ptr());

    // Verify bound1 length = 5 - 2 = 3
    let length_key = make_rt_string("length".to_string());
    let bound1_length = __esc_rt_get_prop(bound1, length_key);
    assert_eq!(
        JsValue::from_raw_bits(bound1_length).as_number(),
        Some(3.0),
        "first bound length should be 3"
    );

    let partial3 = JsValue::int(3).raw_bits();
    let args2: [u64; 2] = [this_arg, partial3];
    let bound2 = dispatch_function_bind(bound1, 2, args2.as_ptr());

    let length_key2 = make_rt_string("length".to_string());
    let bound2_length = __esc_rt_get_prop(bound2, length_key2);
    assert_eq!(
        JsValue::from_raw_bits(bound2_length).as_number(),
        Some(2.0),
        "double-bound length should be max(0, 3 - 1) = 2"
    );
}

#[test]
fn test_bind_no_prototype_property() {
    // ES spec: bound functions should NOT have a prototype property
    use crate::rt_api::{__esc_rt_create_closure, __esc_rt_get_prop, dispatch_function_bind};

    let closure = __esc_rt_create_closure(0, 0, 0);
    let this_arg = JsValue::undefined().raw_bits();
    let args: [u64; 1] = [this_arg];
    let bound = dispatch_function_bind(closure, 1, args.as_ptr());

    let proto_key = make_rt_string("prototype".to_string());
    let proto_val = __esc_rt_get_prop(bound, proto_key);
    assert!(
        JsValue::from_raw_bits(proto_val).is_undefined(),
        "bound function should not have a prototype property"
    );
}
// =========================================================================
// Fix 3: defineProperty non-configurable accessor enforcement (ES spec 10.1.6.3)
// =========================================================================

#[test]
fn test_define_property_non_configurable_accessor_rejects_getter_change() {
    // Non-configurable accessor property should reject changes to getter
    use crate::internal_data::UnifiedObject;
    use crate::property::{DefinePropertyOptions, PropertyError};
    use interner::Interner;

    let mut obj = UnifiedObject::ordinary(shapes::ShapeId(0));
    let mut shapes = shapes::ShapeTable::new();
    let interner = Interner::new();

    let getter_val = JsValue::int(100); // Dummy getter value
    let setter_val = JsValue::int(200); // Dummy setter value

    // Define a non-configurable accessor property
    let opts = DefinePropertyOptions {
        value: None,
        writable: None,
        enumerable: Some(true),
        configurable: Some(false),
        getter: Some(getter_val),
        setter: Some(setter_val),
    };
    obj.define_own_property("x", &opts, &mut shapes, &interner)
        .unwrap();

    // Trying to change getter should fail
    let opts2 = DefinePropertyOptions {
        value: None,
        writable: None,
        enumerable: None,
        configurable: None,
        getter: Some(JsValue::int(999)), // Different getter
        setter: None,
    };
    let result = obj.define_own_property("x", &opts2, &mut shapes, &interner);
    assert_eq!(
        result,
        Err(PropertyError::NotConfigurable),
        "changing getter on non-configurable accessor should fail"
    );
}

