#[test]
fn test_get_own_property_descriptor_array_length() {
    // Array.length should be { writable: true, enumerable: false, configurable: false }
    use crate::internal_data::UnifiedObject;
    use crate::property::OwnPropertyDescriptor;

    let shapes = shapes::ShapeTable::new();
    let interner = Interner::new();

    let obj = UnifiedObject::array(
        shapes::ShapeId(0),
        vec![JsValue::int(10), JsValue::int(20), JsValue::int(30)],
    );

    let desc = obj.get_property_descriptor("length", &shapes, &interner);
    assert!(desc.is_some(), "array length descriptor should exist");
    match desc.unwrap() {
        OwnPropertyDescriptor::Data {
            value,
            writable,
            enumerable,
            configurable,
        } => {
            assert_eq!(value.as_number(), Some(3.0), "length should be 3");
            assert!(writable, "length should be writable");
            assert!(!enumerable, "length should not be enumerable");
            assert!(!configurable, "length should not be configurable");
        }
        OwnPropertyDescriptor::Accessor { .. } => {
            panic!("array length should be a data descriptor");
        }
    }
}

