// Fix 1: Generic this (array-like objects)
// -------------------------------------------------------------------------

/// Helper: create an array-like plain object with indexed properties and length.
///
/// Returns the NaN-boxed bits of an object like `{ 0: v0, 1: v1, ..., length: N }`.
fn create_array_like_object(values: &[JsValue]) -> u64 {
    let obj = crate::rt_api::__esc_rt_create_object();
    for (i, val) in values.iter().enumerate() {
        let key = make_rt_string(i.to_string());
        crate::rt_api::__esc_rt_set_prop(obj, key, val.raw_bits());
    }
    let len_key = make_rt_string("length".to_string());
    crate::rt_api::__esc_rt_set_prop(obj, len_key, JsValue::int(values.len() as i32).raw_bits());
    obj
}

#[test]
fn test_array_generic_this_indexof() {
    let obj = create_array_like_object(&[JsValue::int(10), JsValue::int(20), JsValue::int(30)]);
    let args = [JsValue::int(20).raw_bits()];
    let result = dispatch_array_method(obj, "indexOf", 1, args.as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(result).as_int(),
        Some(1),
        "indexOf on array-like should find element"
    );
}

#[test]
fn test_array_generic_this_indexof_not_found() {
    let obj = create_array_like_object(&[JsValue::int(10), JsValue::int(20)]);
    let args = [JsValue::int(99).raw_bits()];
    let result = dispatch_array_method(obj, "indexOf", 1, args.as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(result).as_int(),
        Some(-1),
        "indexOf on array-like should return -1 when not found"
    );
}

