#[test]
fn test_array_sort_stability() {
    let arr = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::array(
            ShapeTable::EMPTY_SHAPE,
            vec![
                JsValue::int(3),
                JsValue::int(1),
                JsValue::int(2),
                JsValue::int(1),
            ],
        ),
    );
    let result = dispatch_array_method(arr, "sort", 0, std::ptr::null());
    assert_eq!(result, arr, "sort should return the same array");
    let idx0 = crate::rt_api::__esc_rt_get_prop(arr, JsValue::int(0).raw_bits());
    let idx1 = crate::rt_api::__esc_rt_get_prop(arr, JsValue::int(1).raw_bits());
    let idx2 = crate::rt_api::__esc_rt_get_prop(arr, JsValue::int(2).raw_bits());
    let idx3 = crate::rt_api::__esc_rt_get_prop(arr, JsValue::int(3).raw_bits());
    assert_eq!(JsValue::from_raw_bits(idx0).as_int(), Some(1));
    assert_eq!(JsValue::from_raw_bits(idx1).as_int(), Some(1));
    assert_eq!(JsValue::from_raw_bits(idx2).as_int(), Some(2));
    assert_eq!(JsValue::from_raw_bits(idx3).as_int(), Some(3));
    unsafe { free_tagged::<UnifiedObject>(arr) };
}

