// -------------------------------------------------------------------------
// is_array_prototype_method helper
// -------------------------------------------------------------------------

#[test]
fn test_is_array_prototype_method_known() {
    assert!(is_array_prototype_method("forEach"));
    assert!(is_array_prototype_method("map"));
    assert!(is_array_prototype_method("filter"));
    assert!(is_array_prototype_method("reduce"));
    assert!(is_array_prototype_method("reduceRight"));
    assert!(is_array_prototype_method("some"));
    assert!(is_array_prototype_method("every"));
    assert!(is_array_prototype_method("find"));
    assert!(is_array_prototype_method("findIndex"));
    assert!(is_array_prototype_method("findLast"));
    assert!(is_array_prototype_method("findLastIndex"));
    assert!(is_array_prototype_method("indexOf"));
    assert!(is_array_prototype_method("lastIndexOf"));
    assert!(is_array_prototype_method("includes"));
    assert!(is_array_prototype_method("join"));
    assert!(is_array_prototype_method("flat"));
    assert!(is_array_prototype_method("flatMap"));
    assert!(is_array_prototype_method("slice"));
    assert!(is_array_prototype_method("concat"));
    assert!(is_array_prototype_method("at"));
    assert!(is_array_prototype_method("sort"));
    assert!(is_array_prototype_method("reverse"));
    assert!(is_array_prototype_method("fill"));
    assert!(is_array_prototype_method("toSorted"));
    assert!(is_array_prototype_method("toReversed"));
    assert!(is_array_prototype_method("toSpliced"));
    assert!(is_array_prototype_method("copyWithin"));
}

#[test]
fn test_is_array_prototype_method_unknown() {
    assert!(!is_array_prototype_method("toString"));
    assert!(!is_array_prototype_method("valueOf"));
    assert!(!is_array_prototype_method("hasOwnProperty"));
    assert!(!is_array_prototype_method("constructor"));
    assert!(!is_array_prototype_method("foo"));
}

