// -------------------------------------------------------------------------
// Gap B fix: array get/set via string index keys ("0", "1", etc.)
// -------------------------------------------------------------------------

#[test]
fn test_array_get_prop_string_index() {
    let arr = crate::rt_api::__esc_rt_create_array(0);
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(10).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(20).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(30).raw_bits());

    // Access via string key "0"
    let key0 = make_string_value("0");
    let val0 = crate::rt_api::__esc_rt_get_prop(arr, key0);
    assert_eq!(
        JsValue::from_raw_bits(val0).as_int(),
        Some(10),
        "get_prop(array, \"0\") should return first element"
    );

    // Access via string key "1"
    let key1 = make_string_value("1");
    let val1 = crate::rt_api::__esc_rt_get_prop(arr, key1);
    assert_eq!(
        JsValue::from_raw_bits(val1).as_int(),
        Some(20),
        "get_prop(array, \"1\") should return second element"
    );

    // Access via string key "2"
    let key2 = make_string_value("2");
    let val2 = crate::rt_api::__esc_rt_get_prop(arr, key2);
    assert_eq!(
        JsValue::from_raw_bits(val2).as_int(),
        Some(30),
        "get_prop(array, \"2\") should return third element"
    );
}

#[test]
fn test_array_get_prop_string_index_out_of_bounds() {
    let arr = crate::rt_api::__esc_rt_create_array(0);
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(42).raw_bits());

    // Access beyond array length
    let key5 = make_string_value("5");
    let val = crate::rt_api::__esc_rt_get_prop(arr, key5);
    assert!(
        JsValue::from_raw_bits(val).is_undefined(),
        "get_prop(array, \"5\") on 1-element array should return undefined"
    );

    // Access with very large index
    let key_large = make_string_value("999999");
    let val_large = crate::rt_api::__esc_rt_get_prop(arr, key_large);
    assert!(
        JsValue::from_raw_bits(val_large).is_undefined(),
        "get_prop(array, \"999999\") should return undefined"
    );
}

#[test]
fn test_array_set_prop_string_index() {
    let arr = crate::rt_api::__esc_rt_create_array(0);
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(10).raw_bits());
    crate::rt_api::__esc_rt_array_push(arr, JsValue::int(20).raw_bits());

    // Overwrite index 0 via string key
    let key0 = make_string_value("0");
    crate::rt_api::__esc_rt_set_prop(arr, key0, JsValue::int(99).raw_bits());
    let val0 = crate::rt_api::__esc_rt_get_prop(arr, key0);
    assert_eq!(
        JsValue::from_raw_bits(val0).as_int(),
        Some(99),
        "set_prop(array, \"0\", 99) should update first element"
    );

    // Set beyond current length via string key
    let key5 = make_string_value("5");
    crate::rt_api::__esc_rt_set_prop(arr, key5, JsValue::int(50).raw_bits());
    let val5 = crate::rt_api::__esc_rt_get_prop(arr, key5);
    assert_eq!(
        JsValue::from_raw_bits(val5).as_int(),
        Some(50),
        "set_prop(array, \"5\", 50) should set element at index 5"
    );

    // Verify length was updated
    let key_len = make_string_value("length");
    let len = crate::rt_api::__esc_rt_get_prop(arr, key_len);
    assert_eq!(
        JsValue::from_raw_bits(len).as_number(),
        Some(6.0),
        "array length should be 6 after setting index 5"
    );
}

