#[test]
fn test_builtin_object_all_static_methods_are_native_func() {
    use crate::tagged_obj::deref_tagged;

    let methods = [
        "keys",
        "values",
        "entries",
        "assign",
        "create",
        "defineProperty",
        "defineProperties",
        "freeze",
        "seal",
        "isFrozen",
        "isSealed",
        "isExtensible",
        "preventExtensions",
        "getOwnPropertyDescriptor",
        "getOwnPropertyDescriptors",
        "getOwnPropertyNames",
        "getOwnPropertySymbols",
        "getPrototypeOf",
        "setPrototypeOf",
        "hasOwn",
        "fromEntries",
        "is",
    ];
    for method in &methods {
        let obj_str = make_string_value("Object");
        let method_key = make_string_value(method);
        let result = crate::rt_api::__esc_rt_get_prop(obj_str, method_key);
        let v = JsValue::from_raw_bits(result);
        assert!(v.is_object(), "Object.{method} should be an object");
        let uni = unsafe { deref_tagged::<UnifiedObject>(result) };
        assert!(
            uni.is_some(),
            "Object.{method} should deref to UnifiedObject"
        );
        assert_eq!(
            uni.expect("deref").kind,
            crate::internal_data::InternalKind::NativeFunc,
            "Object.{method} should be a NativeFunc"
        );
    }
}

