#[test]
fn test_get_global_array_returns_callable() {
    use crate::internal_data::InternalKind;
    use crate::rt_api::get_global_object;
    use crate::tagged_obj::{ObjTag, deref_tagged, read_obj_tag};

    let bits = get_global_object("Array");
    assert_ne!(bits, JsValue::undefined().raw_bits());

    // Should be a Unified object
    assert_eq!(read_obj_tag(bits), Some(ObjTag::Unified as u8));

    // Should be NativeFunc (callable)
    let obj = unsafe { deref_tagged::<UnifiedObject>(bits) }.unwrap();
    assert_eq!(obj.kind, InternalKind::NativeFunc);
    assert!(obj.flags.is_callable());
}

#[test]
fn test_get_global_identity_preserved() {
    use crate::rt_api::get_global_object;

    // Array === Array must be true (same bits)
    let a1 = get_global_object("Array");
    let a2 = get_global_object("Array");
    assert_eq!(a1, a2, "Array identity must be preserved across calls");

    // Object === Object
    let o1 = get_global_object("Object");
    let o2 = get_global_object("Object");
    assert_eq!(o1, o2, "Object identity must be preserved across calls");

    // Array !== Object
    assert_ne!(a1, o1, "Array and Object must be different objects");
}

