#[test]
fn test_namespace_objects_inherit_object_prototype_user_properties() {
    // Namespace objects (Math, JSON, Reflect) must have [[Prototype]] =
    // %Object.prototype% so user assignments on Object.prototype are visible
    // through them (ES2024 §10.1.8 OrdinaryGet; §8.10.5 ToPropertyDescriptor).
    use crate::rt_api::{__esc_rt_get_prop, get_global_object};

    let math = get_global_object("Math");
    assert_ne!(math, JsValue::undefined().raw_bits());

    // Assign a user property on Object.prototype, then read it through Math.
    let object_ctor = get_global_object("Object");
    let proto_key = make_string_value("prototype");
    let object_prototype = crate::rt_api::__esc_rt_get_prop(object_ctor, proto_key);
    let marker_key = make_string_value("__esc_ns_marker__");
    crate::rt_api::__esc_rt_set_prop(object_prototype, marker_key, JsValue::int(99).raw_bits());

    let read_back = __esc_rt_get_prop(math, marker_key);
    assert_eq!(
        JsValue::from_raw_bits(read_back).as_int(),
        Some(99),
        "Math must inherit user properties from Object.prototype"
    );

    // Cleanup: remove the marker to not pollute other tests.
    crate::rt_api::__esc_rt_delete_prop(object_prototype, marker_key);
}

#[test]
fn test_get_global_constructor_has_name_and_length() {
    use crate::rt_api::{OBJECT_PROPS, get_global_object};

    let bits = get_global_object("Map");
    assert_ne!(bits, JsValue::undefined().raw_bits());

    OBJECT_PROPS.with(|props| {
        let props = props.borrow();
        let map = props
            .get(&bits)
            .expect("Map should have OBJECT_PROPS entry");

        let name_bits = map.get("name").expect("Map should have .name");
        let name_val = JsValue::from_raw_bits(*name_bits);
        assert!(name_val.is_string());
        assert_eq!(crate::string_ops::get_string_data(name_val), "Map");

        let length_bits = map.get("length").expect("Map should have .length");
        let length_val = JsValue::from_raw_bits(*length_bits);
        assert_eq!(length_val.as_number(), Some(0.0));
    });
}

