#[test]
fn test_get_global_all_constructors_are_callable() {
    use crate::internal_data::{InternalData, InternalKind};
    use crate::rt_api::get_global_object;
    use crate::tagged_obj::deref_tagged;

    let constructors = [
        "Array",
        "Object",
        "String",
        "Number",
        "Boolean",
        "Function",
        "RegExp",
        "Date",
        "Promise",
        "Error",
        "TypeError",
        "RangeError",
        "ReferenceError",
        "SyntaxError",
        "URIError",
        "EvalError",
        "Symbol",
        "Proxy",
        "Map",
        "Set",
        "WeakMap",
        "WeakSet",
        "WeakRef",
    ];
    for name in &constructors {
        let bits = get_global_object(name);
        assert_ne!(
            bits,
            JsValue::undefined().raw_bits(),
            "{name} should not be undefined"
        );

        let obj = unsafe { deref_tagged::<UnifiedObject>(bits) }.unwrap();
        assert_eq!(
            obj.kind,
            InternalKind::NativeFunc,
            "{name} should be NativeFunc"
        );
        assert!(obj.flags.is_callable(), "{name} should be callable");

        // Verify the trampoline function pointer is set
        if let Some(InternalData::NativeFunc { func, .. }) = obj.internal_data() {
            assert!(*func as usize != 0, "{name} trampoline should not be null");
        } else {
            panic!("{name} should have NativeFunc internal data");
        }
    }
}

