#[test]
fn test_array_prototype_has_all_instance_methods() {
    use crate::internal_data::InternalKind;
    use crate::tagged_obj::deref_tagged;

    let methods = [
        "concat",
        "copyWithin",
        "entries",
        "every",
        "fill",
        "filter",
        "find",
        "findIndex",
        "findLast",
        "findLastIndex",
        "flat",
        "flatMap",
        "forEach",
        "includes",
        "indexOf",
        "join",
        "keys",
        "lastIndexOf",
        "map",
        "pop",
        "push",
        "reduce",
        "reduceRight",
        "reverse",
        "shift",
        "slice",
        "some",
        "sort",
        "splice",
        "toReversed",
        "toSorted",
        "toSpliced",
        "unshift",
        "values",
        "at",
        "toString",
    ];

    let arr_str = make_string_value("Array");
    let proto_key = make_string_value("prototype");
    let proto = crate::rt_api::__esc_rt_get_prop(arr_str, proto_key);
    assert!(JsValue::from_raw_bits(proto).is_object());

    for method in &methods {
        let method_key = make_string_value(method);
        let result = crate::rt_api::__esc_rt_get_prop(proto, method_key);
        let v = JsValue::from_raw_bits(result);
        assert!(
            v.is_object(),
            "Array.prototype.{method} should be an object"
        );
        let uni = unsafe { deref_tagged::<UnifiedObject>(result) };
        assert!(
            uni.is_some(),
            "Array.prototype.{method} should deref to UnifiedObject"
        );
        assert_eq!(
            uni.expect("deref").kind,
            InternalKind::NativeFunc,
            "Array.prototype.{method} should be a NativeFunc"
        );
    }
}

