// =========================================================================
// NativeFunc .call() / .apply() / .bind() / .toString() tests (G4)
// =========================================================================

/// A native function that returns the current `this` value.
/// Used by tests to verify that `.call()` and `.apply()` set `this` correctly.
fn native_return_current_this(_ctx: u64) -> u64 {
    crate::rt_api::CURRENT_THIS.with(|cell| {
        let v = cell.get();
        if v == 0 {
            JsValue::undefined().raw_bits()
        } else {
            v
        }
    })
}

/// A native function that returns the sum of its arguments (as integers).
/// Used by tests to verify that arguments are passed through `.call()`/`.apply()`.
fn native_sum_args(_ctx: u64) -> u64 {
    let argc = crate::rt_api::CURRENT_ARGC.with(|cell| cell.get());
    let argv = crate::rt_api::CURRENT_ARGV.with(|cell| cell.get());
    let args = crate::rt_api::read_argv(argc, argv);
    let mut sum = 0i32;
    for arg in &args {
        if let Some(n) = arg.as_int() {
            sum += n;
        } else if let Some(n) = arg.as_number() {
            sum += n as i32;
        }
    }
    JsValue::int(sum).raw_bits()
}

/// A native function that returns its argument count.
/// Used by tests to verify that `.apply()` and `.bind()` pass the correct
/// number of arguments.
fn native_return_argc(_ctx: u64) -> u64 {
    let argc = crate::rt_api::CURRENT_ARGC.with(|cell| cell.get());
    JsValue::int(argc as i32).raw_bits()
}

