#[test]
fn test_native_func_bind_with_partial_args() {
    crate::exceptions::clear_exception();
    use crate::internal_data::UnifiedObject;
    use crate::tagged_obj::{ObjTag, TaggedObj};

    // Create a NativeFunc that sums its arguments
    let nf = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::native_func(native_sum_args, 0),
    );

    // Bind with this = undefined, partial args = [100, 200]
    let key_bind = make_string_value("bind");
    let bind_args: [u64; 3] = [
        JsValue::undefined().raw_bits(),
        JsValue::int(100).raw_bits(),
        JsValue::int(200).raw_bits(),
    ];
    let bound = unsafe { crate::rt_api::__esc_rt_call_method(nf, key_bind, 3, bind_args.as_ptr()) };

    // Call the bound function with additional arg 50 — should get 100 + 200 + 50 = 350.
    // __esc_rt_call_indirect sets CURRENT_ARGC/ARGV from its argc/argv params before
    // invoking the NativeFunc trampoline. The trampoline then reads those to get call-time args.
    let call_args: [u64; 1] = [JsValue::int(50).raw_bits()];
    let result = unsafe { crate::rt_api::__esc_rt_call_indirect(bound, 1, call_args.as_ptr()) };
    assert_eq!(
        JsValue::from_raw_bits(result).as_int(),
        Some(350),
        "bound NativeFunc with partial args [100, 200] + call-time arg [50] should sum to 350"
    );
}

