#[test]
fn test_set_slot_by_name_with_flags_non_enumerable() {
    // Direct test of the new set_slot_by_name_with_flags method
    use crate::internal_data::UnifiedObject;

    let mut shapes = shapes::ShapeTable::new();
    let interner = interner::Interner::new();

    let mut obj = UnifiedObject::ordinary(shapes::ShapeTable::EMPTY_SHAPE);
    obj.set_slot_by_name_with_flags(
        "foo",
        JsValue::int(42),
        true,  // writable
        false, // enumerable
        true,  // configurable
        &mut shapes,
        &interner,
    );

    // Verify the property exists and has correct flags
    let desc = obj.get_property_descriptor("foo", &shapes, &interner);
    assert!(desc.is_some(), "property foo should exist");
    match desc.unwrap() {
        crate::property::OwnPropertyDescriptor::Data {
            value,
            writable,
            enumerable,
            configurable,
        } => {
            assert_eq!(value, JsValue::int(42), "value should be 42");
            assert!(writable, "writable should be true");
            assert!(!enumerable, "enumerable should be false");
            assert!(configurable, "configurable should be true");
        }
        _ => panic!("expected Data descriptor"),
    }

    // Verify it doesn't appear in enumerable_keys
    let keys = obj.enumerable_keys(&shapes, &interner);
    assert!(
        keys.is_empty(),
        "non-enumerable property should not appear in enumerable_keys"
    );
}

#[test]
fn test_set_slot_by_name_with_flags_mixed_enumerability() {
    // Test that we can mix enumerable and non-enumerable properties
    use crate::internal_data::UnifiedObject;

    let mut shapes = shapes::ShapeTable::new();
    let interner = interner::Interner::new();

    let mut obj = UnifiedObject::ordinary(shapes::ShapeTable::EMPTY_SHAPE);

    // Add an enumerable property
    obj.set_slot_by_name("visible", JsValue::int(1), &mut shapes, &interner);

    // Add a non-enumerable property
    obj.set_slot_by_name_with_flags(
        "hidden",
        JsValue::int(2),
        true,  // writable
        false, // enumerable
        true,  // configurable
        &mut shapes,
        &interner,
    );

    // Only "visible" should appear in enumerable_keys
    let keys = obj.enumerable_keys(&shapes, &interner);
    assert_eq!(keys.len(), 1, "should have 1 enumerable key");
    assert_eq!(keys[0], "visible", "only 'visible' should be enumerable");

    // But own_keys should return both
    let all_keys = obj.own_keys(&shapes, &interner);
    assert_eq!(all_keys.len(), 2, "should have 2 total keys");
    assert!(all_keys.contains(&"visible".to_string()));
    assert!(all_keys.contains(&"hidden".to_string()));
}

