// =========================================================================
// P2: Function property descriptor flags
// =========================================================================

/// Helper: call Object.getOwnPropertyDescriptor(obj, prop) via dispatch and
/// return the descriptor object bits, or None if undefined.
fn call_get_own_property_descriptor(obj: u64, prop_name: &str) -> Option<u64> {
    let prop_key = make_string_value(prop_name);
    let argv: [u64; 2] = [obj, prop_key];
    let result =
        crate::rt_api::dispatch_object_static_method("getOwnPropertyDescriptor", 2, argv.as_ptr());
    let bits = result?;
    let v = JsValue::from_raw_bits(bits);
    if v.is_undefined() { None } else { Some(bits) }
}

/// Helper: read a boolean field from a descriptor object.
fn read_desc_bool(desc: u64, field: &str) -> Option<bool> {
    let key = make_string_value(field);
    let val = crate::rt_api::__esc_rt_get_prop(desc, key);
    JsValue::from_raw_bits(val).as_bool()
}

/// Helper: read the "value" field from a descriptor object.
fn read_desc_value(desc: u64) -> u64 {
    let key = make_string_value("value");
    crate::rt_api::__esc_rt_get_prop(desc, key)
}

/// Helper: call Object.getOwnPropertyNames(obj) and return the names as strings.
fn call_get_own_property_names(obj: u64) -> Vec<String> {
    let argv: [u64; 1] = [obj];
    let result =
        crate::rt_api::dispatch_object_static_method("getOwnPropertyNames", 1, argv.as_ptr());
    let Some(arr_bits) = result else {
        return Vec::new();
    };
    let arr_val = JsValue::from_raw_bits(arr_bits);
    if !arr_val.is_object() {
        return Vec::new();
    }
    let tag = crate::tagged_obj::read_obj_tag(arr_bits);
    if tag != Some(crate::tagged_obj::ObjTag::Unified as u8) {
        return Vec::new();
    }
    let uni = unsafe { crate::tagged_obj::deref_tagged::<UnifiedObject>(arr_bits) };
    let Some(u) = uni else {
        return Vec::new();
    };
    u.array_elements()
        .iter()
        .map(|v| crate::string_ops::get_string_data(*v))
        .collect()
}

#[test]
fn test_function_name_descriptor_flags() {
    // Object.getOwnPropertyDescriptor(func, "name") should return:
    //   {value: <name>, writable: false, enumerable: false, configurable: true}
    crate::exceptions::clear_exception();

    let name_bits = make_string_value("myFunc");
    let func = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::function(ShapeTable::EMPTY_SHAPE, 0, 0, name_bits, 2, false),
    );
    // Set name via OBJECT_PROPS (like desugar does)
    let name_key = make_string_value("name");
    crate::rt_api::__esc_rt_set_prop(func, name_key, name_bits);

    let desc = call_get_own_property_descriptor(func, "name");
    assert!(desc.is_some(), "name descriptor should exist");
    let d = desc.unwrap();

    assert_eq!(
        read_desc_bool(d, "writable"),
        Some(false),
        "name.writable should be false"
    );
    assert_eq!(
        read_desc_bool(d, "enumerable"),
        Some(false),
        "name.enumerable should be false"
    );
    assert_eq!(
        read_desc_bool(d, "configurable"),
        Some(true),
        "name.configurable should be true"
    );

    // Check the value is the function name
    let val = read_desc_value(d);
    let val_str = crate::string_ops::get_string_data(JsValue::from_raw_bits(val));
    assert_eq!(val_str, "myFunc", "name value should be 'myFunc'");
}

#[test]
fn test_function_length_descriptor_flags() {
    // Object.getOwnPropertyDescriptor(func, "length") should return:
    //   {value: <length>, writable: false, enumerable: false, configurable: true}
    crate::exceptions::clear_exception();

    let name_bits = make_string_value("testFn");
    let func = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::function(ShapeTable::EMPTY_SHAPE, 0, 0, name_bits, 3, false),
    );
    // Set length via OBJECT_PROPS (like desugar does)
    let length_key = make_string_value("length");
    crate::rt_api::__esc_rt_set_prop(func, length_key, JsValue::int(3).raw_bits());

    let desc = call_get_own_property_descriptor(func, "length");
    assert!(desc.is_some(), "length descriptor should exist");
    let d = desc.unwrap();

    assert_eq!(
        read_desc_bool(d, "writable"),
        Some(false),
        "length.writable should be false"
    );
    assert_eq!(
        read_desc_bool(d, "enumerable"),
        Some(false),
        "length.enumerable should be false"
    );
    assert_eq!(
        read_desc_bool(d, "configurable"),
        Some(true),
        "length.configurable should be true"
    );

    // Check the value is the param count (may be int or number encoding)
    let val = read_desc_value(d);
    let v = JsValue::from_raw_bits(val);
    let num = v.as_number().or_else(|| v.as_int().map(|i| i as f64));
    assert!(
        num.is_some_and(|n| (n - 3.0).abs() < f64::EPSILON),
        "length value should be 3, got int={:?} num={:?}",
        v.as_int(),
        v.as_number()
    );
}

