#[test]
fn test_native_func_default_name_and_length() {
    // NativeFunc without explicit name/length in OBJECT_PROPS should still
    // return descriptors with default values (empty string, 0)
    crate::exceptions::clear_exception();

    fn dummy_native(_ctx: u64) -> u64 {
        JsValue::undefined().raw_bits()
    }
    let nf = TaggedObj::boxed(ObjTag::Unified, UnifiedObject::native_func(dummy_native, 0));

    // name should default to empty string
    let desc = call_get_own_property_descriptor(nf, "name");
    assert!(
        desc.is_some(),
        "NativeFunc should have name even without OBJECT_PROPS"
    );
    let d = desc.unwrap();
    let val = read_desc_value(d);
    let val_str = crate::string_ops::get_string_data(JsValue::from_raw_bits(val));
    assert_eq!(
        val_str, "",
        "default NativeFunc name should be empty string"
    );

    // length should default to 0
    let desc2 = call_get_own_property_descriptor(nf, "length");
    assert!(
        desc2.is_some(),
        "NativeFunc should have length even without OBJECT_PROPS"
    );
    let d2 = desc2.unwrap();
    let val2 = read_desc_value(d2);
    let v2 = JsValue::from_raw_bits(val2);
    assert!(
        v2.as_number().is_some_and(|n| n == 0.0),
        "default NativeFunc length should be 0"
    );
}

#[test]
fn test_function_property_is_not_enumerable() {
    // name, length, prototype should not appear in for-in / Object.keys
    crate::exceptions::clear_exception();

    let name_bits = make_string_value("myFunc");
    let func = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::function(ShapeTable::EMPTY_SHAPE, 0, 0, name_bits, 2, false),
    );
    let name_key = make_string_value("name");
    crate::rt_api::__esc_rt_set_prop(func, name_key, name_bits);
    let length_key = make_string_value("length");
    crate::rt_api::__esc_rt_set_prop(func, length_key, JsValue::int(2).raw_bits());
    let proto_obj = crate::rt_api::__esc_rt_create_object();
    let proto_key = make_string_value("prototype");
    crate::rt_api::__esc_rt_set_prop(func, proto_key, proto_obj);

    // Object.keys should return empty for function with only name/length/prototype
    let keys_result = crate::rt_api::__esc_rt_object_keys(func);
    let keys_tag = crate::tagged_obj::read_obj_tag(keys_result);
    assert_eq!(keys_tag, Some(crate::tagged_obj::ObjTag::Unified as u8));
    let keys_uni = unsafe { crate::tagged_obj::deref_tagged::<UnifiedObject>(keys_result) };
    let keys_arr = keys_uni.unwrap();
    assert_eq!(
        keys_arr.array_elements().len(),
        0,
        "Object.keys(func) should be empty (name/length/prototype are not enumerable)"
    );
}

#[test]
fn test_function_get_own_property_names_includes_function_props() {
    // Object.getOwnPropertyNames(func) should include name, length, and prototype
    crate::exceptions::clear_exception();

    let name_bits = make_string_value("myFunc");
    let func = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::function(ShapeTable::EMPTY_SHAPE, 0, 0, name_bits, 2, false),
    );
    let name_key = make_string_value("name");
    crate::rt_api::__esc_rt_set_prop(func, name_key, name_bits);
    let length_key = make_string_value("length");
    crate::rt_api::__esc_rt_set_prop(func, length_key, JsValue::int(2).raw_bits());
    let proto_obj = crate::rt_api::__esc_rt_create_object();
    let proto_key = make_string_value("prototype");
    crate::rt_api::__esc_rt_set_prop(func, proto_key, proto_obj);

    let names = call_get_own_property_names(func);
    assert!(
        names.contains(&"name".to_string()),
        "getOwnPropertyNames should include 'name', got: {:?}",
        names
    );
    assert!(
        names.contains(&"length".to_string()),
        "getOwnPropertyNames should include 'length', got: {:?}",
        names
    );
    assert!(
        names.contains(&"prototype".to_string()),
        "getOwnPropertyNames should include 'prototype', got: {:?}",
        names
    );
}

#[test]
fn test_function_get_own_property_names_without_prototype() {
    // Functions without prototype should still have name and length
    crate::exceptions::clear_exception();

    let name_bits = make_string_value("arrow");
    let func = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::function(ShapeTable::EMPTY_SHAPE, 0, 0, name_bits, 1, true),
    );
    let name_key = make_string_value("name");
    crate::rt_api::__esc_rt_set_prop(func, name_key, name_bits);
    let length_key = make_string_value("length");
    crate::rt_api::__esc_rt_set_prop(func, length_key, JsValue::int(1).raw_bits());

    let names = call_get_own_property_names(func);
    assert!(
        names.contains(&"name".to_string()),
        "arrow getOwnPropertyNames should include 'name'"
    );
    assert!(
        names.contains(&"length".to_string()),
        "arrow getOwnPropertyNames should include 'length'"
    );
    assert!(
        !names.contains(&"prototype".to_string()),
        "arrow getOwnPropertyNames should NOT include 'prototype'"
    );
}

#[test]
fn test_function_has_own_name_and_length() {
    // func.hasOwnProperty("name") and func.hasOwnProperty("length") should be true
    crate::exceptions::clear_exception();

    let name_bits = make_string_value("fn");
    let func = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::function(ShapeTable::EMPTY_SHAPE, 0, 0, name_bits, 0, false),
    );

    // Object.hasOwn(func, "name")
    let name_key = make_string_value("name");
    let argv: [u64; 2] = [func, name_key];
    let result = crate::rt_api::dispatch_object_static_method("hasOwn", 2, argv.as_ptr());
    assert_eq!(
        result.map(|r| JsValue::from_raw_bits(r).as_bool()),
        Some(Some(true)),
        "Object.hasOwn(func, 'name') should be true"
    );

    // Object.hasOwn(func, "length")
    let length_key = make_string_value("length");
    let argv2: [u64; 2] = [func, length_key];
    let result2 = crate::rt_api::dispatch_object_static_method("hasOwn", 2, argv2.as_ptr());
    assert_eq!(
        result2.map(|r| JsValue::from_raw_bits(r).as_bool()),
        Some(Some(true)),
        "Object.hasOwn(func, 'length') should be true"
    );
}

#[test]
fn test_function_name_descriptor_fallback_to_internal_data() {
    // When name is NOT set in OBJECT_PROPS, the descriptor should fall back
    // to the InternalData::Function name field
    crate::exceptions::clear_exception();

    let name_bits = make_string_value("fallbackName");
    let func = TaggedObj::boxed(
        ObjTag::Unified,
        UnifiedObject::function(ShapeTable::EMPTY_SHAPE, 0, 0, name_bits, 4, false),
    );
    // Do NOT set name/length via OBJECT_PROPS — rely on InternalData

    let desc = call_get_own_property_descriptor(func, "name");
    assert!(
        desc.is_some(),
        "name descriptor should exist from InternalData"
    );
    let d = desc.unwrap();
    let val = read_desc_value(d);
    let val_str = crate::string_ops::get_string_data(JsValue::from_raw_bits(val));
    assert_eq!(
        val_str, "fallbackName",
        "should fall back to InternalData name"
    );
    assert_eq!(read_desc_bool(d, "writable"), Some(false));
    assert_eq!(read_desc_bool(d, "enumerable"), Some(false));
    assert_eq!(read_desc_bool(d, "configurable"), Some(true));
}

