#[test]
fn test_set_constructor_empty() {
    crate::exceptions::clear_exception();
    let set = unsafe { crate::rt_api::call_builtin_constructor("Set", 0, std::ptr::null()) };
    let size = crate::rt_api::dispatch_set_method(set, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size),
        JsValue::number(0.0),
        "new Set() should be empty"
    );
}

#[test]
fn test_set_constructor_from_array() {
    crate::exceptions::clear_exception();
    // Create [1, 2, 3]
    let arr = crate::rt_api::create_array_from_elements(vec![
        JsValue::int(1),
        JsValue::int(2),
        JsValue::int(3),
    ]);
    let args: [u64; 1] = [arr];
    let set = unsafe { crate::rt_api::call_builtin_constructor("Set", 1, args.as_ptr()) };
    let size = crate::rt_api::dispatch_set_method(set, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size),
        JsValue::number(3.0),
        "new Set([1,2,3]) should have size 3"
    );

    // has(1) should be true
    let has1 =
        crate::rt_api::dispatch_set_method(set, "has", 1, [JsValue::int(1).raw_bits()].as_ptr());
    assert_eq!(JsValue::from_raw_bits(has1), JsValue::bool(true));

    // has(4) should be false
    let has4 =
        crate::rt_api::dispatch_set_method(set, "has", 1, [JsValue::int(4).raw_bits()].as_ptr());
    assert_eq!(JsValue::from_raw_bits(has4), JsValue::bool(false));
}

