#[test]
fn test_set_constructor_from_another_set() {
    crate::exceptions::clear_exception();
    // Create first set with [10, 20]
    let arr = crate::rt_api::create_array_from_elements(vec![JsValue::int(10), JsValue::int(20)]);
    let args: [u64; 1] = [arr];
    let set1 = unsafe { crate::rt_api::call_builtin_constructor("Set", 1, args.as_ptr()) };

    // Create second set from first
    let args2: [u64; 1] = [set1];
    let set2 = unsafe { crate::rt_api::call_builtin_constructor("Set", 1, args2.as_ptr()) };

    let size = crate::rt_api::dispatch_set_method(set2, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size),
        JsValue::number(2.0),
        "new Set(otherSet) should copy values"
    );

    // Verify independence: adding to set2 shouldn't affect set1
    crate::rt_api::dispatch_set_method(set2, "add", 1, [JsValue::int(30).raw_bits()].as_ptr());
    let size1 = crate::rt_api::dispatch_set_method(set1, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size1),
        JsValue::number(2.0),
        "original set should not be affected"
    );
}

