// -------------------------------------------------------------------------
// Set ES2025 methods: union, intersection, difference, symmetricDifference,
// isSubsetOf, isSupersetOf, isDisjointFrom
// -------------------------------------------------------------------------

/// Helper: create a Set from an array of integer values.
fn create_set_with_ints(ints: &[i32]) -> u64 {
    let set = crate::rt_api::__esc_rt_create_set();
    for &i in ints {
        crate::rt_api::dispatch_set_method(set, "add", 1, [JsValue::int(i).raw_bits()].as_ptr());
    }
    set
}

#[test]
fn test_set_union() {
    crate::exceptions::clear_exception();
    let a = create_set_with_ints(&[1, 2, 3]);
    let b = create_set_with_ints(&[3, 4, 5]);
    let result = crate::rt_api::dispatch_set_method(a, "union", 1, [b].as_ptr());
    let size = crate::rt_api::dispatch_set_method(result, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size),
        JsValue::number(5.0),
        "union of {{1,2,3}} and {{3,4,5}} should have 5 elements"
    );
    // Verify element presence
    for i in 1..=5 {
        let has = crate::rt_api::dispatch_set_method(
            result,
            "has",
            1,
            [JsValue::int(i).raw_bits()].as_ptr(),
        );
        assert_eq!(
            JsValue::from_raw_bits(has),
            JsValue::bool(true),
            "union should contain {}",
            i
        );
    }
}

#[test]
fn test_set_intersection() {
    crate::exceptions::clear_exception();
    let a = create_set_with_ints(&[1, 2, 3, 4]);
    let b = create_set_with_ints(&[3, 4, 5, 6]);
    let result = crate::rt_api::dispatch_set_method(a, "intersection", 1, [b].as_ptr());
    let size = crate::rt_api::dispatch_set_method(result, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size),
        JsValue::number(2.0),
        "intersection of {{1,2,3,4}} and {{3,4,5,6}} should have 2 elements"
    );
    let has3 =
        crate::rt_api::dispatch_set_method(result, "has", 1, [JsValue::int(3).raw_bits()].as_ptr());
    assert_eq!(JsValue::from_raw_bits(has3), JsValue::bool(true));
    let has4 =
        crate::rt_api::dispatch_set_method(result, "has", 1, [JsValue::int(4).raw_bits()].as_ptr());
    assert_eq!(JsValue::from_raw_bits(has4), JsValue::bool(true));
    let has1 =
        crate::rt_api::dispatch_set_method(result, "has", 1, [JsValue::int(1).raw_bits()].as_ptr());
    assert_eq!(JsValue::from_raw_bits(has1), JsValue::bool(false));
}

#[test]
fn test_set_difference() {
    crate::exceptions::clear_exception();
    let a = create_set_with_ints(&[1, 2, 3, 4]);
    let b = create_set_with_ints(&[3, 4, 5]);
    let result = crate::rt_api::dispatch_set_method(a, "difference", 1, [b].as_ptr());
    let size = crate::rt_api::dispatch_set_method(result, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size),
        JsValue::number(2.0),
        "difference of {{1,2,3,4}} and {{3,4,5}} should have {{1,2}}"
    );
    let has1 =
        crate::rt_api::dispatch_set_method(result, "has", 1, [JsValue::int(1).raw_bits()].as_ptr());
    assert_eq!(JsValue::from_raw_bits(has1), JsValue::bool(true));
    let has3 =
        crate::rt_api::dispatch_set_method(result, "has", 1, [JsValue::int(3).raw_bits()].as_ptr());
    assert_eq!(JsValue::from_raw_bits(has3), JsValue::bool(false));
}

#[test]
fn test_set_symmetric_difference() {
    crate::exceptions::clear_exception();
    let a = create_set_with_ints(&[1, 2, 3]);
    let b = create_set_with_ints(&[2, 3, 4]);
    let result = crate::rt_api::dispatch_set_method(a, "symmetricDifference", 1, [b].as_ptr());
    let size = crate::rt_api::dispatch_set_method(result, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size),
        JsValue::number(2.0),
        "symmetricDifference of {{1,2,3}} and {{2,3,4}} should have {{1,4}}"
    );
    let has1 =
        crate::rt_api::dispatch_set_method(result, "has", 1, [JsValue::int(1).raw_bits()].as_ptr());
    assert_eq!(JsValue::from_raw_bits(has1), JsValue::bool(true));
    let has4 =
        crate::rt_api::dispatch_set_method(result, "has", 1, [JsValue::int(4).raw_bits()].as_ptr());
    assert_eq!(JsValue::from_raw_bits(has4), JsValue::bool(true));
    let has2 =
        crate::rt_api::dispatch_set_method(result, "has", 1, [JsValue::int(2).raw_bits()].as_ptr());
    assert_eq!(JsValue::from_raw_bits(has2), JsValue::bool(false));
}

