#[test]
fn test_map_constructor_from_array_of_pairs() {
    crate::exceptions::clear_exception();
    // Create [["a", 1], ["b", 2]]
    let pair1 = crate::rt_api::create_array_from_elements(vec![
        JsValue::from_raw_bits(crate::rt_api::make_rt_string("a".to_string())),
        JsValue::int(1),
    ]);
    let pair2 = crate::rt_api::create_array_from_elements(vec![
        JsValue::from_raw_bits(crate::rt_api::make_rt_string("b".to_string())),
        JsValue::int(2),
    ]);
    let arr = crate::rt_api::create_array_from_elements(vec![
        JsValue::from_raw_bits(pair1),
        JsValue::from_raw_bits(pair2),
    ]);
    let args: [u64; 1] = [arr];
    let map = unsafe { crate::rt_api::call_builtin_constructor("Map", 1, args.as_ptr()) };
    assert!(
        !crate::exceptions::is_exception(),
        "new Map([...pairs]) should not throw"
    );

    // size should be 2
    let size = crate::rt_api::dispatch_map_method(map, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size),
        JsValue::number(2.0),
        "Map should have 2 entries"
    );

    // get("a") should return 1
    let key_a = crate::rt_api::make_rt_string("a".to_string());
    let r = crate::rt_api::dispatch_map_method(map, "get", 1, [key_a].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(r).as_int(),
        Some(1),
        "Map.get('a') should be 1"
    );
}

#[test]
fn test_map_constructor_from_another_map() {
    crate::exceptions::clear_exception();
    let map1 = crate::rt_api::__esc_rt_create_map();
    let k = crate::rt_api::make_rt_string("x".to_string());
    let v = JsValue::int(99).raw_bits();
    crate::rt_api::dispatch_map_method(map1, "set", 2, [k, v].as_ptr());

    // Create map2 from map1
    let args: [u64; 1] = [map1];
    let map2 = unsafe { crate::rt_api::call_builtin_constructor("Map", 1, args.as_ptr()) };

    let size = crate::rt_api::dispatch_map_method(map2, "size", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(size),
        JsValue::number(1.0),
        "new Map(otherMap) should copy entries"
    );
    let r = crate::rt_api::dispatch_map_method(map2, "get", 1, [k].as_ptr());
    assert_eq!(
        JsValue::from_raw_bits(r).as_int(),
        Some(99),
        "copied Map should have same entries"
    );
}

