// 245. test_date_epoch
#[test]
fn test_date_epoch() {
    // Epoch (0ms) should be 1970-01-01T00:00:00.000Z
    let args: [u64; 1] = [JsValue::number(0.0).raw_bits()];
    let date = unsafe { crate::rt_api::call_builtin_constructor("Date", 1, args.as_ptr()) };
    let year = crate::rt_api::dispatch_date_method(date, "getUTCFullYear", 0, std::ptr::null());
    let month = crate::rt_api::dispatch_date_method(date, "getUTCMonth", 0, std::ptr::null());
    let day = crate::rt_api::dispatch_date_method(date, "getUTCDate", 0, std::ptr::null());
    let hours = crate::rt_api::dispatch_date_method(date, "getUTCHours", 0, std::ptr::null());
    let min = crate::rt_api::dispatch_date_method(date, "getUTCMinutes", 0, std::ptr::null());
    let sec = crate::rt_api::dispatch_date_method(date, "getUTCSeconds", 0, std::ptr::null());
    let ms = crate::rt_api::dispatch_date_method(date, "getUTCMilliseconds", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(year).as_number().unwrap_or(-1.0),
        1970.0
    );
    assert_eq!(
        JsValue::from_raw_bits(month).as_number().unwrap_or(-1.0),
        0.0
    );
    assert_eq!(JsValue::from_raw_bits(day).as_number().unwrap_or(-1.0), 1.0);
    assert_eq!(
        JsValue::from_raw_bits(hours).as_number().unwrap_or(-1.0),
        0.0
    );
    assert_eq!(JsValue::from_raw_bits(min).as_number().unwrap_or(-1.0), 0.0);
    assert_eq!(JsValue::from_raw_bits(sec).as_number().unwrap_or(-1.0), 0.0);
    assert_eq!(JsValue::from_raw_bits(ms).as_number().unwrap_or(-1.0), 0.0);
}

