// 255. test_date_set_full_year_with_month_overflow
#[test]
fn test_date_set_full_year_with_month_overflow() {
    // Start with 2024-01-01
    let ts = crate::rt_api::make_date_from_components(&[
        JsValue::number(2024.0),
        JsValue::number(0.0), // Jan
        JsValue::number(1.0),
    ]);
    let date_args: [u64; 1] = [JsValue::number(ts).raw_bits()];
    let date = unsafe { crate::rt_api::call_builtin_constructor("Date", 1, date_args.as_ptr()) };
    // setUTCFullYear(2025, 12) => month 12 overflows to January next year
    let set_args: [u64; 2] = [
        JsValue::number(2025.0).raw_bits(),
        JsValue::number(12.0).raw_bits(),
    ];
    crate::rt_api::dispatch_date_method(date, "setUTCFullYear", 2, set_args.as_ptr());
    let year = crate::rt_api::dispatch_date_method(date, "getUTCFullYear", 0, std::ptr::null());
    let month = crate::rt_api::dispatch_date_method(date, "getUTCMonth", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(year).as_number().unwrap_or(-1.0),
        2026.0
    );
    assert_eq!(
        JsValue::from_raw_bits(month).as_number().unwrap_or(-1.0),
        0.0 // January
    );
}

