// 258. test_date_local_getters_work_like_utc_in_test
#[test]
fn test_date_local_getters_work_like_utc_in_test() {
    // Since local_tz_offset_ms returns 0 in test mode, local and UTC should match
    let args: [u64; 1] = [JsValue::number(1_718_452_800_000.0).raw_bits()];
    let date = unsafe { crate::rt_api::call_builtin_constructor("Date", 1, args.as_ptr()) };
    let utc_year = crate::rt_api::dispatch_date_method(date, "getUTCFullYear", 0, std::ptr::null());
    let local_year = crate::rt_api::dispatch_date_method(date, "getFullYear", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(utc_year).as_number().unwrap_or(-1.0),
        JsValue::from_raw_bits(local_year)
            .as_number()
            .unwrap_or(-2.0),
        "In UTC test mode, local and UTC year should match"
    );
}

