// 261. test_date_set_utc_seconds_with_ms
#[test]
fn test_date_set_utc_seconds_with_ms() {
    let args: [u64; 1] = [JsValue::number(0.0).raw_bits()];
    let date = unsafe { crate::rt_api::call_builtin_constructor("Date", 1, args.as_ptr()) };
    // setUTCSeconds(30, 500) — sets both seconds and milliseconds
    let set_args: [u64; 2] = [
        JsValue::number(30.0).raw_bits(),
        JsValue::number(500.0).raw_bits(),
    ];
    crate::rt_api::dispatch_date_method(date, "setUTCSeconds", 2, set_args.as_ptr());
    let sec = crate::rt_api::dispatch_date_method(date, "getUTCSeconds", 0, std::ptr::null());
    let ms = crate::rt_api::dispatch_date_method(date, "getUTCMilliseconds", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(sec).as_number().unwrap_or(-1.0),
        30.0
    );
    assert_eq!(
        JsValue::from_raw_bits(ms).as_number().unwrap_or(-1.0),
        500.0
    );
}

// 262. test_date_constructor_with_all_components
#[test]
fn test_date_constructor_with_all_components() {
    // new Date(2024, 5, 15, 12, 30, 45, 123) = 2024-06-15T12:30:45.123
    let args: [u64; 7] = [
        JsValue::number(2024.0).raw_bits(),
        JsValue::number(5.0).raw_bits(), // June
        JsValue::number(15.0).raw_bits(),
        JsValue::number(12.0).raw_bits(),
        JsValue::number(30.0).raw_bits(),
        JsValue::number(45.0).raw_bits(),
        JsValue::number(123.0).raw_bits(),
    ];
    let date = unsafe { crate::rt_api::call_builtin_constructor("Date", 7, args.as_ptr()) };
    let year = crate::rt_api::dispatch_date_method(date, "getUTCFullYear", 0, std::ptr::null());
    let month = crate::rt_api::dispatch_date_method(date, "getUTCMonth", 0, std::ptr::null());
    let day = crate::rt_api::dispatch_date_method(date, "getUTCDate", 0, std::ptr::null());
    let hours = crate::rt_api::dispatch_date_method(date, "getUTCHours", 0, std::ptr::null());
    let min = crate::rt_api::dispatch_date_method(date, "getUTCMinutes", 0, std::ptr::null());
    let sec = crate::rt_api::dispatch_date_method(date, "getUTCSeconds", 0, std::ptr::null());
    let ms_val =
        crate::rt_api::dispatch_date_method(date, "getUTCMilliseconds", 0, std::ptr::null());
    assert_eq!(
        JsValue::from_raw_bits(year).as_number().unwrap_or(-1.0),
        2024.0
    );
    assert_eq!(
        JsValue::from_raw_bits(month).as_number().unwrap_or(-1.0),
        5.0
    );
    assert_eq!(
        JsValue::from_raw_bits(day).as_number().unwrap_or(-1.0),
        15.0
    );
    assert_eq!(
        JsValue::from_raw_bits(hours).as_number().unwrap_or(-1.0),
        12.0
    );
    assert_eq!(
        JsValue::from_raw_bits(min).as_number().unwrap_or(-1.0),
        30.0
    );
    assert_eq!(
        JsValue::from_raw_bits(sec).as_number().unwrap_or(-1.0),
        45.0
    );
    assert_eq!(
        JsValue::from_raw_bits(ms_val).as_number().unwrap_or(-1.0),
        123.0
    );
}

