#[test]
fn test_new_boolean_wrapper_creation() {
    use crate::internal_data::{InternalKind, UnifiedObject};
    use crate::tagged_obj::{ObjTag, TaggedObj};

    let val = JsValue::bool(true).raw_bits();
    let obj = UnifiedObject::boolean_wrapper(ShapeTable::EMPTY_SHAPE, val);
    assert_eq!(obj.kind, InternalKind::BooleanObj);
    assert!(obj.internal.is_some());

    let bits = TaggedObj::boxed(ObjTag::Unified, obj);
    let uobj = unsafe { crate::tagged_obj::deref_tagged::<UnifiedObject>(bits) };
    assert!(uobj.is_some());
    let uobj = uobj.unwrap();
    assert_eq!(uobj.kind, InternalKind::BooleanObj);
}

