#[test]
fn test_string_wrapper_has_indexed_chars() {
    use crate::internal_data::{ElementsStorage, UnifiedObject};

    let val = make_string_value("abc");
    let obj = UnifiedObject::string_wrapper(ShapeTable::EMPTY_SHAPE, val);

    // Should have 3 dense elements
    match &obj.elements {
        ElementsStorage::Dense(elems) => {
            assert_eq!(elems.len(), 3, "should have 3 character elements");
            // Check that each element is a string
            for elem in elems {
                assert!(elem.is_string(), "each element should be a string");
            }
            // Verify actual character values
            let ch0 = crate::string_ops::get_string_data(elems[0]);
            let ch1 = crate::string_ops::get_string_data(elems[1]);
            let ch2 = crate::string_ops::get_string_data(elems[2]);
            assert_eq!(ch0, "a");
            assert_eq!(ch1, "b");
            assert_eq!(ch2, "c");
        }
        other => panic!("expected Dense elements, got {:?}", other),
    }
}

