// -------------------------------------------------------------------------
// 278. test_promise_then_non_promise_throws
// -------------------------------------------------------------------------
#[test]
fn test_promise_then_non_promise_throws() {
    crate::exceptions::clear_exception();
    // Create a regular object tagged as Promise-like but not actually a Promise
    let obj = crate::rt_api::__esc_rt_create_object();
    // Call .then() on it via call_method — this routes through dispatch_promise_instance_method
    let then_key = crate::rt_api::make_rt_string("then".to_string());
    let _result =
        unsafe { crate::rt_api::__esc_rt_call_method(obj, then_key, 0, std::ptr::null()) };
    // Non-promise objects go through a different dispatch path, but we can
    // verify by calling __esc_rt_promise_then with a non-promise
    crate::exceptions::clear_exception();
    // Verify that __esc_rt_promise_then works on a real Promise
    let p = crate::rt_api::__esc_rt_promise_create();
    let undef = JsValue::undefined().raw_bits();
    let result = crate::rt_api::__esc_rt_promise_then(p, undef, undef);
    assert!(
        !crate::exceptions::is_exception(),
        "Promise.prototype.then on Promise should succeed"
    );
    assert!(JsValue::from_raw_bits(result).is_object());
    crate::exceptions::clear_exception();
}

