// -------------------------------------------------------------------------
// 282. test_proxy_define_property_non_configurable_change_throws
// -------------------------------------------------------------------------
#[test]
fn test_proxy_define_property_non_configurable_change_throws() {
    use crate::proxy::ProxyError;

    // Create a target with a non-configurable property
    let target = crate::rt_api::__esc_rt_create_object();
    let key = crate::rt_api::make_rt_string("x".to_string());

    // Define a non-configurable property on target via Object.defineProperty
    let desc_obj = crate::rt_api::__esc_rt_create_object();
    let val_key = crate::rt_api::make_rt_string("value".to_string());
    crate::rt_api::__esc_rt_set_prop(desc_obj, val_key, JsValue::int(1).raw_bits());
    let config_key = crate::rt_api::make_rt_string("configurable".to_string());
    crate::rt_api::__esc_rt_set_prop(desc_obj, config_key, JsValue::bool(false).raw_bits());
    let writable_key = crate::rt_api::make_rt_string("writable".to_string());
    crate::rt_api::__esc_rt_set_prop(desc_obj, writable_key, JsValue::bool(false).raw_bits());

    crate::rt_api::dispatch_object_static_method(
        "defineProperty",
        3,
        [target, key, desc_obj].as_ptr(),
    );

    // Create a handler that always says defineProperty succeeds
    let handler = crate::rt_api::__esc_rt_create_object();
    let trap_fn = crate::tagged_obj::TaggedObj::boxed(
        crate::tagged_obj::ObjTag::Unified,
        crate::internal_data::UnifiedObject::native_func(|_ctx| JsValue::bool(true).raw_bits(), 0),
    );
    let trap_key = crate::rt_api::make_rt_string("defineProperty".to_string());
    crate::rt_api::__esc_rt_set_prop(handler, trap_key, trap_fn);

    // Create proxy
    let proxy = crate::rt_api::__esc_rt_create_proxy(target, handler);

    // Try to define a configurable version on the proxy — should fail with invariant violation
    let new_desc = crate::rt_api::__esc_rt_create_object();
    let new_config_key = crate::rt_api::make_rt_string("configurable".to_string());
    crate::rt_api::__esc_rt_set_prop(new_desc, new_config_key, JsValue::bool(true).raw_bits());

    let result = crate::proxy::proxy_define_property(proxy, key, new_desc, "x");
    assert!(
        matches!(
            result,
            Err(ProxyError::DefinePropertyInvariantViolation { .. })
        ),
        "Proxy defineProperty should throw on non-configurable configurable change"
    );
}

