fn test_proxy_get_own_property_descriptor_trap_returns_string_throws() {
    use crate::proxy::ProxyError;

    // Step 9: If trap result is not Object and not undefined, throw TypeError
    let target = crate::rt_api::__esc_rt_create_object();
    let handler = crate::rt_api::__esc_rt_create_object();

    // Trap that returns a string instead of an object/undefined
    let trap_fn = crate::tagged_obj::TaggedObj::boxed(
        crate::tagged_obj::ObjTag::Unified,
        crate::internal_data::UnifiedObject::native_func(
            |_ctx| crate::rt_api::make_rt_string("bad result".to_string()),
            0,
        ),
    );
    let trap_key = crate::rt_api::make_rt_string("getOwnPropertyDescriptor".to_string());
    crate::rt_api::__esc_rt_set_prop(handler, trap_key, trap_fn);

    let proxy = crate::rt_api::__esc_rt_create_proxy(target, handler);
    let key = crate::rt_api::make_rt_string("x".to_string());

    let result = crate::proxy::proxy_get_own_property_descriptor(proxy, key, "x");
    assert!(
        matches!(result, Err(ProxyError::InvalidTrapResult { .. })),
        "getOwnPropertyDescriptor trap returning string should throw TypeError"
    );
}

