#[test]
fn test_proxy_own_keys_non_extensible_extra_key_throws() {
    use crate::proxy::ProxyError;

    // Create target with property "x" and freeze it (make non-extensible)
    let target = crate::rt_api::__esc_rt_create_object();
    let x_key = crate::rt_api::make_rt_string("x".to_string());
    crate::rt_api::__esc_rt_set_prop(target, x_key, JsValue::int(1).raw_bits());

    // Freeze the target to make it non-extensible
    crate::rt_api::dispatch_object_static_method("freeze", 1, [target].as_ptr());

    // Handler ownKeys trap returns ["x", "extra"] — "extra" is not on target
    let handler = crate::rt_api::__esc_rt_create_object();
    let trap_fn = crate::tagged_obj::TaggedObj::boxed(
        crate::tagged_obj::ObjTag::Unified,
        crate::internal_data::UnifiedObject::native_func(
            |_ctx| {
                let arr = crate::rt_api::__esc_rt_create_empty_array(0);
                crate::rt_api::__esc_rt_array_push(
                    arr,
                    crate::rt_api::make_rt_string("x".to_string()),
                );
                crate::rt_api::__esc_rt_array_push(
                    arr,
                    crate::rt_api::make_rt_string("extra".to_string()),
                );
                arr
            },
            0,
        ),
    );
    let trap_key = crate::rt_api::make_rt_string("ownKeys".to_string());
    crate::rt_api::__esc_rt_set_prop(handler, trap_key, trap_fn);

    let proxy = crate::rt_api::__esc_rt_create_proxy(target, handler);
    let result = crate::proxy::proxy_own_keys(proxy);
    assert!(
        matches!(result, Err(ProxyError::OwnKeysNonExtensibleExtra)),
        "ownKeys trap adding extra key on non-extensible target should throw TypeError"
    );
}

