// 277. test_object_create_with_properties
#[test]
fn test_object_create_with_properties() {
    crate::exceptions::clear_exception();

    // Build properties object: { x: { value: 42, writable: true, enumerable: true, configurable: true } }
    let props = crate::rt_api::__esc_rt_create_object();
    let x_desc = crate::rt_api::__esc_rt_create_object();

    let value_key = crate::rt_api::make_rt_string("value".to_string());
    let writable_key = crate::rt_api::make_rt_string("writable".to_string());
    let enumerable_key = crate::rt_api::make_rt_string("enumerable".to_string());
    let configurable_key = crate::rt_api::make_rt_string("configurable".to_string());

    crate::rt_api::__esc_rt_set_prop(x_desc, value_key, JsValue::int(42).raw_bits());
    crate::rt_api::__esc_rt_set_prop(x_desc, writable_key, JsValue::bool(true).raw_bits());
    crate::rt_api::__esc_rt_set_prop(x_desc, enumerable_key, JsValue::bool(true).raw_bits());
    crate::rt_api::__esc_rt_set_prop(x_desc, configurable_key, JsValue::bool(true).raw_bits());

    let x_key = crate::rt_api::make_rt_string("x".to_string());
    crate::rt_api::__esc_rt_set_prop(props, x_key, x_desc);

    // Object.create(null, props) should create object with property x = 42
    let argv: [u64; 2] = [JsValue::null().raw_bits(), props];
    let result = crate::rt_api::dispatch_object_static_method("create", 2, argv.as_ptr());

    assert!(result.is_some(), "Object.create should return an object");
    assert!(
        !crate::exceptions::is_exception(),
        "Object.create(null, props) should not throw"
    );

    // Verify the property was defined
    let obj = result.unwrap();
    let x_key2 = crate::rt_api::make_rt_string("x".to_string());
    let val = crate::rt_api::__esc_rt_get_prop(obj, x_key2);
    assert_eq!(
        JsValue::from_raw_bits(val).as_int(),
        Some(42),
        "Object.create should define properties from second argument"
    );
    crate::exceptions::clear_exception();
}

