// 294. test_to_property_descriptor_boolean_coercion
#[test]
fn test_to_property_descriptor_boolean_coercion() {
    crate::exceptions::clear_exception();

    let obj = crate::rt_api::__esc_rt_create_object();
    let prop_key = crate::rt_api::make_rt_string("x".to_string());

    // Build descriptor with writable = 0 (falsy), enumerable = 1 (truthy),
    // configurable = "" (falsy)
    let desc = crate::rt_api::__esc_rt_create_object();
    let vk = crate::rt_api::make_rt_string("value".to_string());
    let wk = crate::rt_api::make_rt_string("writable".to_string());
    let ek = crate::rt_api::make_rt_string("enumerable".to_string());
    let ck = crate::rt_api::make_rt_string("configurable".to_string());

    crate::rt_api::__esc_rt_set_prop(desc, vk, JsValue::int(42).raw_bits());
    crate::rt_api::__esc_rt_set_prop(desc, wk, JsValue::int(0).raw_bits());
    crate::rt_api::__esc_rt_set_prop(desc, ek, JsValue::int(1).raw_bits());
    crate::rt_api::__esc_rt_set_prop(desc, ck, JsValue::bool(false).raw_bits());

    let argv: [u64; 3] = [obj, prop_key, desc];
    crate::rt_api::dispatch_object_static_method("defineProperty", 3, argv.as_ptr());

    assert!(
        !crate::exceptions::is_exception(),
        "defineProperty with truthy/falsy descriptor flags should not throw"
    );

    // Verify descriptor: get the descriptor back
    let argv_get: [u64; 2] = [obj, crate::rt_api::make_rt_string("x".to_string())];
    let result = crate::rt_api::dispatch_object_static_method(
        "getOwnPropertyDescriptor",
        2,
        argv_get.as_ptr(),
    );
    assert!(
        result.is_some(),
        "getOwnPropertyDescriptor should return a value"
    );

    let desc_obj = result.unwrap();
    let w_key = crate::rt_api::make_rt_string("writable".to_string());
    let w_val = crate::rt_api::__esc_rt_get_prop(desc_obj, w_key);
    assert_eq!(
        JsValue::from_raw_bits(w_val).as_bool(),
        Some(false),
        "writable should be false (coerced from 0)"
    );

    let e_key = crate::rt_api::make_rt_string("enumerable".to_string());
    let e_val = crate::rt_api::__esc_rt_get_prop(desc_obj, e_key);
    assert_eq!(
        JsValue::from_raw_bits(e_val).as_bool(),
        Some(true),
        "enumerable should be true (coerced from 1)"
    );

    crate::exceptions::clear_exception();
}

// --- defineProperties ordering test ---

// 295. test_define_properties_ordering
#[test]
fn test_define_properties_ordering() {
    crate::exceptions::clear_exception();

    // Create a target object
    let obj = crate::rt_api::__esc_rt_create_object();

    // Create properties object with two property descriptors
    let props = crate::rt_api::__esc_rt_create_object();

    // First property: a
    let a_desc = crate::rt_api::__esc_rt_create_object();
    let vk = crate::rt_api::make_rt_string("value".to_string());
    crate::rt_api::__esc_rt_set_prop(a_desc, vk, JsValue::int(1).raw_bits());
    let wk2 = crate::rt_api::make_rt_string("writable".to_string());
    crate::rt_api::__esc_rt_set_prop(a_desc, wk2, JsValue::bool(true).raw_bits());
    let ek2 = crate::rt_api::make_rt_string("enumerable".to_string());
    crate::rt_api::__esc_rt_set_prop(a_desc, ek2, JsValue::bool(true).raw_bits());
    let ck2 = crate::rt_api::make_rt_string("configurable".to_string());
    crate::rt_api::__esc_rt_set_prop(a_desc, ck2, JsValue::bool(true).raw_bits());

    // Second property: b
    let b_desc = crate::rt_api::__esc_rt_create_object();
    let vk3 = crate::rt_api::make_rt_string("value".to_string());
    crate::rt_api::__esc_rt_set_prop(b_desc, vk3, JsValue::int(2).raw_bits());
    let wk3 = crate::rt_api::make_rt_string("writable".to_string());
    crate::rt_api::__esc_rt_set_prop(b_desc, wk3, JsValue::bool(true).raw_bits());
    let ek3 = crate::rt_api::make_rt_string("enumerable".to_string());
    crate::rt_api::__esc_rt_set_prop(b_desc, ek3, JsValue::bool(true).raw_bits());
    let ck3 = crate::rt_api::make_rt_string("configurable".to_string());
    crate::rt_api::__esc_rt_set_prop(b_desc, ck3, JsValue::bool(true).raw_bits());

    let ak = crate::rt_api::make_rt_string("a".to_string());
    let bk = crate::rt_api::make_rt_string("b".to_string());
    crate::rt_api::__esc_rt_set_prop(props, ak, a_desc);
    crate::rt_api::__esc_rt_set_prop(props, bk, b_desc);

    let argv: [u64; 2] = [obj, props];
    let result = crate::rt_api::dispatch_object_static_method("defineProperties", 2, argv.as_ptr());

    assert!(result.is_some(), "defineProperties should return a value");
    assert!(
        !crate::exceptions::is_exception(),
        "defineProperties should not throw"
    );

    // Verify both properties are defined
    let a_val =
        crate::rt_api::__esc_rt_get_prop(obj, crate::rt_api::make_rt_string("a".to_string()));
    assert_eq!(
        JsValue::from_raw_bits(a_val).as_int(),
        Some(1),
        "property a should be 1"
    );
    let b_val =
        crate::rt_api::__esc_rt_get_prop(obj, crate::rt_api::make_rt_string("b".to_string()));
    assert_eq!(
        JsValue::from_raw_bits(b_val).as_int(),
        Some(2),
        "property b should be 2"
    );
    crate::exceptions::clear_exception();
}

// --- Delete non-configurable property tests ---

// 296. test_delete_non_configurable_returns_false
#[test]
fn test_delete_non_configurable_returns_false() {
    let interner = Interner::new();
    let mut shapes = ShapeTable::new();
    let mut obj = JsObject::new(ShapeTable::EMPTY_SHAPE, 3);

    // Define a non-configurable property
    let opts = property::DefinePropertyOptions {
        value: Some(JsValue::int(42)),
        writable: Some(true),
        enumerable: Some(true),
        configurable: Some(false),
        getter: None,
        setter: None,
    };
    property::define_property(&mut obj, "x", &opts, &mut shapes, &interner).unwrap();

    // delete should return false for non-configurable
    let deleted = property::delete_property(&mut obj, "x", &shapes, &interner);
    assert!(
        !deleted,
        "delete_property should return false for non-configurable property"
    );

    // Property value should still be accessible
    let val = property::get_property(&obj, "x", &shapes, &interner);
    assert_eq!(
        val.map(|v| v.as_int()),
        Some(Some(42)),
        "non-configurable property should still exist after failed delete"
    );
}

