#[test]
fn test_delete_non_configurable_unified_returns_false() {
    crate::exceptions::clear_exception();

    let obj = crate::rt_api::__esc_rt_create_object();
    let prop_key = crate::rt_api::make_rt_string("x".to_string());

    // Define non-configurable property via Object.defineProperty
    let desc = crate::rt_api::__esc_rt_create_object();
    let vk = crate::rt_api::make_rt_string("value".to_string());
    let ck = crate::rt_api::make_rt_string("configurable".to_string());
    crate::rt_api::__esc_rt_set_prop(desc, vk, JsValue::int(42).raw_bits());
    crate::rt_api::__esc_rt_set_prop(desc, ck, JsValue::bool(false).raw_bits());

    let dp_argv: [u64; 3] = [obj, prop_key, desc];
    crate::rt_api::dispatch_object_static_method("defineProperty", 3, dp_argv.as_ptr());
    assert!(
        !crate::exceptions::is_exception(),
        "defineProperty should not throw"
    );

    // Now try to delete the non-configurable property
    let del_key = crate::rt_api::make_rt_string("x".to_string());
    let deleted_bits = crate::rt_api::__esc_rt_delete_prop(obj, del_key);
    let deleted = JsValue::from_raw_bits(deleted_bits);

    // In sloppy mode, delete on non-configurable returns false
    assert_eq!(
        deleted.as_bool(),
        Some(false),
        "delete of non-configurable property should return false"
    );
    crate::exceptions::clear_exception();
}

