// 305. test_object_keys_on_object_works
#[test]
fn test_object_keys_on_object_works() {
    crate::exceptions::clear_exception();

    let obj = crate::rt_api::__esc_rt_create_object();
    let k = crate::rt_api::make_rt_string("a".to_string());
    crate::rt_api::__esc_rt_set_prop(obj, k, JsValue::int(1).raw_bits());

    let argv: [u64; 1] = [obj];
    let result = crate::rt_api::dispatch_object_static_method("keys", 1, argv.as_ptr());

    assert!(result.is_some(), "Object.keys should return a value");
    assert!(
        !crate::exceptions::is_exception(),
        "Object.keys on object should not throw"
    );

    // Verify it returns an array with "a"
    let arr_bits = result.unwrap();
    let arr = unsafe { crate::tagged_obj::deref_tagged::<UnifiedObject>(arr_bits) };
    assert!(arr.is_some(), "result should be a UnifiedObject");
    let arr = arr.unwrap();
    assert_eq!(arr.array_len(), 1, "Object.keys should return 1 key");
    crate::exceptions::clear_exception();
}

