// 320. test_array_registration_has_all_instance_methods
#[test]
fn test_array_registration_has_all_instance_methods() {
    let reg = crate::builtin_builder::get_registration("Array").unwrap();
    let names = reg.instance_method_names();
    // Verify all expected Array instance methods are present
    let expected = [
        "concat",
        "copyWithin",
        "entries",
        "every",
        "fill",
        "filter",
        "find",
        "findIndex",
        "findLast",
        "findLastIndex",
        "flat",
        "flatMap",
        "forEach",
        "includes",
        "indexOf",
        "join",
        "keys",
        "lastIndexOf",
        "map",
        "pop",
        "push",
        "reduce",
        "reduceRight",
        "reverse",
        "shift",
        "slice",
        "some",
        "sort",
        "splice",
        "toReversed",
        "toSorted",
        "toSpliced",
        "unshift",
        "values",
        "at",
        "toString",
    ];
    assert_eq!(
        names.len(),
        expected.len(),
        "Array instance method count mismatch: got {}, expected {}",
        names.len(),
        expected.len()
    );
    for method in &expected {
        assert!(
            names.contains(method),
            "Array instance method list missing: {method}"
        );
    }
}

