// 322. test_array_method_lengths_match_spec
#[test]
fn test_array_method_lengths_match_spec() {
    let reg = crate::builtin_builder::get_registration("Array").unwrap();
    // Static methods
    assert_eq!(reg.static_method_length("isArray"), Some(1));
    assert_eq!(reg.static_method_length("from"), Some(1));
    assert_eq!(reg.static_method_length("of"), Some(0));
    // Instance methods — spot-check key ones
    assert_eq!(reg.instance_method_length("push"), Some(1));
    assert_eq!(reg.instance_method_length("pop"), Some(0));
    assert_eq!(reg.instance_method_length("slice"), Some(2));
    assert_eq!(reg.instance_method_length("splice"), Some(2));
    assert_eq!(reg.instance_method_length("forEach"), Some(1));
    assert_eq!(reg.instance_method_length("indexOf"), Some(1));
    assert_eq!(reg.instance_method_length("toString"), Some(0));
    assert_eq!(reg.instance_method_length("reverse"), Some(0));
    assert_eq!(reg.instance_method_length("sort"), Some(1));
}

// 323. test_object_method_lengths_match_spec
#[test]
fn test_object_method_lengths_match_spec() {
    let reg = crate::builtin_builder::get_registration("Object").unwrap();
    // Static methods
    assert_eq!(reg.static_method_length("keys"), Some(1));
    assert_eq!(reg.static_method_length("assign"), Some(2));
    assert_eq!(reg.static_method_length("create"), Some(2));
    assert_eq!(reg.static_method_length("defineProperty"), Some(3));
    assert_eq!(reg.static_method_length("defineProperties"), Some(2));
    assert_eq!(reg.static_method_length("freeze"), Some(1));
    assert_eq!(reg.static_method_length("hasOwn"), Some(2));
    assert_eq!(reg.static_method_length("is"), Some(2));
    // Instance methods
    assert_eq!(reg.instance_method_length("toString"), Some(0));
    assert_eq!(reg.instance_method_length("valueOf"), Some(0));
    assert_eq!(reg.instance_method_length("hasOwnProperty"), Some(1));
}

